import{r as e}from"./jsx-runtime-BguD1OXD.js";import{n as t,t as n}from"./questions-prepare-BF5b4L-q.js";var r=[{id:`case-corrowmere`,company:`Corrowmere Seed Cooperative`,title:`Corrowmere Seed Cooperative: field sensors and seed orders`,summary:`A farming cooperative wants one analytics model that combines live soil-sensor data with seed orders, secured by region and released through a controlled lifecycle.`,environment:[`Soil-moisture sensors stream readings into an eventhouse with a KQL database named SensorDB, which already holds several months of data.`,`Seed orders are loaded into a warehouse named OrdersWH in the Operations workspace. The source system resends changed orders, so staging contains several versions of some orders.`,`Grower reference data lives in a lakehouse named AgronomyLH in a separate Research workspace that IT manages.`,`Regional sales targets are kept by analysts in a spreadsheet.`,`Semantic models connect to their data with a fixed identity, so report readers don’t need their own permissions on the underlying data.`,`The Operations workspace is connected to a GitHub repository, and a deployment pipeline moves content from Development to Test to Production.`],requirements:[`Agronomists must see hourly average soil moisture per field for the last week.`,`The semantic model must use sensor data, orders, and the regional targets together, with in-memory query performance.`,`Sensor data must not be copied into another store to make it available to the model.`,`Orders must be loaded once per order, using the latest version.`,`Regional managers, who are workspace Viewers, must see only their own region’s orders in reports.`,`Grower data from AgronomyLH must be joined with orders without copying it.`],constraints:[`Analysts can’t write to AgronomyLH or OrdersWH.`,`Changes merged in GitHub must reach the Development workspace before they are deployed onward.`]},{id:`case-brindlecombe`,company:`Brindlecombe Transit`,title:`Brindlecombe Transit: ridership and fares`,summary:`A city transit authority is scaling a large ridership model, adding live fare data, and tightening governance as more teams build on it.`,environment:[`A ridership semantic model in Import mode holds six years of tap-on events in a fact table partitioned by tap date.`,`The model is about 7 GB today and is expected to exceed 10 GB within a year. It is in a workspace on a Fabric F capacity.`,`Fare tables in a SQL source change every few minutes.`,`A stop dimension records stop names, and stops are sometimes renamed.`,`Model developers use Tabular Editor and DAX Studio through the XMLA endpoint.`,`The ridership data carries a Microsoft Purview sensitivity label with protection.`],requirements:[`Each refresh must reload only the last three days of taps while keeping six years of history.`,`Fare figures in reports must always be current, while stop and route dimensions stay fast to filter.`,`Trips must still show the stop name that was in use when the trip happened.`,`Planners must switch one chart between Boardings, Revenue, and On-time % with a slicer.`,`Before changing a column in the fares warehouse, owners of every dependent report must be warned.`],constraints:[`Developers can query the model from DAX Studio, but saving changes from Tabular Editor fails.`,`Some reports that depend on the fares warehouse live in other departments’ workspaces.`,`Data exports must keep the label’s protection.`]}],i=`case-corrowmere`,a=`case-brindlecombe`,ee=[{id:`CS5-01`,caseStudyId:i,machineId:`shared-spool`,bulletIds:[`P1.5`],format:`single`,difficulty:3,trapPairId:`onelake-availability-vs-integration`,stem:`Corrowmere’s semantic model must use the sensor readings in SensorDB, including the months already stored, without copying them into another store. What should you do?`,sources:[t.eventhouseOneLake,t.modelOneLake],options:[{id:`a`,text:`Turn on OneLake integration in the semantic model’s settings and refresh it`,explain:`Semantic model OneLake integration exports an Import model’s tables to OneLake; it doesn’t expose eventhouse data.`},{id:`b`,text:`Turn on OneLake availability for SensorDB and choose Apply to existing tables`,explain:`Correct. OneLake availability creates a logical Delta copy of KQL data, with no extra storage cost, that other engines such as Direct Lake can read; applying it to existing tables back-fills the stored months.`},{id:`c`,text:`Turn on OneLake availability for SensorDB at the database level only`,explain:`At database level only new tables are included unless you apply it to existing tables, so the stored readings would be missing.`},{id:`d`,text:`Copy the readings into OrdersWH with a pipeline every hour`,explain:`That copies the data, which the requirements rule out.`}],answer:`b`},{id:`CS5-02`,caseStudyId:i,machineId:`direct-lake-shuttle`,bulletIds:[`S2.4`],format:`single`,difficulty:3,trapPairId:`dl-onelake-vs-sql`,stem:`Corrowmere’s model must combine the SensorDB data (with OneLake availability on), tables from OrdersWH, and the analysts’ regional targets spreadsheet, with in-memory performance. Which storage design should you use?`,sources:[t.directLake,t.composite],options:[{id:`a`,text:`Direct Lake on SQL analytics endpoints over OrdersWH, with the targets as an Import table`,explain:`Direct Lake on SQL uses a single source item, doesn’t support KQL databases, and can’t mix storage modes in the same model.`},{id:`b`,text:`Import mode for every table, refreshed hourly`,explain:`Import copies the sensor data into the model, and Learn positions Direct Lake for large Fabric data already in Delta format.`},{id:`c`,text:`Direct Lake on OneLake for the sensor and order tables, with the targets added as an Import table`,explain:`Correct. Direct Lake on OneLake can use tables from more than one Fabric item, supports KQL databases with OneLake availability, and can be combined with Import tables.`},{id:`d`,text:`DirectQuery to SensorDB and OrdersWH, with the targets as an Import table`,explain:`DirectQuery sends every query to the sources, giving up the in-memory performance the requirement asks for.`}],answer:`c`},{id:`CS5-03`,caseStudyId:i,machineId:`tension-meter`,bulletIds:[`P3.3`],format:`dropdown`,difficulty:2,stem:`Corrowmere’s agronomists need hourly average soil moisture per field for the last week from SensorDB. Complete the KQL query.`,sources:[t.kqlSummarize,t.kqlBin,t.kqlWhere],language:`kql`,code:`SoilReadings
| [[1]] Timestamp > ago(7d)
| summarize AvgMoisture = [[2]](Moisture) by FieldId, [[3]](Timestamp, 1h)`,slots:[{id:`1`,options:[{id:`a`,text:`where`,explain:`Correct. where filters rows to the last seven days.`},{id:`b`,text:`project`,explain:`project chooses columns; it doesn’t filter rows.`},{id:`c`,text:`extend`,explain:`extend adds columns; it doesn’t filter rows.`}],answer:`a`},{id:`2`,options:[{id:`a`,text:`sum`,explain:`sum adds the readings instead of averaging them.`},{id:`b`,text:`dcount`,explain:`dcount counts distinct values.`},{id:`c`,text:`avg`,explain:`Correct. avg() returns the average for each group.`}],answer:`c`},{id:`3`,options:[{id:`a`,text:`ago`,explain:`ago() returns a point in time; it doesn’t group values.`},{id:`b`,text:`bin`,explain:`Correct. bin() groups timestamps into 1-hour ranges.`},{id:`c`,text:`take`,explain:`take is an operator that returns sample rows, not a grouping function.`}],answer:`b`}]},{id:`CS5-04`,caseStudyId:i,machineId:`carding-machine`,bulletIds:[`P2.7`],format:`single`,difficulty:2,trapPairId:`where-having-qualify`,stem:`Corrowmere’s staging.Orders table in OrdersWH holds several versions of some orders, each with a LoadedAt timestamp. Which T-SQL keeps only the latest version of each order?`,sources:[t.qualify],options:[{id:`a`,text:`SELECT * FROM staging.Orders WHERE ROW_NUMBER() OVER (PARTITION BY OrderID ORDER BY LoadedAt DESC) = 1`,explain:`WHERE runs before window functions, so it can’t reference ROW_NUMBER().`},{id:`b`,text:`SELECT * FROM staging.Orders QUALIFY ROW_NUMBER() OVER (PARTITION BY OrderID ORDER BY LoadedAt DESC) = 1`,explain:`Correct. QUALIFY filters after window functions are evaluated, so it keeps row 1 per order without a subquery.`},{id:`c`,text:`SELECT DISTINCT * FROM staging.Orders`,explain:`Versions differ in LoadedAt and other values, so DISTINCT keeps them all.`},{id:`d`,text:`SELECT OrderID, MAX(LoadedAt) FROM staging.Orders GROUP BY OrderID HAVING COUNT(*) > 1`,explain:`This returns only orders with several versions, and only two columns.`}],answer:`b`},{id:`CS5-05`,caseStudyId:i,machineId:`thread-sieves`,bulletIds:[`M1.3`],format:`single`,difficulty:3,stem:`Corrowmere’s regional managers are Viewers in the workspace and read reports built on the Direct Lake on OneLake model. Each must see only their own region’s orders. Where should the row filter be defined?`,sources:[t.modelRls,t.dlManage],options:[{id:`a`,text:`A row-level security security policy on the orders table in OrdersWH`,explain:`Direct Lake on OneLake doesn’t check permissions through the SQL analytics endpoint, so a SQL policy isn’t how this model filters rows.`},{id:`b`,text:`A filter on each report page`,explain:`Report filters aren’t security; users with access to the model can still query other regions.`},{id:`c`,text:`Object-level security on the Region column`,explain:`OLS hides objects such as columns; it doesn’t filter rows.`},{id:`d`,text:`A row-level security role in the semantic model whose filter keeps the manager’s region`,explain:`Correct. Semantic model RLS restricts users with Viewer permissions, which is what the managers are.`}],answer:`d`},{id:`CS5-06`,caseStudyId:i,machineId:`thread-intake`,bulletIds:[`P1.3`],format:`single`,difficulty:3,trapPairId:`shortcut-mirror-copy`,stem:`Corrowmere must join grower data from AgronomyLH (Research workspace) with orders in the Operations workspace, without copying it. Analysts can’t write to AgronomyLH. What should you create?`,sources:[t.shortcuts,t.queryWarehouse],options:[{id:`a`,text:`A cross-database query from OrdersWH to AgronomyLH using a three-part name`,explain:`Three-part names work only within the same workspace.`},{id:`b`,text:`A Copy job from AgronomyLH into OrdersWH`,explain:`A Copy job makes a copy, which the requirement rules out.`},{id:`c`,text:`A OneLake shortcut in a lakehouse in the Operations workspace that points to the AgronomyLH tables`,explain:`Correct. A shortcut references the data in place, needs no write access to the target, and can then be joined from the same workspace.`},{id:`d`,text:`Mirroring of AgronomyLH into the Operations workspace`,explain:`Mirroring replicates operational databases into OneLake; it isn’t used to reference another lakehouse.`}],answer:`c`},{id:`CS5-07`,caseStudyId:i,machineId:`pattern-ledger`,bulletIds:[`M2.1`],format:`single`,difficulty:2,trapPairId:`commit-vs-update`,stem:`A pull request that changes a pipeline definition was merged into the branch connected to Corrowmere’s Development workspace. The pipeline now shows Update required in the workspace. What should a developer do before deploying to Test?`,sources:[t.gitProcess],options:[{id:`a`,text:`Commit the workspace’s pipeline to the branch`,explain:`Commit sends workspace changes to Git and would try to overwrite the merged change.`},{id:`b`,text:`Update the workspace from Git`,explain:`Correct. Update brings the branch’s latest commit into the workspace, which is what Update required asks for.`},{id:`c`,text:`Disconnect and reconnect the workspace`,explain:`Reconnecting isn’t needed; Update applies the merged change.`},{id:`d`,text:`Deploy from Development to Test; the pipeline picks up the change automatically`,explain:`Deployment copies the workspace’s current item, which doesn’t yet include the merged change.`}],answer:`b`},{id:`CS6-01`,caseStudyId:a,machineId:`batch-winder`,bulletIds:[`S2.5`],format:`single`,difficulty:3,trapPairId:`archive-vs-refresh-period`,stem:`Brindlecombe’s tap fact table must keep six years of history while each refresh reloads only the last three days. Which incremental refresh setup meets the requirement?`,sources:[t.incrementalCfg,t.incremental],options:[{id:`a`,text:`Archive data starting 3 days before refresh date; incrementally refresh data starting 6 years before refresh date`,explain:`The periods are swapped: the archive period is how much history to keep, and the refresh period is what each refresh reloads.`},{id:`b`,text:`Filter TapDate >= RangeStart and TapDate <= RangeEnd; archive 6 years; refresh 3 days`,explain:`Equal-to on both parameters can put a boundary row in two partitions and duplicate data.`},{id:`c`,text:`Filter TapDate >= RangeStart and TapDate < RangeEnd; archive 6 years; refresh 3 days`,explain:`Correct. The filter uses equal-to on only one parameter, the archive period keeps six years, and the refresh period reloads the last three days.`},{id:`d`,text:`Two parameters named TapFrom and TapTo; archive 6 years; refresh 3 days`,explain:`Incremental refresh requires the reserved, case-sensitive names RangeStart and RangeEnd.`}],answer:`c`},{id:`CS6-02`,caseStudyId:a,machineId:`wide-beam`,bulletIds:[`S1.6`],format:`single`,difficulty:2,stem:`Brindlecombe’s ridership model will grow past 10 GB through refreshes in the service, and developers manage it through the XMLA endpoint. What should you configure?`,sources:[t.largeModels],options:[{id:`a`,text:`Large semantic model storage format for the model`,explain:`Correct. It is required for models beyond 10 GB and recommended for XMLA write operations.`},{id:`b`,text:`Switch the fact table to Direct Lake`,explain:`The model is an Import model fed by refreshes; switching modes isn’t what the size requirement asks.`},{id:`c`,text:`Publish the full history from Power BI Desktop`,explain:`Publishing from Desktop is capped at 10 GB; the model grows through refresh in the service.`},{id:`d`,text:`Move the workspace to Pro`,explain:`Pro workspaces don’t support XMLA write operations and don’t lift the size limit.`}],answer:`a`},{id:`CS6-03`,caseStudyId:a,machineId:`remote-loom-control`,bulletIds:[`M2.5`],format:`single`,difficulty:3,trapPairId:`xmla-read-vs-readwrite`,stem:`Brindlecombe’s developers can query the model from DAX Studio, but saving changes from Tabular Editor through the XMLA endpoint fails. The developers are workspace Contributors. What should be changed?`,sources:[t.xmla],options:[{id:`a`,text:`Give each developer Build permission on the model`,explain:`Contributors already have Write permission on models over XMLA; the endpoint setting is the blocker.`},{id:`b`,text:`Set the capacity’s XMLA Endpoint setting to Read Write`,explain:`Correct. Read-only is the default and allows queries; metadata changes such as Tabular Editor saves need Read Write, set for the capacity.`},{id:`c`,text:`Promote the developers to workspace Admin`,explain:`Contributors and above already have Write permission over XMLA, so the role isn’t the problem.`},{id:`d`,text:`Turn off large semantic model storage format`,explain:`Large format is recommended for XMLA writes; turning it off doesn’t enable them.`}],answer:`b`},{id:`CS6-04`,caseStudyId:a,machineId:`double-loom`,bulletIds:[`S1.7`],format:`single`,difficulty:3,trapPairId:`dual-vs-hybrid`,stem:`Brindlecombe adds the fare tables in DirectQuery so fare figures are always current. Stop and route dimensions come from the same SQL source and must stay fast to filter, with regular relationships to the fares. Which storage mode should the dimensions use?`,sources:[t.modes,t.composite],options:[{id:`a`,text:`Import`,explain:`Import dimensions sit in a different source group from DirectQuery facts, so the relationships would be limited.`},{id:`b`,text:`DirectQuery`,explain:`DirectQuery dimensions keep relationships regular but give up in-memory speed for filtering.`},{id:`c`,text:`Dual`,explain:`Correct. Dual lets the engine serve the dimension from cache or by DirectQuery per query, keeping relationships with DirectQuery facts regular and filtering fast.`},{id:`d`,text:`Hybrid`,explain:`A hybrid table is a partitioned fact table, usually created through an incremental refresh policy with real-time DirectQuery; it isn’t a storage mode for dimensions.`}],answer:`c`},{id:`CS6-05`,caseStudyId:a,machineId:`ripple-map`,bulletIds:[`M2.4`],format:`single`,difficulty:2,trapPairId:`lineage-vs-impact`,stem:`Before changing a column in Brindlecombe’s fares warehouse, owners of every dependent report must be warned, including reports in other departments’ workspaces. What should you use?`,sources:[t.impact,t.lineage],options:[{id:`a`,text:`Lineage view in the fares workspace`,explain:`Lineage view doesn’t show downstream items in other workspaces.`},{id:`b`,text:`The OneLake catalog’s Explore tab`,explain:`Listing downstream items across workspaces and notifying their contacts is what impact analysis does.`},{id:`c`,text:`Impact analysis on the warehouse with All downstream items, then Notify contacts`,explain:`Correct. Impact analysis lists downstream items across workspaces, and Notify contacts emails their workspaces’ contacts.`},{id:`d`,text:`A sensitivity label on the warehouse`,explain:`Labels classify sensitivity; they don’t warn report owners.`}],answer:`c`},{id:`CS6-06`,caseStudyId:a,machineId:`seal-and-stamp`,bulletIds:[`M1.4`],format:`multi`,difficulty:2,stem:`Brindlecombe’s ridership data carries a sensitivity label with protection, and exports must keep it. Which two export paths keep the label’s protection? Choose two.`,sources:[t.infoProtection],options:[{id:`a`,text:`Export to PDF`,explain:`Correct. Protection travels with PDF exports.`},{id:`b`,text:`Export to CSV`,explain:`CSV exports aren’t protected.`},{id:`c`,text:`Sharing with a partner organization’s tenant`,explain:`Label access control works only in the tenant where it was applied.`},{id:`d`,text:`Export to Excel`,explain:`Correct. Protection travels with Excel exports.`}],answers:[`a`,`d`]},{id:`CS6-07`,caseStudyId:a,machineId:`weave-planner`,bulletIds:[`P2.3`],format:`single`,difficulty:2,trapPairId:`scd1-vs-scd2`,stem:`Brindlecombe’s trips must still show the stop name that was in use when each trip happened, even after a stop is renamed. How should the stop dimension handle renames?`,sources:[t.dimTables,t.loadTables],options:[{id:`a`,text:`As SCD type 2: expire the current row and insert a new version with a new surrogate key`,explain:`Correct. Type 2 keeps history, so facts keep pointing at the version that was true when they happened.`},{id:`b`,text:`As SCD type 1: overwrite the name`,explain:`Type 1 loses history, so every trip would show the new name.`},{id:`c`,text:`Truncate and reload the stop dimension nightly`,explain:`Learn warns that truncating a dimension with generated surrogate keys breaks fact references and type 2 history.`},{id:`d`,text:`Store the stop name in the trip fact and drop the dimension`,explain:`That abandons the star schema the warehouse is built on.`}],answer:`a`},{id:`CS6-08`,caseStudyId:a,machineId:`jacquard-head`,bulletIds:[`S1.5`],format:`single`,difficulty:2,trapPairId:`calcgroup-vs-fieldparam`,stem:`Brindlecombe’s planners must switch one chart between Boardings, Revenue, and On-time % with a slicer. What should you add to the model?`,sources:[t.fieldParams,t.calcGroups],options:[{id:`a`,text:`A calculation group with Boardings, Revenue, and On-time % items`,explain:`A calculation group applies one calculation to whichever measure is selected; it doesn’t let readers pick which measure the chart shows.`},{id:`b`,text:`A field parameter listing the three measures, used in a slicer and the chart`,explain:`Correct. A field parameter lets readers switch which fields a visual shows.`},{id:`c`,text:`A dynamic format string on each measure`,explain:`Dynamic format strings change display formats, not which measure is shown.`},{id:`d`,text:`Three bookmarks and three charts`,explain:`Bookmarks can mimic switching, but the model-based way to let a slicer switch measures is a field parameter.`}],answer:`b`}],te=[{id:`case-fernhollow`,company:`Fernhollow Outfitters`,title:`Fernhollow Outfitters: retail sales platform`,summary:`A regional outdoor retailer is moving sales reporting from an on-premises ERP into Microsoft Fabric, with regional managers who may see only their own region.`,environment:[`Sales and customer data live in a SQL Server ERP database in Fernhollow’s own data center.`,`Fernhollow has one Fabric F64 capacity and three workspaces: Sales-Dev, Sales-Test, and Sales-Prod.`,`Data engineers write PySpark; the BI team writes T-SQL and DAX.`],requirements:[`Land raw ERP extracts in a lakehouse (bronze and silver layers).`,`Build the gold layer as a star schema with T-SQL stored procedures and multi-table transactions.`,`Keep a history of each customer’s region so past sales stay with the region at the time of sale.`,`Serve reports through a Direct Lake semantic model that never falls back to DirectQuery.`,`Regional managers must see only their own region’s sales.`,`Promote content from Sales-Dev to Sales-Test to Sales-Prod with deployment pipelines.`],constraints:[`Users must never see partly loaded data during the nightly ETL.`,`Row filters for managers must be defined once, in the semantic model.`]},{id:`case-quillmere`,company:`Quillmere Health`,title:`Quillmere Health: patient telemetry`,summary:`A hospital network streams bedside device telemetry into Fabric and must protect patient data while supporting near-real-time operations and research.`,environment:[`Device telemetry streams into a KQL database in an eventhouse.`,`Ward occupancy is kept in an operational Azure SQL database that changes every few minutes.`,`A research team uses notebooks in its own workspace.`,`Microsoft Purview sensitivity labels are published to all staff.`],requirements:[`Operations staff need five-minute summaries of device readings.`,`Data engineers need the telemetry as Delta tables in a lakehouse without a copy pipeline.`,`Ward dashboards must combine near-real-time occupancy with historical admissions.`,`Researchers may read lakehouse data from their notebooks but must never query patient names in the warehouse.`,`Exported reports must keep their label protection where Fabric supports it.`],constraints:[`Researchers have no role in the clinical workspaces.`,`No new data copies of telemetry may be scheduled.`]},{id:`case-saltmarsh`,company:`Saltmarsh Haulage`,title:`Saltmarsh Haulage: shipment analytics lifecycle`,summary:`A freight company is bringing source control, safe releases, and refresh discipline to a growing shipment model that several teams depend on.`,environment:[`Shipment data comes from an Azure SQL database through Dataflow Gen2 into a warehouse.`,`The Shipments semantic model is an Import model on a Fabric F64 capacity, currently 8 GB and growing.`,`Developers edit the model in Power BI Desktop and Tabular Editor.`,`Reports in four other workspaces use the model.`],requirements:[`Review model and report changes as text diffs in pull requests.`,`Version the workspace in an Azure DevOps repository.`,`Keep six years of shipment history and reload only the last seven days each night.`,`Deploy model changes from Tabular Editor to the service.`,`Warn report owners before any change to the shipment dataflow’s output.`],constraints:[`The model will exceed 10 GB within a year.`,`Some shipment weights arrive as text with invalid values.`]},{id:`case-lumenvale`,company:`Lumenvale Utilities`,title:`Lumenvale Utilities: finance and metering models`,summary:`A utility’s finance team, trained on PL-300, is standardizing DAX logic, report starting points, and trusted data for smart-meter analytics in Fabric.`,environment:[`Meter readings and tariffs are stored in a warehouse named MeterWH; the meter registry is a lakehouse named RegistryLH in the same workspace.`,`Tariffs are normalized into Tariff, TariffBand, and TariffFamily tables.`,`A meter can be shared by several customers in multi-unit buildings.`,`The finance semantic model has 40 base measures.`],requirements:[`Provide YTD, prior-year, and YoY% versions of every measure without duplicating measures.`,`Show amounts in each country’s currency format while charts keep plotting numbers.`,`Validate measure results with DAX queries before publishing.`,`Mark RegistryLH as the single authoritative source of meter data.`,`Give new report authors a standard starting report with the model and queries but no data.`],constraints:[`Report hierarchies must be built from single tables.`,`Some measures filter large tables and are slow.`]}],o=`case-fernhollow`,s=`case-quillmere`,c=`case-saltmarsh`,l=`case-lumenvale`,ne=[{id:`CS1-01`,caseStudyId:o,machineId:`thread-intake`,bulletIds:[`P1.1`],format:`single`,difficulty:2,stem:`Fernhollow needs a Dataflow Gen2 to read the ERP tables on its SQL Server for the bronze layer. What must be in place for the connection?`,sources:[t.gateway,t.connections],options:[{id:`a`,text:`A OneLake shortcut to the SQL Server database`,explain:`Shortcuts point to storage locations, not to an on-premises SQL Server.`},{id:`b`,text:`An on-premises data gateway in Fernhollow’s network`,explain:`Correct. Learn: use the on-premises data gateway to connect on-premises data to the cloud.`},{id:`c`,text:`Mirroring of the Fabric warehouse`,explain:`Mirroring the warehouse doesn’t reach the on-premises source.`},{id:`d`,text:`A workspace identity with Contributor access`,explain:`An identity doesn’t provide network access to an on-premises server.`}],answer:`b`},{id:`CS1-02`,caseStudyId:o,machineId:`vat-selector`,bulletIds:[`P1.4`],format:`single`,difficulty:2,trapPairId:`stores`,stem:`Fernhollow’s BI team will build the gold star schema with T-SQL stored procedures that update several tables in one transaction. Which data store should hold the gold layer?`,sources:[t.decisionLhWh],options:[{id:`a`,text:`The lakehouse, through its SQL analytics endpoint`,explain:`The endpoint is read-only, so procedures can’t modify data there.`},{id:`b`,text:`An eventhouse`,explain:`Eventhouses are for streaming event data queried with KQL.`},{id:`c`,text:`A warehouse`,explain:`Correct. Learn: the warehouse is developed with T-SQL and provides full multi-table ACID transactions and stored procedures.`},{id:`d`,text:`A semantic model with calculated tables`,explain:`A semantic model isn’t a store for T-SQL ETL.`}],answer:`c`},{id:`CS1-03`,caseStudyId:o,machineId:`weave-planner`,bulletIds:[`P2.3`],format:`yesno`,difficulty:3,trapPairId:`scd1-vs-scd2`,stem:`Fernhollow must keep each customer’s region history so past sales stay with the region at the time of sale. For each proposed design, select Yes if it meets the goal. Otherwise, select No.`,sources:[t.dimTables,t.loadTables],statements:[{id:`s1`,text:`Overwrite Region in DimCustomer whenever the ERP value changes, matching on CustomerID.`,answer:!1,explain:`No. That is SCD type 1, which rolls all past sales up to the new region.`},{id:`s2`,text:`Expire the current DimCustomer row and insert a new version with a new surrogate key; facts store the surrogate key current at load time.`,answer:!0,explain:`Yes. SCD type 2 with surrogate keys keeps each fact on the version that was valid.`},{id:`s3`,text:`Truncate and reload DimCustomer from the ERP each night with new surrogate keys.`,answer:!1,explain:`No. Learn says never to truncate and reload a dimension with generated surrogate keys; it invalidates facts and loses history.`}]},{id:`CS1-04`,caseStudyId:o,machineId:`direct-lake-shuttle`,bulletIds:[`S2.4`],format:`single`,difficulty:3,trapPairId:`dl-onelake-vs-sql`,stem:`Fernhollow’s Direct Lake model must never fall back to DirectQuery, and manager row filters are defined in the semantic model. Which Direct Lake option and setting meets the requirements?`,sources:[t.directLake,t.dlHow],options:[{id:`a`,text:`Direct Lake on SQL analytics endpoints with DirectLakeBehavior set to Automatic`,explain:`Automatic falls back to DirectQuery silently, which the requirement forbids.`},{id:`b`,text:`Direct Lake on SQL analytics endpoints with DirectLakeBehavior set to DirectQueryOnly`,explain:`DirectQueryOnly forces every query to DirectQuery.`},{id:`c`,text:`Direct Lake on SQL analytics endpoints with SQL RLS defined in the warehouse`,explain:`SQL RLS makes Direct Lake on SQL fall back, and the filters must live in the semantic model.`},{id:`d`,text:`Direct Lake on OneLake`,explain:`Correct. It runs only in DirectLakeOnly mode and never falls back; semantic model RLS applies to it.`}],answer:`d`},{id:`CS1-05`,caseStudyId:o,machineId:`direct-lake-shuttle`,bulletIds:[`S2.3`],format:`single`,difficulty:2,trapPairId:`framing-vs-import-refresh`,stem:`Fernhollow’s nightly pipeline loads gold tables for two hours. Managers must never see partly loaded data in the Direct Lake model. What should the pipeline do?`,sources:[t.dlHow],options:[{id:`a`,text:`Refresh the model every 15 minutes during the load`,explain:`Each refresh would frame partly loaded tables.`},{id:`b`,text:`Run with automatic updates off, and refresh the model after the last table loads`,explain:`Correct. Framing only after the load completes shows users a consistent point in time.`},{id:`c`,text:`Set the model to the large storage format`,explain:`Storage format doesn’t control framing.`},{id:`d`,text:`Rebuild the model’s relationships after each load`,explain:`Relationships don’t control which data version users see.`}],answer:`b`},{id:`CS1-06`,caseStudyId:o,machineId:`thread-sieves`,bulletIds:[`M1.3`],format:`single`,difficulty:2,stem:`Fernhollow’s regional managers are workspace Viewers. A table maps each manager’s email to a region. How should you restrict each manager to their own region?`,sources:[t.modelRls],options:[{id:`a`,text:`A semantic model role with the filter [ManagerEmail] = USERPRINCIPALNAME()`,explain:`Correct. Dynamic RLS matches the signed-in user, and the filter flows through relationships.`},{id:`b`,text:`A security policy in the gold warehouse`,explain:`The requirement says to define filters once, in the semantic model.`},{id:`c`,text:`One workspace per region with copied reports`,explain:`Copying content doesn’t scale and duplicates reports.`},{id:`d`,text:`Give managers the Contributor role`,explain:`Contributors bypass semantic model RLS.`}],answer:`a`},{id:`CS1-07`,caseStudyId:o,machineId:`conveyor`,bulletIds:[`M2.3`],format:`yesno`,difficulty:3,stem:`After deploying the Direct Lake model from Sales-Test to Sales-Prod, Prod reports show Test data. For each proposed solution, select Yes if it meets the goal. Otherwise, select No.`,sources:[t.pipelinesProcess,t.pipelinesRules],statements:[{id:`s1`,text:`Add a datasource rule in the Sales-Prod stage that points the model to the Prod gold warehouse, then deploy again.`,answer:!0,explain:`Yes. Direct Lake models don’t autobind to the target stage’s items; datasource rules fix the binding.`},{id:`s2`,text:`Refresh the semantic model in Sales-Prod.`,answer:!1,explain:`No. Refresh reframes against the source the model is bound to, which is still in Test.`},{id:`s3`,text:`Redeploy only the reports to Sales-Prod.`,answer:!1,explain:`No. Reports autobind to the Prod model; the model itself is still bound to Test.`}]},{id:`CS2-01`,caseStudyId:s,machineId:`tension-meter`,bulletIds:[`P3.3`],format:`dropdown`,difficulty:2,stem:`Quillmere’s operations staff need the average heart rate per device in five-minute buckets for the last hour, from the Readings table. Complete the KQL query.`,sources:[t.kqlWhere,t.kqlSummarize,t.kqlBin],language:`kql`,code:`Readings
| where Timestamp > [[1]](1h)
| summarize AvgHeartRate = [[2]](HeartRate) by DeviceId, bin(Timestamp, [[3]])`,slots:[{id:`1`,options:[{id:`a`,text:`ago`,explain:`Correct. ago(1h) is one hour before now.`},{id:`b`,text:`bin`,explain:`bin buckets values; it doesn’t compute a time relative to now.`},{id:`c`,text:`between`,explain:`between needs a range of two values.`}],answer:`a`},{id:`2`,options:[{id:`a`,text:`count`,explain:`count() counts rows; it doesn’t average values.`},{id:`b`,text:`dcount`,explain:`dcount() estimates distinct values.`},{id:`c`,text:`avg`,explain:`Correct. avg() averages HeartRate per group.`}],answer:`c`},{id:`3`,options:[{id:`a`,text:`5m`,explain:`Correct. 5m is a five-minute timespan.`},{id:`b`,text:`1h`,explain:`This would give hourly buckets.`},{id:`c`,text:`300`,explain:`5m is the five-minute timespan; 300 isn’t written as a timespan.`}],answer:`a`}]},{id:`CS2-02`,caseStudyId:s,machineId:`shared-spool`,bulletIds:[`P1.5`],format:`single`,difficulty:2,trapPairId:`onelake-availability-vs-integration`,stem:`Quillmere’s data engineers need the eventhouse telemetry as Delta tables in their lakehouse, and no new copy jobs may be scheduled. What should you do?`,sources:[t.eventhouseOneLake,t.shortcuts],options:[{id:`a`,text:`Schedule a pipeline that copies the KQL tables to the lakehouse nightly`,explain:`This is the scheduled copy the constraint forbids.`},{id:`b`,text:`Export the KQL tables to CSV in the Files area`,explain:`CSV files aren’t Delta tables, and exports are copies.`},{id:`c`,text:`Turn on OneLake availability for the KQL database and create shortcuts in the lakehouse`,explain:`Correct. OneLake availability exposes the data in Delta format, and shortcuts make it visible in the lakehouse.`},{id:`d`,text:`Mirror the eventhouse into a warehouse`,explain:`Mirroring isn’t how eventhouse data is exposed to a lakehouse.`}],answer:`c`},{id:`CS2-03`,caseStudyId:s,machineId:`bale-catalog`,bulletIds:[`P1.2`],format:`single`,difficulty:1,trapPairId:`catalog-vs-rthub`,stem:`A Quillmere engineer wants to browse the data streams available in the organization, including the telemetry stream, to find a new device feed. Where should they look?`,sources:[t.rtHub,t.catalog],options:[{id:`a`,text:`The Real-Time hub`,explain:`Correct. The Real-Time hub is where you discover and manage streaming data.`},{id:`b`,text:`The lakehouse Files area`,explain:`Files shows stored files, not streams across the organization.`},{id:`c`,text:`The deployment pipeline view`,explain:`Pipelines promote content between stages.`},{id:`d`,text:`The semantic model’s lineage view`,explain:`Lineage shows item dependencies, not available streams.`}],answer:`a`},{id:`CS2-04`,caseStudyId:s,machineId:`double-loom`,bulletIds:[`S1.7`],format:`single`,difficulty:3,trapPairId:`storage-modes`,stem:`Quillmere’s ward dashboard must show occupancy from the Azure SQL database within minutes, next to historical admissions that refresh nightly. Admissions, Ward, and Date come from the same Azure SQL database, and Ward and Date relate to both facts. How should you configure the model?`,sources:[t.composite,t.storageMode],options:[{id:`a`,text:`Import every table and refresh every five minutes`,explain:`Scheduled refresh limits make this impractical, and it copies all data repeatedly.`},{id:`b`,text:`Occupancy in DirectQuery, admissions in Import, and Ward and Date in Dual`,explain:`Correct. A composite model gives current occupancy, fast history, and Dual dimensions keep relationships regular.`},{id:`c`,text:`Every table in DirectQuery`,explain:`History would be slower than needed and gains nothing from DirectQuery.`},{id:`d`,text:`Occupancy in DirectQuery and the dimensions in Import`,explain:`Import dimensions relate to DirectQuery facts through limited relationships; Dual avoids that.`}],answer:`b`},{id:`CS2-05`,caseStudyId:s,machineId:`thread-sieves`,bulletIds:[`M1.3`],format:`single`,difficulty:2,trapPairId:`cls-vs-ols-vs-ddm`,stem:`The clinical warehouse is shared with Quillmere’s researchers with Read All with SQL analytics endpoint permission. Any query that touches dbo.Patients.PatientName must fail for them, while other columns stay available. What should you implement?`,sources:[t.whCls],options:[{id:`a`,text:`Dynamic data masking on PatientName`,explain:`Masking returns the column with obscured values instead of failing.`},{id:`b`,text:`A sensitivity label on the warehouse`,explain:`Labels don’t block columns in SQL queries.`},{id:`c`,text:`Column-level security that grants SELECT on every column except PatientName`,explain:`Correct. Queries that touch a denied column fail with a permission error.`},{id:`d`,text:`Row-level security on dbo.Patients`,explain:`RLS filters rows, not columns.`}],answer:`c`},{id:`CS2-06`,caseStudyId:s,machineId:`item-locks`,bulletIds:[`M1.2`],format:`single`,difficulty:2,stem:`Quillmere’s researchers have no role in the clinical workspace. They must read the telemetry lakehouse from notebooks in their own workspace. Which permission should you grant when sharing the lakehouse?`,sources:[t.shareItems,t.roles],options:[{id:`a`,text:`Read All with SQL analytics endpoint`,explain:`This allows T-SQL reads, not Spark.`},{id:`b`,text:`Read all with Apache Spark`,explain:`Correct. ReadAll allows reading through OneLake APIs and Spark.`},{id:`c`,text:`Build`,explain:`Build applies to semantic models.`},{id:`d`,text:`The workspace Viewer role`,explain:`The Viewer role doesn’t include reading data through OneLake and Spark (ReadAll), and it would cover every item in the workspace.`}],answer:`b`},{id:`CS2-07`,caseStudyId:s,machineId:`seal-and-stamp`,bulletIds:[`M1.4`],format:`yesno`,difficulty:2,stem:`Quillmere’s ward report carries a Highly Confidential label with an encryption policy. For each export, select Yes if the label’s protection stays with the exported file. Otherwise, select No.`,sources:[t.infoProtection],statements:[{id:`s1`,text:`Export to Excel`,answer:!0,explain:`Yes. Excel is a supported export path.`},{id:`s2`,text:`Export of a table visual to .txt`,answer:!1,explain:`No. Other export paths such as .csv and .txt aren’t supported.`},{id:`s3`,text:`Analyze in Excel with a live connection to the model`,answer:!0,explain:`Yes. Learn lists Analyze in Excel as a supported export path.`}]},{id:`CS3-01`,caseStudyId:c,machineId:`carding-machine`,bulletIds:[`P2.8`],format:`single`,difficulty:2,stem:`Saltmarsh’s staging table stores ShipmentWeight as text, and some values are invalid, such as “n/a”. The warehouse load must convert valid values to decimal without failing on bad rows. Which expression should you use?`,sources:[t.tryCast],options:[{id:`a`,text:`CAST(ShipmentWeight AS decimal(10,2))`,explain:`CAST raises an error on the first invalid value and stops the load.`},{id:`b`,text:`TRY_CAST(ShipmentWeight AS decimal(10,2))`,explain:`Correct. TRY_CAST returns NULL when a value can’t be converted.`},{id:`c`,text:`COALESCE(ShipmentWeight, '0')`,explain:`COALESCE replaces NULLs; it doesn’t convert types or handle invalid text.`},{id:`d`,text:`CONCAT(ShipmentWeight, '.00')`,explain:`This produces more text, not a decimal.`}],answer:`b`},{id:`CS3-02`,caseStudyId:c,machineId:`twisting-frame`,bulletIds:[`P2.5`],format:`single`,difficulty:3,stem:`Saltmarsh’s dashboards only show monthly totals by carrier and lane, but the fact table stores one row per shipment line. Analysts never need shipment-level detail. What should you do to reduce the fact table’s size?`,sources:[t.loadTables],options:[{id:`a`,text:`Load an aggregated result grouped by all the dimension keys at month grain`,explain:`Correct. Aggregating raises the grain and reduces dimensionality, at the cost of detail nobody needs.`},{id:`b`,text:`Partition the fact table by shipment number`,explain:`Partitioning doesn’t reduce the stored rows.`},{id:`c`,text:`Add a calculated column with the monthly total`,explain:`This adds data to every row instead of reducing it.`},{id:`d`,text:`Convert the fact table to a snowflake design`,explain:`Snowflaking applies to dimensions, not fact grain.`}],answer:`a`},{id:`CS3-03`,caseStudyId:c,machineId:`batch-winder`,bulletIds:[`S2.5`],format:`multi`,difficulty:3,trapPairId:`archive-vs-refresh-period`,stem:`Saltmarsh must keep six years of shipments and reload only the last seven days each night. Shipments carry a LastModified column, and the policy partitions on ShipDate. Which two settings should the incremental refresh policy use? Choose two.`,sources:[t.incrementalCfg],options:[{id:`a`,text:`Archive data starting 6 years before the refresh date, and incrementally refresh 7 days before`,explain:`Correct. The archive period keeps history; the refresh period is the reloaded window.`},{id:`b`,text:`Detect data changes using the LastModified column`,explain:`Correct. Only periods whose LastModified value changed are refreshed, and it differs from the partition column.`},{id:`c`,text:`Detect data changes using the ShipDate column`,explain:`Learn says the detect-changes column shouldn’t be the same column used to partition the data.`},{id:`d`,text:`Archive data starting 7 days before, and incrementally refresh 6 years before`,explain:`This swaps the periods and reloads six years each night.`}],answers:[`a`,`b`]},{id:`CS3-04`,caseStudyId:c,machineId:`wide-beam`,bulletIds:[`S1.6`],format:`single`,difficulty:2,stem:`Saltmarsh’s Shipments model will pass 10 GB within a year, and developers will deploy it from Tabular Editor over XMLA. Which model setting is required beyond 10 GB and also recommended for XMLA write operations?`,sources:[t.largeModels],options:[{id:`a`,text:`Large semantic model storage format`,explain:`Correct. It’s required beyond 10 GB and improves XMLA write performance.`},{id:`b`,text:`Dual storage mode on the fact table`,explain:`Dual doesn’t change size limits or XMLA performance.`},{id:`c`,text:`Query caching`,explain:`Caching speeds up reads only.`},{id:`d`,text:`Automatic page refresh`,explain:`This is a report page setting; it doesn’t change model size limits or XMLA performance.`}],answer:`a`},{id:`CS3-05`,caseStudyId:c,machineId:`draft-table`,bulletIds:[`M2.2`],format:`single`,difficulty:1,trapPairId:`pbi-files`,stem:`Saltmarsh wants to review model and report changes as text diffs in pull requests. How should developers save their Power BI Desktop work?`,sources:[t.pbip],options:[{id:`a`,text:`As a .pbix file in a shared folder`,explain:`A .pbix is a single file, not the plain-text project files built for source control.`},{id:`b`,text:`As a .pbit template`,explain:`A template is a starting point, not a source-control format.`},{id:`c`,text:`As a .pbids file`,explain:`A .pbids holds only a connection.`},{id:`d`,text:`As a Power BI project (.pbip)`,explain:`Correct. Projects store definitions as plain text built for source control.`}],answer:`d`},{id:`CS3-06`,caseStudyId:c,machineId:`ripple-map`,bulletIds:[`M2.4`],format:`single`,difficulty:2,trapPairId:`lineage-vs-impact`,stem:`Saltmarsh plans to rename a column in the shipment dataflow’s output. Reports in four other workspaces depend on it, and some of those workspaces are inaccessible to you. What should you do first?`,sources:[t.impact,t.lineage],options:[{id:`a`,text:`Open lineage view in your workspace and email the owners you see`,explain:`Lineage view doesn’t show downstream items in other workspaces.`},{id:`b`,text:`Rename the column and watch for refresh failures`,explain:`This breaks downstream content without warning.`},{id:`c`,text:`Run impact analysis on the dataflow and use Notify contacts`,explain:`Correct. Impact analysis lists dependents across workspaces and notifies their contacts, even ones you can’t access.`},{id:`d`,text:`Certify the dataflow so owners see the change`,explain:`Endorsement doesn’t notify anyone.`}],answer:`c`},{id:`CS3-07`,caseStudyId:c,machineId:`remote-loom-control`,bulletIds:[`M2.5`],format:`single`,difficulty:2,trapPairId:`xmla-read-vs-readwrite`,stem:`Saltmarsh’s first deployment from Tabular Editor to the workspace fails with a write error, although querying the model works. What should the capacity admin change?`,sources:[t.xmla],options:[{id:`a`,text:`Turn off the large storage format`,explain:`Learn recommends large format on for XMLA writes.`},{id:`b`,text:`Set the capacity’s XMLA Endpoint setting to Read Write`,explain:`Correct. Read-only is the default; deployments need Read Write.`},{id:`c`,text:`Move the workspace to Pro`,explain:`Pro workspaces don’t support XMLA writes.`},{id:`d`,text:`Disconnect the workspace from Git`,explain:`Git doesn’t block XMLA writes.`}],answer:`b`},{id:`CS3-08`,caseStudyId:c,machineId:`pattern-ledger`,bulletIds:[`M2.1`],format:`single`,difficulty:1,stem:`Saltmarsh’s lead developer is a workspace Member and tries to connect the workspace to the Azure DevOps repository, but can’t. Git integration is enabled for the organization. What is needed?`,sources:[t.gitIntro,t.roles],options:[{id:`a`,text:`A workspace Admin must make the connection`,explain:`Correct. Only Admins can connect a workspace to Git.`},{id:`b`,text:`The developer needs a deployment pipeline first`,explain:`Pipelines aren’t a prerequisite for Git.`},{id:`c`,text:`The repository must be moved to GitHub`,explain:`Azure DevOps is supported.`},{id:`d`,text:`The model must be saved as .pbit`,explain:`Templates have nothing to do with the Git connection.`}],answer:`a`},{id:`CS4-01`,caseStudyId:l,machineId:`dax-scale`,bulletIds:[`P3.4`],format:`single`,difficulty:2,stem:`Lumenvale’s finance team wants to check [Billed Amount] by region and month before publishing a change, without building a visual. Which DAX query should they run in DAX query view?`,sources:[t.daxQueries,t.summarizeColumns],options:[{id:`a`,text:`EVALUATE SUMMARIZECOLUMNS('Region'[Region], 'Date'[Month], "Billed", [Billed Amount])`,explain:`Correct. SUMMARIZECOLUMNS groups by the columns and returns the measure for each group.`},{id:`b`,text:`SELECT Region, Month, [Billed Amount] FROM Sales`,explain:`This is SQL, not a DAX query.`},{id:`c`,text:`EVALUATE [Billed Amount] BY 'Region'[Region]`,explain:`A measure needs a table expression; BY isn’t DAX query syntax.`},{id:`d`,text:`DEFINE SUMMARIZECOLUMNS('Region'[Region], [Billed Amount])`,explain:`DEFINE holds definitions; a query needs EVALUATE.`}],answer:`a`},{id:`CS4-02`,caseStudyId:l,machineId:`recipe-book`,bulletIds:[`P2.1`],format:`single`,difficulty:2,trapPairId:`star-vs-snowflake`,stem:`Lumenvale’s tariffs are normalized into Tariff, TariffBand, and TariffFamily in MeterWH. The finance model needs a Family > Band > Tariff hierarchy, and hierarchies must come from single tables. What should you create in MeterWH?`,sources:[t.dimTables,t.createView],options:[{id:`a`,text:`A stored procedure that returns the three tables`,explain:`The model can’t import a procedure’s result as a table this way.`},{id:`b`,text:`A view that joins the three tables into one tariff result`,explain:`Correct. Learn: expose a snowflake through a view that joins it into a denormalized result.`},{id:`c`,text:`Three separate shortcuts to the tables`,explain:`Shortcuts keep three tables, so the hierarchy still can’t be built.`},{id:`d`,text:`An inline table-valued function per level`,explain:`Separate functions still produce separate tables.`}],answer:`b`},{id:`CS4-03`,caseStudyId:l,machineId:`inspection-bench`,bulletIds:[`P3.2`],format:`single`,difficulty:2,stem:`In MeterWH, you need to join dbo.Readings to the Meters table in RegistryLH, which is in the same workspace and has been added to the Explorer. How should you reference the lakehouse table in T-SQL?`,sources:[t.queryWarehouse],options:[{id:`a`,text:`OPENROWSET over RegistryLH/Files`,explain:`The table is reachable directly by name; Files holds raw files.`},{id:`b`,text:`A four-part name that includes the workspace`,explain:`Cross-database queries in the same workspace use three-part names.`},{id:`c`,text:`RegistryLH.dbo.Meters`,explain:`Correct. Reference the added database’s table with a three-part name.`},{id:`d`,text:`A KQL cross-cluster query`,explain:`KQL doesn’t run in the warehouse SQL editor.`}],answer:`c`},{id:`CS4-04`,caseStudyId:l,machineId:`jacquard-head`,bulletIds:[`S1.5`],format:`multi`,difficulty:2,trapPairId:`calcgroup-vs-fieldparam`,stem:`Lumenvale needs YTD, prior-year, and YoY% versions of 40 measures, and amounts in each country’s currency format while charts keep plotting numbers. Which two features should you implement? Choose two.`,sources:[t.calcGroups,t.dynamicFormat],options:[{id:`a`,text:`FORMAT() inside each measure`,explain:`FORMAT returns text, which breaks charts.`},{id:`b`,text:`A field parameter with 120 measures`,explain:`A field parameter switches fields; it doesn’t create the variants.`},{id:`c`,text:`A calculation group for the time intelligence variants`,explain:`Correct. Calculation items apply YTD, PY, and YoY% to any measure.`},{id:`d`,text:`Dynamic format strings for the currency formats`,explain:`Correct. Measures stay numeric while the format changes by context.`}],answers:[`c`,`d`]},{id:`CS4-05`,caseStudyId:l,machineId:`speed-governor`,bulletIds:[`S2.2`],format:`single`,difficulty:3,stem:`A slow Lumenvale measure is CALCULATE([Usage], FILTER('Meter', 'Meter'[Type] = "Smart")). Which rewrite follows Learn’s guidance and keeps any existing Type filter?`,sources:[t.bpFilter],options:[{id:`a`,text:`CALCULATE([Usage], FILTER(ALL('Meter'), 'Meter'[Type] = "Smart"))`,explain:`This still iterates the table and also removes existing Meter filters.`},{id:`b`,text:`SUMX(FILTER('Meter', 'Meter'[Type] = "Smart"), [Usage])`,explain:`Iterating meters and evaluating the measure per row is slower.`},{id:`c`,text:`CALCULATE([Usage], 'Meter'[Type] = "Smart" || 'Meter'[Type] = "Legacy")`,explain:`This changes the result by adding Legacy meters.`},{id:`d`,text:`CALCULATE([Usage], KEEPFILTERS('Meter'[Type] = "Smart"))`,explain:`Correct. A Boolean column filter is optimized, and KEEPFILTERS keeps existing Type filters.`}],answer:`d`},{id:`CS4-06`,caseStudyId:l,machineId:`warp-frame`,bulletIds:[`S1.3`],format:`single`,difficulty:3,stem:`In Lumenvale’s model, a meter can be shared by several customers, and a customer can have several meters. Readings relate to Meter. How should Customer filter readings?`,sources:[t.manyToMany],options:[{id:`a`,text:`Relate Customer directly to Readings`,explain:`Readings have no customer key; they belong to meters.`},{id:`b`,text:`Relate Customer to Meter with a many-to-many relationship on MeterID`,explain:`Learn doesn’t recommend relating many-to-many dimensions directly.`},{id:`c`,text:`Add a customer-meter bridging table with two one-to-many relationships, one set to Both`,explain:`Correct. A bridging table resolves the many-to-many dimensions so Customer filters reach Readings.`},{id:`d`,text:`Merge Customer into the Meter table`,explain:`This duplicates meters per customer and breaks the Meter key.`}],answer:`c`},{id:`CS4-07`,caseStudyId:l,machineId:`seal-and-stamp`,bulletIds:[`M1.5`],format:`single`,difficulty:1,trapPairId:`endorse-vs-label`,stem:`Lumenvale wants RegistryLH marked as the single authoritative source of meter data so that teams stop using copies. What should you apply?`,sources:[t.endorsement],options:[{id:`a`,text:`The Promoted badge`,explain:`Promoted means ready to share, not authoritative.`},{id:`b`,text:`A Confidential sensitivity label`,explain:`Labels state sensitivity, not authority.`},{id:`c`,text:`A deployment pipeline rule`,explain:`Rules change settings between stages.`},{id:`d`,text:`The Master data badge`,explain:`Correct. Master data marks a data item as the authoritative source for core data.`}],answer:`d`},{id:`CS4-08`,caseStudyId:l,machineId:`pattern-book`,bulletIds:[`M2.6`],format:`single`,difficulty:1,trapPairId:`pbi-files`,stem:`Lumenvale’s new report authors should start from a standard report with the finance model and queries, but no data. What should you give them?`,sources:[t.templates],options:[{id:`a`,text:`A Power BI template (.pbit)`,explain:`Correct. A template has report pages, model definition, and queries without data.`},{id:`b`,text:`A .pbids file`,explain:`A .pbids holds only a data source connection.`},{id:`c`,text:`A copy of the published .pbix`,explain:`A .pbix includes imported data.`},{id:`d`,text:`Read permission on the model`,explain:`Permissions don’t give a starting report.`}],answer:`a`}],u=[...te,...r],re=[...ne,...ee],d=`gate-keys`,f=`item-locks`,p=`thread-sieves`,m=`seal-and-stamp`,ie=[{id:`GK-01`,machineId:d,bulletIds:[`M1.1`],format:`single`,difficulty:1,placement:!0,trapPairId:`member-vs-contributor`,stem:`Data engineers must create and edit lakehouses, warehouses, and notebooks in a Fabric workspace, but must not share items or manage workspace access. Which workspace role should you assign?`,sources:[t.roles],options:[{id:`a`,text:`Admin`,explain:`Admins can also manage permissions and delete the workspace, which is more than needed.`},{id:`b`,text:`Member`,explain:`Members can also share items and add people, which the requirement forbids.`},{id:`c`,text:`Contributor`,explain:`Correct. Contributors can create and modify content but can’t manage access, and can share only if given Reshare permission.`},{id:`d`,text:`Viewer`,explain:`Viewers can only view content; they can’t create or edit items.`}],answer:`c`},{id:`GK-02`,machineId:d,bulletIds:[`M1.1`],format:`single`,difficulty:2,placement:!0,stem:`A workspace Member wants to connect the workspace to a GitHub repository for source control. The option is unavailable to them. Who can make the connection?`,sources:[t.roles,t.gitIntro],options:[{id:`a`,text:`Any Contributor with a GitHub account`,explain:`Contributors can commit after the connection exists, but can’t create it.`},{id:`b`,text:`A workspace Admin`,explain:`Correct. Only Admins can connect a workspace to a Git repository.`},{id:`c`,text:`The capacity administrator only`,explain:`Capacity admins manage capacities; the Git connection is a workspace Admin action.`},{id:`d`,text:`Any Member, after enabling Git in the tenant`,explain:`Even with Git enabled in the tenant, Members can’t connect the workspace.`}],answer:`b`},{id:`GK-03`,machineId:d,bulletIds:[`M1.1`],format:`single`,difficulty:2,placement:!0,stem:`Analysts are workspace Viewers and read reports on a semantic model with RLS. A developer with the Contributor role reports that the RLS filters don’t apply to them. Why?`,sources:[t.modelRls,t.roles],options:[{id:`a`,text:`RLS doesn’t apply to Contributors or higher roles`,explain:`Correct. Users with edit permission on the model (Admin, Member, Contributor) aren’t restricted by RLS.`},{id:`b`,text:`RLS takes effect only after the next scheduled refresh`,explain:`The cause is the developer’s role: RLS doesn’t restrict users who can edit the model.`},{id:`c`,text:`The developer isn’t assigned to any role, so they see nothing`,explain:`They see everything, not nothing.`},{id:`d`,text:`RLS isn’t supported on models in Fabric workspaces`,explain:`Semantic model RLS is supported in Fabric.`}],answer:`a`},{id:`GK-04`,machineId:d,bulletIds:[`M1.1`],format:`yesno`,difficulty:2,placement:!0,stem:`You are planning workspace access for a Fabric analytics team. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.roles,t.workspaces],statements:[{id:`s1`,text:`Workspace roles can be assigned to security groups as well as to individual users.`,answer:!0,explain:`Yes. Roles can go to users, security groups, Microsoft 365 groups, distribution lists, and service principals.`},{id:`s2`,text:`A Contributor role in one workspace also grants Contributor rights in other workspaces on the same capacity.`,answer:!1,explain:`No. Workspace roles apply only to that workspace.`},{id:`s3`,text:`A user who is in two groups, one with Viewer and one with Member, gets the Member role.`,answer:!0,explain:`Yes. A user gets the highest role they’re assigned.`}]},{id:`GK-05`,machineId:d,bulletIds:[`M1.1`],format:`match`,difficulty:2,placement:!0,trapPairId:`member-vs-contributor`,stem:`Match each requirement to the least-privileged workspace role that meets it.`,sources:[t.roles],prompts:[{id:`p1`,text:`Delete the workspace and add other admins`},{id:`p2`,text:`Share items and add people as Contributors`},{id:`p3`,text:`Create warehouses and edit notebooks`},{id:`p4`,text:`Open reports without editing anything`}],choices:[{id:`c1`,text:`Admin`},{id:`c2`,text:`Member`},{id:`c3`,text:`Contributor`},{id:`c4`,text:`Viewer`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Only Admins can delete the workspace and add admins.`},{promptId:`p2`,choiceId:`c2`,explain:`Members can share and add people with Member or lower roles.`},{promptId:`p3`,choiceId:`c3`,explain:`Contributors can create and modify content.`},{promptId:`p4`,choiceId:`c4`,explain:`Viewers can view content only.`}]},{id:`GK-06`,machineId:d,bulletIds:[`M1.1`],format:`single`,difficulty:3,placement:!0,stem:`You plan OneLake security roles to limit which lakehouse folders people can read. For users in which workspace role do these roles mainly make a difference?`,sources:[t.roles,t.onelakeAccessModel],options:[{id:`a`,text:`Admin`,explain:`Admins already have write access to all data in the workspace.`},{id:`b`,text:`Member`,explain:`Members already have write access to the data.`},{id:`c`,text:`Contributor`,explain:`Contributors also have data access through write permission.`},{id:`d`,text:`Viewer`,explain:`Correct. Admins, Members, and Contributors have data access through write permission, so OneLake security roles mainly restrict Viewers.`}],answer:`d`},{id:`GK-07`,machineId:d,bulletIds:[`M1.1`],format:`single`,difficulty:1,stem:`You need to give a new team access to a workspace and keep administration simple as people join and leave. What does Learn recommend?`,sources:[t.roles,t.workspaces,t.onelakeSecurity],options:[{id:`a`,text:`Assign the role to a security group`,explain:`Correct. Assigning roles to groups keeps access manageable.`},{id:`b`,text:`Assign the role to each user individually`,explain:`This works, but every change needs a workspace edit.`},{id:`c`,text:`Share every item with each user`,explain:`Item sharing doesn’t scale and doesn’t replace a workspace role.`},{id:`d`,text:`Give everyone the Admin role`,explain:`This grants far more than needed.`}],answer:`a`},{id:`GK-08`,machineId:d,bulletIds:[`M1.1`],format:`single`,difficulty:2,placement:!0,trapPairId:`access-layers`,stem:`Fabric separates control-plane permissions from data-plane permissions. Which of these is a data-plane control?`,sources:[t.permissionModel,t.onelakeAccessModel,t.onelakeSecurity],options:[{id:`a`,text:`The workspace Contributor role`,explain:`Workspace roles are control-plane permissions about what you can do with items.`},{id:`b`,text:`Edit permission on a lakehouse`,explain:`Item permissions such as Edit govern actions on the item.`},{id:`c`,text:`A OneLake security role on a lakehouse folder`,explain:`Correct. OneLake security roles govern which data you can read.`},{id:`d`,text:`Share permission on a semantic model`,explain:`Share is an item permission about resharing.`}],answer:`c`},{id:`GK-09`,machineId:d,bulletIds:[`M1.1`],format:`multi`,difficulty:2,placement:!0,trapPairId:`member-vs-contributor`,stem:`Which two actions can a workspace Member perform by default that a Contributor without Reshare permission can’t? Choose two.`,sources:[t.roles],options:[{id:`a`,text:`Share an item with another user`,explain:`Correct. Members can share items; Contributors can’t.`},{id:`b`,text:`Create a new warehouse`,explain:`Contributors can create warehouses too.`},{id:`c`,text:`Add a user to the workspace as a Contributor`,explain:`Correct. Members can add people with Member or lower roles.`},{id:`d`,text:`Delete the workspace`,explain:`Only Admins can delete the workspace.`}],answers:[`a`,`c`]},{id:`IL-01`,machineId:f,bulletIds:[`M1.2`],format:`single`,difficulty:2,placement:!0,stem:`An analyst without a workspace role needs to query a lakehouse’s tables with T-SQL through its SQL analytics endpoint. Nothing else is needed. Which permission should you grant when sharing the lakehouse?`,sources:[t.shareItems],options:[{id:`a`,text:`Read only`,explain:`Read lets them connect and see metadata, but not read the data.`},{id:`b`,text:`Read all with Apache Spark`,explain:`This grants access through OneLake and Spark, not T-SQL.`},{id:`c`,text:`Read All with SQL analytics endpoint`,explain:`Correct. It grants ReadData, which lets the user read data with T-SQL.`},{id:`d`,text:`Edit`,explain:`Edit grants far more than reading data.`}],answer:`c`},{id:`IL-02`,machineId:f,bulletIds:[`M1.2`],format:`single`,difficulty:2,placement:!0,stem:`A data scientist with no workspace role needs to read a lakehouse’s files and tables from a notebook in their own workspace. Which permission should you grant when sharing?`,sources:[t.shareItems,t.roles],options:[{id:`a`,text:`Read all with Apache Spark`,explain:`Correct. It grants ReadAll, which allows reading through OneLake APIs and Spark.`},{id:`b`,text:`Read All with SQL analytics endpoint`,explain:`This grants T-SQL access only.`},{id:`c`,text:`Build`,explain:`Build is a semantic model permission for creating content.`},{id:`d`,text:`Execute`,explain:`Execute applies to running or cancelling items.`}],answer:`a`},{id:`IL-03`,machineId:f,bulletIds:[`M1.2`],format:`single`,difficulty:1,stem:`A report author in another workspace needs to build new reports on your semantic model. Which item permission should they have on the model?`,sources:[t.shareItems],options:[{id:`a`,text:`Share`,explain:`Share allows resharing, not building content.`},{id:`b`,text:`Build`,explain:`Correct. Build lets the user create new content on the semantic model.`},{id:`c`,text:`Read All with SQL analytics endpoint`,explain:`This is a lakehouse or warehouse permission.`},{id:`d`,text:`Execute`,explain:`Execute is for running items.`}],answer:`b`},{id:`IL-04`,machineId:f,bulletIds:[`M1.2`],format:`yesno`,difficulty:2,placement:!0,stem:`You are sharing Fabric items with users who have no workspace role. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.shareItems],statements:[{id:`s1`,text:`A link for “People with existing access” grants access to anyone who opens it.`,answer:!1,explain:`No. It generates a URL but doesn’t grant any access.`},{id:`s2`,text:`After you revoke a signed-in user’s item permission, it can take up to two hours to take effect.`,answer:!0,explain:`Yes. Learn states the delay for signed-in users.`},{id:`s3`,text:`The Shared with me option lists every type of Fabric item shared with you.`,answer:!1,explain:`No. It currently displays only Power BI items.`}]},{id:`IL-05`,machineId:f,bulletIds:[`M1.2`],format:`single`,difficulty:3,placement:!0,trapPairId:`access-layers`,stem:`You share a lakehouse with a user and grant only the default Read permission. They can open the item but get errors when querying tables through the SQL analytics endpoint. Why?`,sources:[t.shareItems,t.roles],options:[{id:`a`,text:`Read alone doesn’t include data access`,explain:`Correct. Item Read alone doesn’t include data access; add Read All with SQL analytics endpoint.`},{id:`b`,text:`Shared items need 24 hours before queries work`,explain:`The cause is the missing data permission; Read alone doesn’t include data access.`},{id:`c`,text:`The SQL analytics endpoint must be shared separately from the lakehouse`,explain:`The permission is chosen when sharing the lakehouse.`},{id:`d`,text:`SQL queries need the workspace Admin role`,explain:`Item permissions are enough; no role is required.`}],answer:`a`},{id:`IL-06`,machineId:f,bulletIds:[`M1.2`],format:`multi`,difficulty:2,placement:!0,stem:`You share a warehouse with a colleague. Which two permissions can you add on top of the default Read permission? Choose two.`,sources:[t.shareItems],options:[{id:`a`,text:`Workspace Member`,explain:`Workspace roles aren’t granted through item sharing.`},{id:`b`,text:`Share, so they can reshare the item`,explain:`Correct. Share lets them reshare up to their own permissions.`},{id:`c`,text:`Capacity Contributor`,explain:`Capacity permissions aren’t set by sharing an item.`},{id:`d`,text:`Read All with SQL analytics endpoint`,explain:`Correct. ReadData lets them read data with T-SQL.`}],answers:[`b`,`d`]},{id:`IL-07`,machineId:f,bulletIds:[`M1.2`],format:`single`,difficulty:2,placement:!0,stem:`You need to review who has access to a warehouse through sharing and remove one person’s Share permission. Where should you go?`,sources:[t.shareItems,t.giveAccess],options:[{id:`a`,text:`The workspace Manage access pane`,explain:`Manage access adds people to workspace roles, not item permissions.`},{id:`b`,text:`The OneLake catalog Govern tab`,explain:`Item permissions are reviewed and removed with Manage permissions on the item.`},{id:`c`,text:`The tenant admin portal`,explain:`Item permissions are managed on the item.`},{id:`d`,text:`Manage permissions on the warehouse`,explain:`Correct. Manage permissions lets you review and remove item permissions.`}],answer:`d`},{id:`IL-08`,machineId:f,bulletIds:[`M1.2`],format:`single`,difficulty:3,placement:!0,trapPairId:`access-layers`,stem:`A user has item Read on a warehouse. You also run DENY SELECT ON dbo.Payroll TO [that user]. What can they do with dbo.Payroll?`,sources:[t.whGranular,t.shareItems],options:[{id:`a`,text:`Query it, because item Read overrides SQL permissions`,explain:`SQL permissions apply on top of item access.`},{id:`b`,text:`Query it only from the visual query editor`,explain:`GRANT and DENY apply on top of item access, whichever SQL tool sends the query.`},{id:`c`,text:`Nothing; the DENY blocks SELECT on that table`,explain:`Correct. GRANT and DENY apply on top of the access that item Read provides.`},{id:`d`,text:`Query it through Spark instead`,explain:`Item Read alone doesn’t grant Spark data access either.`}],answer:`c`},{id:`IL-09`,machineId:f,bulletIds:[`M1.2`],format:`single`,difficulty:2,placement:!0,stem:`A user needs to open one report and one semantic model in a workspace, but nothing else there. What is the least-privileged approach?`,sources:[t.shareItems,t.roles],options:[{id:`a`,text:`Give the user the workspace Viewer role`,explain:`Viewer applies to every item in the workspace.`},{id:`b`,text:`Share the two items with the user`,explain:`Correct. Item sharing grants access to specific items without a workspace role.`},{id:`c`,text:`Create a new workspace and copy the items`,explain:`Copying duplicates content and adds maintenance.`},{id:`d`,text:`Add the user to the capacity’s contributors`,explain:`Item access comes from workspace roles or item sharing; sharing the two items is the targeted way.`}],answer:`b`},{id:`TS-01`,machineId:p,bulletIds:[`M1.3`],format:`dropdown`,difficulty:2,placement:!0,stem:`You need warehouse row-level security so that sales reps see only their own orders in sales.Orders. The predicate function Security.tvf_securitypredicate already exists. Complete the T-SQL.`,sources:[t.whRls,t.createSecurityPolicy],language:`tsql`,code:`CREATE [[1]] SalesFilter
ADD [[2]] PREDICATE Security.tvf_securitypredicate(SalesRep)
ON sales.Orders
WITH (STATE = [[3]]);`,slots:[{id:`1`,options:[{id:`a`,text:`ROLE`,explain:`A database role groups users; it doesn’t bind a predicate to a table.`},{id:`b`,text:`SECURITY POLICY`,explain:`Correct. A security policy binds the predicate function to the table.`},{id:`c`,text:`VIEW`,explain:`A view isn’t how Fabric row-level security works; a security policy binds the predicate function to the table.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`FILTER`,explain:`Correct. A filter predicate silently filters rows for SELECT, UPDATE, and DELETE.`},{id:`b`,text:`MASK`,explain:`Masking is dynamic data masking, defined on columns.`},{id:`c`,text:`CHECK`,explain:`Security policies use FILTER (and BLOCK) predicates, not CHECK.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`OFF`,explain:`OFF creates the policy but doesn’t enforce it.`},{id:`b`,text:`ENABLED`,explain:`The STATE option takes ON or OFF.`},{id:`c`,text:`ON`,explain:`Correct. STATE = ON enforces the policy.`}],answer:`c`}]},{id:`TS-02`,machineId:p,bulletIds:[`M1.3`],format:`single`,difficulty:2,placement:!0,trapPairId:`cls-vs-ols-vs-ddm`,stem:`Support staff must query dbo.Customers in a Fabric warehouse but must never read the CreditCard column. Queries that touch it should fail. What should you implement?`,sources:[t.whCls],options:[{id:`a`,text:`Dynamic data masking on CreditCard`,explain:`Masking still returns the column, with obscured values, instead of failing.`},{id:`b`,text:`A security policy with a filter predicate`,explain:`RLS filters rows, not columns.`},{id:`c`,text:`A sensitivity label on the warehouse`,explain:`Labels classify items; they don’t deny a column in SQL.`},{id:`d`,text:`GRANT SELECT on every column except CreditCard`,explain:`Correct. Column-level security: a query that touches CreditCard fails with a permission error.`}],answer:`d`},{id:`TS-03`,machineId:p,bulletIds:[`M1.3`],format:`single`,difficulty:2,placement:!0,stem:`Users must not be able to see that a Salaries table exists in a semantic model, including in the field list. Which feature should you use?`,sources:[t.modelOls],options:[{id:`a`,text:`Object-level security in a model role`,explain:`Correct. OLS hides the table or column, including its metadata, from members of the role.`},{id:`b`,text:`Row-level security with a FALSE() filter`,explain:`RLS filters rows; it doesn’t hide the table or its metadata the way OLS does.`},{id:`c`,text:`Hiding the table in report view`,explain:`Hiding a table in a view isn’t security; OLS is the feature that secures tables and columns.`},{id:`d`,text:`Dynamic data masking in the source`,explain:`Masking is a warehouse column feature; hiding a model table from a role is OLS.`}],answer:`a`},{id:`TS-04`,machineId:p,bulletIds:[`M1.3`],format:`single`,difficulty:2,placement:!0,stem:`Each sales manager should see only rows for their own region in a semantic model. A mapping table relates each manager’s email to their region. Which DAX filter should the role use on the mapping table?`,sources:[t.modelRls],options:[{id:`a`,text:`[UserEmail] = USERNAME() && FALSE()`,explain:`Adding FALSE() returns no rows for anyone.`},{id:`b`,text:`[UserEmail] = USERPRINCIPALNAME()`,explain:`Correct. Dynamic RLS matches each signed-in user’s UPN, and the filter flows through relationships.`},{id:`c`,text:`[Region] = SELECTEDVALUE([Region])`,explain:`This depends on report selections, not on who is signed in.`},{id:`d`,text:`[UserEmail] = "manager@contoso.com"`,explain:`A static filter shows the same rows to every member.`}],answer:`b`},{id:`TS-05`,machineId:p,bulletIds:[`M1.3`],format:`yesno`,difficulty:3,placement:!0,stem:`You are implementing row-level security in a Fabric warehouse. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.whRls,t.whGranular],statements:[{id:`s1`,text:`Security policies also filter rows for dbo users and members of db_owner.`,answer:!0,explain:`Yes. Security policies apply to all users, including dbo.`},{id:`s2`,text:`You can change the predicate function while the security policy that uses it still exists.`,answer:!1,explain:`No. Drop the policy, alter the function, then recreate the policy.`},{id:`s3`,text:`You must run CREATE USER for each analyst before granting permissions.`,answer:!1,explain:`No. You can’t run CREATE USER in a Fabric warehouse; the user is created on GRANT or DENY.`}]},{id:`TS-06`,machineId:p,bulletIds:[`M1.3`],format:`single`,difficulty:3,placement:!0,stem:`You define RLS in a lakehouse’s SQL analytics endpoint. A Direct Lake on SQL semantic model uses that table, with DirectLakeBehavior left at its default. What happens to the model’s queries on it?`,sources:[t.dlHow,t.directLake],options:[{id:`a`,text:`They stay in Direct Lake and ignore the SQL RLS`,explain:`SQL-based security is a fallback condition for Direct Lake on SQL, so queries don’t stay in Direct Lake.`},{id:`b`,text:`They fail until the RLS is removed`,explain:`Failing is the DirectLakeOnly behavior; the default, Automatic, falls back silently.`},{id:`c`,text:`They fall back to DirectQuery`,explain:`Correct. SQL RLS on a table is a fallback condition for Direct Lake on SQL.`},{id:`d`,text:`The model copies the RLS rules into its own roles`,explain:`SQL RLS isn’t converted into model roles.`}],answer:`c`},{id:`TS-07`,machineId:p,bulletIds:[`M1.3`],format:`single`,difficulty:2,placement:!0,trapPairId:`access-layers`,stem:`You set object-level DENY permissions in a lakehouse’s SQL analytics endpoint. The same users read the lakehouse tables from a Spark notebook with ReadAll permission. What do they see in Spark?`,sources:[t.endpoint],options:[{id:`a`,text:`All the data in those tables`,explain:`Correct. SQL security rules on the endpoint don’t apply when the data is accessed through Spark.`},{id:`b`,text:`Only the tables they can query in SQL`,explain:`Spark doesn’t evaluate SQL endpoint permissions.`},{id:`c`,text:`An error, because ReadAll conflicts with DENY`,explain:`The two permissions apply to different engines.`},{id:`d`,text:`Masked values for the denied tables`,explain:`Masking isn’t what a DENY does.`}],answer:`a`},{id:`TS-08`,machineId:p,bulletIds:[`M1.3`],format:`match`,difficulty:2,placement:!0,trapPairId:`cls-vs-ols-vs-ddm`,stem:`Match each requirement to the security feature that meets it.`,sources:[t.whCls,t.whDdm,t.modelOls,t.whRls],prompts:[{id:`p1`,text:`Queries that touch the Salary column in a warehouse must fail`},{id:`p2`,text:`Show only the last four digits of phone numbers to most warehouse users`},{id:`p3`,text:`Hide a column, including its name, from a semantic model role`},{id:`p4`,text:`Each rep sees only their own rows in a warehouse table`}],choices:[{id:`c1`,text:`Column-level security (GRANT on columns)`},{id:`c2`,text:`Dynamic data masking`},{id:`c3`,text:`Semantic model object-level security`},{id:`c4`,text:`Warehouse row-level security`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`CLS denies the column; queries touching it fail.`},{promptId:`p2`,choiceId:`c2`,explain:`Masking returns the column with obscured values for non-privileged users.`},{promptId:`p3`,choiceId:`c3`,explain:`OLS hides the field and its metadata from the role.`},{promptId:`p4`,choiceId:`c4`,explain:`A security policy filters rows per user.`}]},{id:`TS-09`,machineId:p,bulletIds:[`M1.3`],format:`single`,difficulty:2,placement:!0,trapPairId:`cls-vs-ols-vs-ddm`,stem:`A security reviewer proposes dynamic data masking as the only protection for national ID numbers in a warehouse. What does Learn advise?`,sources:[t.whDdm],options:[{id:`a`,text:`Masking alone is sufficient, because stored data is encrypted`,explain:`Masking doesn’t encrypt or change stored data.`},{id:`b`,text:`Combine masking with column- and row-level security`,explain:`Correct. Masking only obscures results, so Learn recommends combining it with CLS and RLS.`},{id:`c`,text:`Replace masking with a sensitivity label`,explain:`Labels don’t restrict columns in SQL queries.`},{id:`d`,text:`Apply masking in the semantic model instead`,explain:`Dynamic data masking is a warehouse feature.`}],answer:`b`},{id:`TS-10`,machineId:p,bulletIds:[`M1.3`],format:`single`,difficulty:3,placement:!0,stem:`A lakehouse holds raw files for three regions under Files/raw/<region>. Each region’s analysts, who are workspace Viewers, may read only their own folder, from Spark or any engine that honors OneLake security. What should you create?`,sources:[t.onelakeSecurity,t.onelakeAccessModel],options:[{id:`a`,text:`A security policy in the SQL analytics endpoint`,explain:`SQL policies filter rows in SQL queries only, not file folders read by Spark.`},{id:`b`,text:`A semantic model role per region`,explain:`Model roles restrict the semantic model only.`},{id:`c`,text:`A OneLake security role per region`,explain:`Correct. OneLake security roles grant read access to chosen folders and are enforced across engines.`},{id:`d`,text:`Three workspaces, one per region`,explain:`This splits the data instead of securing it in place.`}],answer:`c`},{id:`TS-11`,machineId:p,bulletIds:[`M1.3`],format:`single`,difficulty:2,placement:!0,stem:`You need a OneLake security role that lets a group write to a lakehouse table and also restricts which rows they can see. What happens?`,sources:[t.onelakeAccessModel],options:[{id:`a`,text:`The role works; write access applies only to visible rows`,explain:`Learn doesn’t allow RLS constraints on ReadWrite roles.`},{id:`b`,text:`It isn’t possible in one role`,explain:`Correct. Roles that grant ReadWrite can’t also have RLS or CLS constraints.`},{id:`c`,text:`The row filter is ignored for writes but enforced for reads`,explain:`The combination isn’t allowed in one role.`},{id:`d`,text:`The role converts to a SQL security policy`,explain:`OneLake roles aren’t converted to SQL objects.`}],answer:`b`},{id:`SL-01`,machineId:m,bulletIds:[`M1.4`],format:`single`,difficulty:2,placement:!0,stem:`A lakehouse is labeled Highly Confidential. A semantic model and report are later built on it. You want the label to flow to those items without manual labeling. Which capability does this?`,sources:[t.infoProtection],options:[{id:`a`,text:`Mandatory labeling`,explain:`Mandatory labeling forces users to pick a label; it doesn’t copy one.`},{id:`b`,text:`Endorsement as Certified`,explain:`Endorsement signals trust and has nothing to do with labels.`},{id:`c`,text:`Default labeling`,explain:`Default labeling applies a preset label to new items, not the source item’s label.`},{id:`d`,text:`Downstream inheritance`,explain:`Correct. A label propagates downstream to items that depend on the labeled item.`}],answer:`d`},{id:`SL-02`,machineId:m,bulletIds:[`M1.4`],format:`yesno`,difficulty:2,placement:!0,stem:`A report has a sensitivity label with an encryption (publishing) policy. For each export, select Yes if the label’s protection stays with the exported file. Otherwise, select No.`,sources:[t.infoProtection],statements:[{id:`s1`,text:`Export to PDF`,answer:!0,explain:`Yes. Export to Excel, PDF, and PowerPoint are supported export paths.`},{id:`s2`,text:`Export of visual data to a .csv file`,answer:!1,explain:`No. Access control in other export paths, such as .csv or .txt, is unsupported.`},{id:`s3`,text:`Export to PowerPoint`,answer:!0,explain:`Yes. PowerPoint is a supported export path.`}]},{id:`SL-03`,machineId:m,bulletIds:[`M1.4`],format:`single`,difficulty:2,placement:!0,stem:`A user with a Microsoft Fabric Free license can’t apply sensitivity labels to Power BI reports, although the labels are published to them. What do they need, according to Learn?`,sources:[t.infoProtection],options:[{id:`a`,text:`A Power BI Pro or Premium Per User license`,explain:`Correct. Labeling Power BI items needs Pro or PPU in addition to the Purview licensing.`},{id:`b`,text:`The workspace Admin role`,explain:`Role isn’t the documented requirement.`},{id:`c`,text:`A Fabric capacity of F64 or larger`,explain:`Capacity size isn’t the documented requirement.`},{id:`d`,text:`Certification rights from the Fabric admin`,explain:`Certification is endorsement, not labeling.`}],answer:`a`},{id:`SL-04`,machineId:m,bulletIds:[`M1.4`],format:`single`,difficulty:3,placement:!0,stem:`A governance team must apply sensitivity labels to 800 existing items in bulk, without opening each one. What should they use?`,sources:[t.infoProtection],options:[{id:`a`,text:`Downstream inheritance from one labeled item`,explain:`Inheritance only reaches items that depend on the labeled item.`},{id:`b`,text:`Endorse all items as Master data`,explain:`Endorsement isn’t labeling.`},{id:`c`,text:`The Power BI admin REST APIs`,explain:`Correct. Labels can be added, changed, or deleted programmatically through the admin REST APIs.`},{id:`d`,text:`A deployment pipeline rule`,explain:`Deployment rules change data sources and parameters, not labels.`}],answer:`c`},{id:`SL-05`,machineId:m,bulletIds:[`M1.4`],format:`single`,difficulty:2,placement:!0,stem:`A semantic model imports data from an Azure SQL table that carries a Confidential label. Which labeling capability can apply that label to the semantic model automatically?`,sources:[t.infoProtection],options:[{id:`a`,text:`Inheritance from data sources`,explain:`Correct. It’s currently supported for Power BI semantic models only.`},{id:`b`,text:`Downstream inheritance`,explain:`Downstream inheritance flows from Fabric items to items built on them, not from external sources.`},{id:`c`,text:`Mandatory labeling`,explain:`Mandatory labeling requires users to choose a label.`},{id:`d`,text:`Promotion`,explain:`Promotion is endorsement.`}],answer:`a`},{id:`SL-06`,machineId:m,bulletIds:[`M1.4`],format:`single`,difficulty:2,placement:!0,stem:`A labeled semantic model is shared with a partner organization through cross-tenant external data sharing. Does the label’s access control protect the data in the partner tenant?`,sources:[t.infoProtection],options:[{id:`a`,text:`Yes, labels are enforced in every tenant that opens the data`,explain:`Learn says access control only applies in the tenant where the label was applied and in supported exports.`},{id:`b`,text:`Yes, but only when both tenants use Premium capacities`,explain:`Capacity type doesn’t change cross-tenant behavior.`},{id:`c`,text:`Only if the partner has the same label names`,explain:`Matching names doesn’t make access control work across tenants.`},{id:`d`,text:`No, label access control isn’t supported across tenants`,explain:`Correct. Access control in cross-tenant scenarios is unsupported.`}],answer:`d`},{id:`SL-07`,machineId:m,bulletIds:[`M1.5`],format:`single`,difficulty:1,placement:!0,trapPairId:`endorse-vs-label`,stem:`A lakehouse holds the company’s official customer list, which every team should use as the single source of truth. Which endorsement fits best?`,sources:[t.endorsement],options:[{id:`a`,text:`Promoted`,explain:`Promoted says the creator thinks it’s ready to share, not that it’s authoritative.`},{id:`b`,text:`Master data`,explain:`Correct. Master data marks a data item as the authoritative source for core data such as customer lists.`},{id:`c`,text:`Certified`,explain:`Certified means it meets quality standards; Master data is specific to authoritative core data.`},{id:`d`,text:`A Confidential sensitivity label`,explain:`A label states sensitivity, not authority.`}],answer:`b`},{id:`SL-08`,machineId:m,bulletIds:[`M1.5`],format:`yesno`,difficulty:2,placement:!0,stem:`Your organization is rolling out endorsement in Fabric. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.endorsement],statements:[{id:`s1`,text:`Any user with write permission on an item can promote it.`,answer:!0,explain:`Yes. Promotion needs only write permission.`},{id:`s2`,text:`Any user can request certification, but only users specified by a Fabric admin can certify.`,answer:!0,explain:`Yes. Learn states both.`},{id:`s3`,text:`Power BI dashboards can be certified.`,answer:!1,explain:`No. Any item except Power BI dashboards can be promoted or certified.`}]},{id:`SL-10`,machineId:m,bulletIds:[`M1.5`],format:`single`,difficulty:2,placement:!0,stem:`Users report that the Certified option is greyed out for every item, even for the data governance lead. What is the most likely cause?`,sources:[t.endorsement],options:[{id:`a`,text:`Certification isn’t enabled by a Fabric admin`,explain:`Correct. Certification must be enabled by a Fabric admin, who also specifies the certifiers.`},{id:`b`,text:`The items aren’t labeled`,explain:`Certification doesn’t depend on labels.`},{id:`c`,text:`The items must be promoted for 30 days first`,explain:`There’s no waiting period.`},{id:`d`,text:`Only dashboards can be certified`,explain:`It’s the opposite: dashboards can’t be certified.`}],answer:`a`},{id:`SL-11`,machineId:m,bulletIds:[`M1.5`],format:`match`,difficulty:1,placement:!0,trapPairId:`endorse-vs-label`,stem:`Match each governance signal to who can apply it.`,sources:[t.endorsement],prompts:[{id:`p1`,text:`Promoted`},{id:`p2`,text:`Certified`},{id:`p3`,text:`Master data`}],choices:[{id:`c1`,text:`Any user with write permission on the item`},{id:`c2`,text:`Users specified by a Fabric admin, after anyone requests it`},{id:`c3`,text:`Users specified by a Fabric admin, for items that contain data`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Promotion needs only write permission.`},{promptId:`p2`,choiceId:`c2`,explain:`Anyone can request certification; designated users certify.`},{promptId:`p3`,choiceId:`c3`,explain:`Master data applies to data items and only admin-specified users can apply it.`}]},{id:`SL-12`,machineId:m,bulletIds:[`M1.5`],format:`multi`,difficulty:2,placement:!0,trapPairId:`endorse-vs-label`,stem:`Which two statements correctly contrast endorsement with sensitivity labels? Choose two.`,sources:[t.endorsement,t.infoProtection],options:[{id:`a`,text:`Endorsement helps people find trustworthy items; labels classify how sensitive data is`,explain:`Correct. They answer different questions.`},{id:`b`,text:`Endorsement encrypts exported files`,explain:`Encryption on export comes from labels with publishing policies.`},{id:`c`,text:`Labels can only be applied to semantic models`,explain:`Manual labeling is supported for all Fabric items.`},{id:`d`,text:`Labels come from Microsoft Purview and can propagate downstream`,explain:`Correct. Labels are Purview classifications with downstream inheritance.`}],answers:[`a`,`d`]}],ae=`gate-keys`,h=`seal-and-stamp`,oe=[{id:`GK-H1`,machineId:ae,bulletIds:[`M1.1`],format:`single`,difficulty:3,trapPairId:`member-vs-contributor`,stem:`Dana belongs to two security groups. Group A has the Viewer role on the Sales workspace and is a member of the semantic model’s Region RLS role. Group B has the Contributor role on the same workspace. Dana sees every region’s rows in a report built on the model. Why?`,sources:[t.roles,t.modelRls],options:[{id:`a`,text:`RLS roles are additive, so membership in two groups shows every region`,explain:`Roles are additive across RLS roles, but here only one RLS role is involved; the cause is Dana’s workspace role.`},{id:`b`,text:`Viewers bypass RLS when they also have Build permission`,explain:`Build doesn’t change it: RLS restricts users with Viewer permissions.`},{id:`c`,text:`Dana gets the highest role assigned through her groups, Contributor, and RLS only restricts Viewers`,explain:`Correct. A user in several groups gets the highest role they’re assigned, and semantic model RLS doesn’t apply to Admins, Members, or Contributors, who can edit the model.`},{id:`d`,text:`Workspace roles apply at capacity level, so the Viewer assignment is ignored`,explain:`Workspace roles apply only to that workspace, not to the capacity.`}],answer:`c`},{id:`SL-H1`,machineId:h,bulletIds:[`M1.5`],format:`single`,difficulty:3,trapPairId:`endorse-vs-label`,stem:`A data governance lead wants three things: the customer lakehouse marked as the organization’s authoritative customer list, the sales semantic model marked as meeting quality standards, and the executive dashboard marked the same way. The lead has write permission on all three but isn’t on any admin-specified list. Which plan is possible?`,sources:[t.endorsement],options:[{id:`a`,text:`The lead applies Master data to the lakehouse, certifies the model, and certifies the dashboard`,explain:`Master data and certification can only be applied by users the Fabric admin specifies, and dashboards can’t be endorsed.`},{id:`b`,text:`An admin-specified user applies Master data to the lakehouse, an authorized reviewer certifies the model, and the dashboard stays unendorsed`,explain:`Correct. Only admin-specified users can apply Master data or certify, Master data applies to items that contain data, and Power BI dashboards can’t be promoted or certified.`},{id:`c`,text:`The lead promotes all three items, which makes them authoritative`,explain:`Promotion only says the creator thinks the item is ready to share, and dashboards can’t be promoted.`},{id:`d`,text:`An admin applies a sensitivity label to all three items to mark them as authoritative`,explain:`A sensitivity label says how sensitive data is, not how trustworthy it is.`}],answer:`b`},{id:`SL-H2`,machineId:h,bulletIds:[`M1.5`],format:`yesno`,difficulty:3,stem:`A company organizes Fabric content into domains and wants each domain to manage its own certification. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.endorsement],statements:[{id:`s1`,text:`A Fabric admin can delegate certification to domain admins so each domain has its own reviewers.`,answer:!0,explain:`Yes. Certification must be enabled by a Fabric admin and can be delegated to domain admins.`},{id:`s2`,text:`Only users the Fabric admin specifies can certify items.`,answer:!0,explain:`Yes. Anyone can request certification, but only authorized reviewers specified by the Fabric admin can certify.`},{id:`s3`,text:`Promoting an item requires approval from a Fabric admin.`,answer:!1,explain:`No. Any user with write permission on an item can promote it (Power BI dashboards can’t be endorsed).`}]},{id:`SL-H3`,machineId:h,bulletIds:[`M1.4`],format:`single`,difficulty:2,stem:`A semantic model carries a sensitivity label with protection from Microsoft Purview. Analysts export data from reports built on it in several ways. In which case does the label’s protection travel with the exported file?`,sources:[t.infoProtection],options:[{id:`a`,text:`Export to a CSV file`,explain:`CSV and TXT exports aren’t protected.`},{id:`b`,text:`Sharing the data with a user in another tenant`,explain:`Label access control works only in the tenant where it was applied.`},{id:`c`,text:`Export to Excel`,explain:`Correct. Protection travels with Excel, PDF, and PowerPoint exports and with .pbix downloads.`},{id:`d`,text:`Copying a visual’s values to the clipboard and pasting them into a text file`,explain:`Learn lists supported export paths; plain text isn’t one of them, so protection doesn’t follow.`}],answer:`c`},{id:`PL-H1`,machineId:`pattern-ledger`,bulletIds:[`M2.1`],format:`single`,difficulty:3,trapPairId:`commit-vs-update`,stem:`Git integration is enabled for the tenant. A workspace Member must connect the team workspace to a GitHub branch, and later the Contributors on the team must be able to switch the workspace to a feature branch themselves. What has to happen?`,sources:[t.gitProcess,t.roles],options:[{id:`a`,text:`The Member connects the workspace; Contributors can switch branches by default`,explain:`Only a workspace Admin can connect a workspace to Git, and switching branches needs an Admin setting.`},{id:`b`,text:`A workspace Admin connects the workspace and turns on “Allow users with at least Contributor role to change Git branch”`,explain:`Correct. Only Admins connect or disconnect a workspace, and Members and Contributors can switch the connected branch only after an Admin enables that setting.`},{id:`c`,text:`A tenant admin connects the workspace from the admin portal and gives Contributors the Member role`,explain:`Workspace connection happens in the workspace by a workspace Admin, and Member still can’t connect it.`},{id:`d`,text:`The Member commits all items first, which connects the workspace to the branch`,explain:`Committing needs an existing connection; it doesn’t create one.`}],answer:`b`},{id:`RM-H1`,machineId:`ripple-map`,bulletIds:[`M2.4`],format:`single`,difficulty:3,trapPairId:`lineage-vs-impact`,stem:`You plan to drop a column from a lakehouse table. Reports in three other workspaces may depend on it through semantic models, and their owners must be warned before the change. You have write permission on the lakehouse. What should you do?`,sources:[t.impact,t.lineage],options:[{id:`a`,text:`Open lineage view in the lakehouse’s workspace and email the owners of the items it shows`,explain:`Lineage view shows the items in its own workspace (plus upstream sources one level out), not downstream items in other workspaces.`},{id:`b`,text:`Open impact analysis on the lakehouse, switch to All downstream items, and use Notify contacts`,explain:`Correct. Impact analysis lists downstream items across workspaces, and Notify contacts emails the contact lists of all affected workspaces.`},{id:`c`,text:`Open impact analysis on each report as a Viewer`,explain:`Impact analysis needs write permission on the item, and starting from the reports misses what depends on the lakehouse.`},{id:`d`,text:`Search the OneLake catalog for items with the column name`,explain:`The catalog helps discover items; it doesn’t trace dependencies or notify owners.`}],answer:`b`},{id:`PB-H1`,machineId:`pattern-book`,bulletIds:[`M2.6`],format:`single`,difficulty:2,stem:`A certified shared semantic model lives in a workspace on an F32 capacity. Report authors in other workspaces have only free licenses and were granted Build permission, but they can’t build reports on the model. What would let them build reports while keeping their free licenses?`,sources:[t.sharedModels],options:[{id:`a`,text:`Grant them Reshare permission on the model`,explain:`Resharing doesn’t change the capacity requirement for free users.`},{id:`b`,text:`Promote the model in addition to certifying it`,explain:`Endorsement helps discovery; it doesn’t change licensing or access.`},{id:`c`,text:`Export the model as a .pbit for each author`,explain:`A template copies the model definition without data; it doesn’t give access to the shared model.`},{id:`d`,text:`Move the model’s workspace to a Premium or an F64-or-larger capacity`,explain:`Correct. Free-license users can build reports from shared models with Build permission only when the model is on Premium or an F64-or-larger capacity.`}],answer:`d`},{id:`DT-H1`,machineId:`draft-table`,bulletIds:[`M2.2`],format:`yesno`,difficulty:3,trapPairId:`pbi-files`,stem:`Your team saves a report as a Power BI Desktop project (.pbip), commits it to Git, and deploys it through Fabric Git integration. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.pbip],statements:[{id:`s1`,text:`The generated .gitignore keeps the local data cache (cache.abf) out of source control.`,answer:!0,explain:`Yes. The .gitignore excludes cache.abf and localSettings.json, so data isn’t committed.`},{id:`s2`,text:`Deploying through Git integration also deploys the model’s data, so no refresh is needed.`,answer:!1,explain:`No. Paths other than Desktop Publish deploy metadata only, so the data isn’t deployed.`},{id:`s3`,text:`The project can’t be opened without its .pbip file.`,answer:!1,explain:`No. The .pbip file is optional; you can open the report from its definition.pbir.`}]},{id:`RL-H1`,machineId:`remote-loom-control`,bulletIds:[`M2.5`],format:`single`,difficulty:3,trapPairId:`xmla-read-vs-readwrite`,stem:`An engineer wants to run a TMSL refresh from SSMS that reloads one partition of a model with an incremental refresh policy, overriding the policy for that run. The workspace is on a Fabric capacity, and the engineer can already query the model from DAX Studio. Which combination is required?`,sources:[t.xmla,t.tmslRefresh,t.largeModels],options:[{id:`a`,text:`The capacity’s XMLA Endpoint set to Read Write, and the engineer at least Contributor in the workspace`,explain:`Correct. Writes such as TMSL refresh need read-write XMLA (read-only is the default), and Contributors and above have Write permission on semantic models over XMLA. TMSL refresh can override an incremental refresh policy.`},{id:`b`,text:`The default read-only XMLA setting, and Build permission on the model`,explain:`Read-only allows queries like the DAX Studio ones, not refresh operations.`},{id:`c`,text:`The workspace moved to Pro, and the engineer made a Viewer`,explain:`Pro workspaces don’t support XMLA write operations, and Viewers don’t have Write permission.`},{id:`d`,text:`XMLA set to Read Write on the workspace only, with the engineer as a Viewer`,explain:`The XMLA setting is a capacity setting that applies to all its workspaces, and a Viewer can’t write.`}],answer:`a`}],g=`pattern-ledger`,_=`draft-table`,v=`conveyor`,y=`ripple-map`,b=`remote-loom-control`,x=`pattern-book`,se=[{id:`PL-01`,machineId:g,bulletIds:[`M2.1`],format:`single`,difficulty:1,stem:`Your team wants version history, branching, and the ability to revert changes for the items in a Fabric workspace. What should you configure?`,sources:[t.gitIntro],options:[{id:`a`,text:`A deployment pipeline with three stages`,explain:`Deployment pipelines promote content between stages; they don’t provide version history.`},{id:`b`,text:`Git integration with an Azure DevOps or GitHub branch`,explain:`Correct. Git integration versions item definitions in a connected branch.`},{id:`c`,text:`Workspace folders with dates in their names`,explain:`Folders organize items; they don’t keep history.`},{id:`d`,text:`A OneLake shortcut to a backup lakehouse`,explain:`A shortcut references data; it doesn’t version item definitions.`}],answer:`b`},{id:`PL-02`,machineId:g,bulletIds:[`M2.1`],format:`single`,difficulty:2,trapPairId:`commit-vs-update`,stem:`A teammate merged changes into the Git branch connected to your workspace. The Source control pane shows those items as Update required. What should you do to bring the changes into the workspace?`,sources:[t.gitIntro,t.gitProcess],options:[{id:`a`,text:`Select Commit`,explain:`Commit sends workspace changes to Git, the opposite direction.`},{id:`b`,text:`Disconnect and reconnect the workspace`,explain:`Reconnecting isn’t needed to pull changes.`},{id:`c`,text:`Select Update`,explain:`Correct. Update brings the branch’s latest commit into the workspace.`},{id:`d`,text:`Deploy the items with a deployment pipeline`,explain:`Pipelines copy between stage workspaces, not from Git.`}],answer:`c`},{id:`PL-03`,machineId:g,bulletIds:[`M2.1`],format:`yesno`,difficulty:2,stem:`You are setting up Git integration for a Fabric workspace. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.gitIntro,t.gitProcess],statements:[{id:`s1`,text:`Only a workspace Admin can connect the workspace to a Git repository.`,answer:!0,explain:`Yes. After the connection, Members and Contributors can commit and update.`},{id:`s2`,text:`Git integration works with on-premises Git servers.`,answer:!1,explain:`No. Supported providers are cloud-based only: Azure DevOps, GitHub, and GitHub Enterprise.`},{id:`s3`,text:`Empty workspace folders are copied to Git.`,answer:!1,explain:`No. Empty folders aren’t copied.`}]},{id:`PL-04`,machineId:g,bulletIds:[`M2.1`],format:`order`,difficulty:2,stem:`You need to start versioning a Fabric workspace in GitHub. Put the steps in order.`,sources:[t.gitIntro,t.gitProcess],items:[{id:`i2`,text:`A workspace Admin connects the workspace to a repository branch and folder`,explain:`Second. The connection needs the tenant setting and the Admin role.`},{id:`i4`,text:`Developers commit workspace changes to the branch`,explain:`Last. Ongoing work flows through commits and updates.`},{id:`i1`,text:`A Fabric admin enables Git integration for the organization`,explain:`First. The organization’s admin must enable the feature.`},{id:`i3`,text:`Choose the direction of the initial sync`,explain:`Third. When both sides have content, you choose which overwrites the other.`}],answerOrder:[`i1`,`i2`,`i3`,`i4`]},{id:`PL-05`,machineId:g,bulletIds:[`M2.1`],format:`single`,difficulty:3,trapPairId:`commit-vs-update`,stem:`You connect a workspace that already contains items to a Git branch that also contains different items. You choose to sync from Git to the workspace. What is the risk?`,sources:[t.gitProcess],options:[{id:`a`,text:`Workspace items are overwritten irreversibly`,explain:`Correct. Updating overwrites the workspace, and unlike a Git branch the workspace can’t be rolled back.`},{id:`b`,text:`The Git branch is deleted and recreated`,explain:`Updating the workspace doesn’t change the branch.`},{id:`c`,text:`Both versions are merged automatically`,explain:`Fabric doesn’t merge; one side overwrites the other.`},{id:`d`,text:`Nothing happens until a deployment pipeline runs`,explain:`Pipelines are unrelated to Git sync.`}],answer:`a`},{id:`PL-06`,machineId:g,bulletIds:[`M2.1`],format:`single`,difficulty:2,stem:`A Contributor wants to switch the workspace to a different connected Git branch, but the option is blocked. The workspace Admin wants to allow it. What should the Admin do?`,sources:[t.gitProcess],options:[{id:`a`,text:`Make the Contributor a pipeline admin`,explain:`Pipeline admin has nothing to do with Git branches.`},{id:`b`,text:`Disconnect Git so anyone can reconnect`,explain:`Only Admins can connect, so this wouldn’t help.`},{id:`c`,text:`Grant the Contributor Build permission on every item`,explain:`Build permission is for semantic models.`},{id:`d`,text:`Enable the workspace setting that lets Contributors change branch`,explain:`Correct. This workspace setting lets Members and Contributors with write access to all items switch the connected branch.`}],answer:`d`},{id:`PL-07`,machineId:g,bulletIds:[`M2.1`],format:`match`,difficulty:1,trapPairId:`commit-vs-update`,stem:`Match each Git status in the Source control pane to what it means.`,sources:[t.gitIntro,t.gitProcess],prompts:[{id:`p1`,text:`Uncommitted changes`},{id:`p2`,text:`Update required`},{id:`p3`,text:`Conflict`}],choices:[{id:`c1`,text:`The workspace item changed and should be committed`},{id:`c2`,text:`The branch has a newer version to bring into the workspace`},{id:`c3`,text:`The item changed in both the workspace and Git`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Commit sends the change to Git.`},{promptId:`p2`,choiceId:`c2`,explain:`Update brings the branch’s version into the workspace.`},{promptId:`p3`,choiceId:`c3`,explain:`Changes on both sides must be resolved.`}]},{id:`DT-01`,machineId:_,bulletIds:[`M2.2`],format:`single`,difficulty:1,trapPairId:`pbi-files`,stem:`Developers want to review changes to a Power BI report and its semantic model as text diffs in pull requests. How should they save their work in Power BI Desktop?`,sources:[t.pbip],options:[{id:`a`,text:`As a Power BI template (.pbit)`,explain:`A template is a starting point without data, not a source-control format.`},{id:`b`,text:`As a .pbix file`,explain:`A .pbix is a single file, not the separate plain-text files a project uses for source control.`},{id:`c`,text:`As a Power BI project (.pbip)`,explain:`Correct. A project stores definitions as plain-text files designed for source control.`},{id:`d`,text:`As a .pbids file`,explain:`A .pbids file holds only a data source connection.`}],answer:`c`},{id:`DT-02`,machineId:_,bulletIds:[`M2.2`],format:`yesno`,difficulty:2,trapPairId:`pbi-files`,stem:`You saved a report named Sales as a Power BI project. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.pbip],statements:[{id:`s1`,text:`The project includes Sales.Report and Sales.SemanticModel folders.`,answer:!0,explain:`Yes. Saving as a project creates the report and semantic model folders.`},{id:`s2`,text:`The generated .gitignore excludes the local data cache, so data isn’t committed.`,answer:!0,explain:`Yes. cache.abf and localSettings.json are ignored.`},{id:`s3`,text:`The Sales.pbip file contains the full report definition.`,answer:!1,explain:`No. The .pbip only points to the report folder; the definition files hold the content.`}]},{id:`DT-03`,machineId:_,bulletIds:[`M2.2`],format:`single`,difficulty:2,stem:`In a Power BI project, in which format is the semantic model’s metadata stored so that it can be edited in VS Code?`,sources:[t.pbip],options:[{id:`a`,text:`TMDL files`,explain:`Correct. Model metadata is stored as TMDL files.`},{id:`b`,text:`A binary cache.abf file`,explain:`cache.abf is the local data cache, and it’s git-ignored.`},{id:`c`,text:`One XML file per table`,explain:`This isn’t the project format.`},{id:`d`,text:`CSV exports of each table`,explain:`Projects don’t store data as CSV.`}],answer:`a`},{id:`DT-04`,machineId:_,bulletIds:[`M2.2`],format:`single`,difficulty:2,stem:`A developer tries to save a Power BI project directly to a SharePoint document library from Power BI Desktop. What should you tell them?`,sources:[t.pbip],options:[{id:`a`,text:`Save it as a .pbit instead`,explain:`A template doesn’t solve source control or storage.`},{id:`b`,text:`It isn’t supported; save to a local folder`,explain:`Correct. Learn lists this limitation, and synced OneDrive folders can cause sync failures.`},{id:`c`,text:`Turn on the large storage format first`,explain:`Storage format doesn’t affect where Desktop saves projects.`},{id:`d`,text:`Publish the project to a workspace and download it`,explain:`This doesn’t give a project in SharePoint.`}],answer:`b`},{id:`DT-05`,machineId:_,bulletIds:[`M2.2`],format:`single`,difficulty:3,stem:`A semantic model from a Power BI project reaches the service through Fabric Git integration, not through Desktop Publish. Reports on it show no data. Why?`,sources:[t.pbip],options:[{id:`a`,text:`Only metadata was deployed, not the data`,explain:`Correct. Other deployment paths deploy metadata only; Desktop Publish also sends the data cache.`},{id:`b`,text:`The .gitignore deleted the report pages`,explain:`The .gitignore excludes only the cache and local settings.`},{id:`c`,text:`Projects can’t contain Import tables`,explain:`Projects support Import models.`},{id:`d`,text:`The workspace needs a deployment pipeline first`,explain:`Pipelines aren’t required.`}],answer:`a`},{id:`DT-06`,machineId:_,bulletIds:[`M2.2`],format:`multi`,difficulty:2,stem:`Which two files does Power BI Desktop’s generated .gitignore exclude from a project? Choose two.`,sources:[t.pbip],options:[{id:`a`,text:`definition.pbir`,explain:`The report definition is what you want in source control.`},{id:`b`,text:`cache.abf`,explain:`Correct. The local data cache isn’t committed.`},{id:`c`,text:`localSettings.json`,explain:`Correct. User-specific local settings aren’t committed.`},{id:`d`,text:`The TMDL files`,explain:`TMDL holds the model metadata that should be committed.`}],answers:[`b`,`c`]},{id:`DT-07`,machineId:_,bulletIds:[`M2.2`],format:`single`,difficulty:1,stem:`A developer deleted the Sales.pbip file from a project folder by mistake. The Sales.Report and Sales.SemanticModel folders are intact. How can they open the report?`,sources:[t.pbip],options:[{id:`a`,text:`They can’t; the .pbip file is required`,explain:`The .pbip is optional, only a shortcut to the report folder.`},{id:`b`,text:`Restore it from the cache.abf file`,explain:`The cache holds data, not the pointer file.`},{id:`c`,text:`Open definition.pbir in the report folder`,explain:`Correct. You can open the report directly from its definition.pbir.`},{id:`d`,text:`Download the report from the service as .pbix`,explain:`That works only for published content and isn’t needed here.`}],answer:`c`},{id:`CV-01`,machineId:v,bulletIds:[`M2.3`],format:`single`,difficulty:2,stem:`A pipeline admin with no role in the Test workspace tries to deploy a notebook from Development to Test and can’t. What else do they need?`,sources:[t.pipelinesProcess],options:[{id:`a`,text:`At least Contributor in both the source and target workspaces`,explain:`Correct. Deploying between stages needs pipeline admin plus Contributor, Member, or Admin on both workspaces.`},{id:`b`,text:`Nothing; pipeline admin covers all stages`,explain:`Pipeline access doesn’t grant permissions on workspace content.`},{id:`c`,text:`Viewer in the target workspace`,explain:`Viewer isn’t enough to deploy.`},{id:`d`,text:`Fabric administrator rights`,explain:`Tenant admin isn’t the documented requirement.`}],answer:`a`},{id:`CV-02`,machineId:v,bulletIds:[`M2.3`],format:`single`,difficulty:3,stem:`You deploy a Direct Lake semantic model from Development to Test. Test reports still show Development lakehouse data. What should you do?`,sources:[t.pipelinesProcess,t.pipelinesRules],options:[{id:`a`,text:`Refresh the model in Test`,explain:`Refresh reframes against the lakehouse it’s bound to, which is still Development.`},{id:`b`,text:`Redeploy the reports only`,explain:`Reports autobind to the Test model; the model is the problem.`},{id:`c`,text:`Add a datasource rule in Test, then redeploy`,explain:`Correct. Direct Lake models don’t autobind to the target stage’s items; use datasource rules.`},{id:`d`,text:`Switch the model to Import before deploying`,explain:`This changes the design instead of fixing the binding.`}],answer:`c`},{id:`CV-03`,machineId:v,bulletIds:[`M2.3`],format:`yesno`,difficulty:2,trapPairId:`pipelines-vs-git`,stem:`You are creating a deployment pipeline. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.pipelinesIntro,t.pipelinesProcess],statements:[{id:`s1`,text:`A pipeline can have between 2 and 10 stages.`,answer:!0,explain:`Yes. You set the number of stages when you create the pipeline.`},{id:`s2`,text:`Deploying copies the data in lakehouses and semantic models to the next stage.`,answer:!1,explain:`No. Deployment copies item definitions (metadata), not data.`},{id:`s3`,text:`A deployment pipeline requires the workspace to be connected to Git.`,answer:!1,explain:`No. Deployment pipelines and Git integration are independent.`}]},{id:`CV-04`,machineId:v,bulletIds:[`M2.3`],format:`single`,difficulty:2,stem:`A notebook in Development uses the Development lakehouse as its default lakehouse. After deployment to Production, it must use the Production lakehouse. What should you configure?`,sources:[t.pipelinesRules],options:[{id:`a`,text:`A parameter rule on the semantic model`,explain:`Parameter rules change model or dataflow parameters, not a notebook’s lakehouse.`},{id:`b`,text:`A default lakehouse rule for the notebook in the Production stage`,explain:`Correct. Default lakehouse rules change the notebook’s lakehouse per stage.`},{id:`c`,text:`A OneLake shortcut in Production to the Development lakehouse`,explain:`This keeps Production reading Development data.`},{id:`d`,text:`Git integration on the Production workspace`,explain:`Git doesn’t change per-stage settings.`}],answer:`b`},{id:`CV-05`,machineId:v,bulletIds:[`M2.3`],format:`single`,difficulty:2,stem:`You try to deploy only a report from Test to Production. The deployment fails. The report’s semantic model isn’t in Production yet. Why?`,sources:[t.pipelinesProcess],options:[{id:`a`,text:`Reports can only be deployed with a deployment plan`,explain:`Deployment plans are optional.`},{id:`b`,text:`Production stages can’t receive reports`,explain:`Any supported item can be deployed.`},{id:`c`,text:`The report must be certified first`,explain:`Endorsement isn’t a deployment requirement.`},{id:`d`,text:`Its semantic model must be deployed too`,explain:`Correct. Deploy the semantic model too, or first.`}],answer:`d`},{id:`CV-06`,machineId:v,bulletIds:[`M2.3`],format:`match`,difficulty:3,stem:`Match each deployment pipeline action to the permissions it needs.`,sources:[t.pipelinesProcess],prompts:[{id:`p1`,text:`Deploy a notebook from Development to an existing Test workspace`},{id:`p2`,text:`Deploy to an empty stage`},{id:`p3`,text:`Assign a workspace to a stage`}],choices:[{id:`c1`,text:`Pipeline admin + at least Contributor on source and target workspaces`},{id:`c2`,text:`Pipeline admin + at least Contributor on the source workspace`},{id:`c3`,text:`Pipeline admin + Admin of the workspace being assigned`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Deploying between stages needs a role on both workspaces.`},{promptId:`p2`,choiceId:`c2`,explain:`Only the source workspace matters when the target is empty.`},{promptId:`p3`,choiceId:`c3`,explain:`Assigning needs Admin of that workspace.`}]},{id:`CV-07`,machineId:v,bulletIds:[`M2.3`],format:`single`,difficulty:1,trapPairId:`pipelines-vs-git`,stem:`A team needs to promote tested content from a Development workspace to Test and then to Production inside Fabric, changing data sources per stage. Which feature should they use?`,sources:[t.pipelinesIntro],options:[{id:`a`,text:`Deployment pipelines`,explain:`Correct. Pipelines promote content through stages and apply rules per stage.`},{id:`b`,text:`Data pipelines in Data Factory`,explain:`Data pipelines orchestrate data movement, not content release.`},{id:`c`,text:`Git integration only`,explain:`Git versions content but doesn’t promote it between stage workspaces with rules.`},{id:`d`,text:`Impact analysis`,explain:`Impact analysis lists dependents; it doesn’t deploy.`}],answer:`a`},{id:`CV-08`,machineId:v,bulletIds:[`M2.3`],format:`single`,difficulty:2,stem:`A data source rule should switch a semantic model from an Azure SQL database in Test to a Snowflake database in Production. The rule can’t be applied. Why?`,sources:[t.pipelinesRules],options:[{id:`a`,text:`Rules can only be set on the Development stage`,explain:`Rules are set on target stages such as Production.`},{id:`b`,text:`Rules only switch between same-type sources`,explain:`Correct. Learn: data source rules work only when switching between data sources of the same type.`},{id:`c`,text:`Snowflake isn’t supported in semantic models`,explain:`The limitation is about switching source types in a rule.`},{id:`d`,text:`Rules take effect only after Git commits`,explain:`Rules take effect on the next deployment.`}],answer:`b`},{id:`CV-09`,machineId:v,bulletIds:[`M2.3`],format:`order`,difficulty:2,stem:`You are setting up a new deployment pipeline. A semantic model must use the production database in the Production stage. Put the steps in order.`,sources:[t.pipelinesStart,t.pipelinesRules],items:[{id:`i4`,text:`Define a data source rule for the semantic model in the Production stage`,explain:`Fourth. Rules are created under an item in the stage where they apply.`},{id:`i1`,text:`Create the pipeline and name its stages`,explain:`First. The number of stages is fixed at creation.`},{id:`i5`,text:`Deploy from Test to Production again`,explain:`Last. Learn: rules don’t apply until you deploy to the stage where they were created.`},{id:`i2`,text:`Assign a workspace to each stage`,explain:`Second. Each stage is backed by one workspace.`},{id:`i3`,text:`Deploy the content through to the Production stage`,explain:`Third. The semantic model must exist in Production before a rule can be set on it.`}],answerOrder:[`i1`,`i2`,`i3`,`i4`,`i5`]},{id:`RM-01`,machineId:y,bulletIds:[`M2.4`],format:`single`,difficulty:1,trapPairId:`lineage-vs-impact`,stem:`Before you drop a column from a lakehouse table, you need to list every downstream item that depends on the lakehouse, including items in other workspaces. What should you use?`,sources:[t.impact,t.lineage],options:[{id:`a`,text:`Lineage view of the workspace`,explain:`Lineage view doesn’t show downstream items in other workspaces.`},{id:`b`,text:`Impact analysis on the lakehouse`,explain:`Correct. Impact analysis lists downstream items across workspaces.`},{id:`c`,text:`The deployment pipeline compare view`,explain:`Compare shows differences between stages, not dependents.`},{id:`d`,text:`The Git Source control pane`,explain:`Git status shows changes, not dependents.`}],answer:`b`},{id:`RM-02`,machineId:y,bulletIds:[`M2.4`],format:`single`,difficulty:2,stem:`Impact analysis on a warehouse shows downstream reports in workspaces you can’t access. You need to warn their owners about a schema change. What should you do?`,sources:[t.impact],options:[{id:`a`,text:`Ask a Fabric admin to grant you access to each workspace`,explain:`Not needed: notifications reach workspaces you can’t access.`},{id:`b`,text:`Endorse the warehouse as Certified`,explain:`Endorsement doesn’t notify anyone.`},{id:`c`,text:`Select Notify contacts and describe the change`,explain:`Correct. It emails the contact lists of all affected workspaces, even ones you can’t access.`},{id:`d`,text:`Add a sensitivity label so it propagates downstream`,explain:`Labels don’t send change notices.`}],answer:`c`},{id:`RM-03`,machineId:y,bulletIds:[`M2.4`],format:`yesno`,difficulty:2,trapPairId:`lineage-vs-impact`,stem:`You are planning a change to a semantic model. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.impact,t.lineage],statements:[{id:`s1`,text:`You need write permission on the semantic model to run impact analysis on it.`,answer:!0,explain:`Yes. Impact analysis requires write permission on the item.`},{id:`s2`,text:`Impact analysis can show either direct children or all downstream items.`,answer:!0,explain:`Yes. You switch between Child items and All downstream items.`},{id:`s3`,text:`Workspace Viewers can see data sources in lineage view.`,answer:!1,explain:`No. Viewers can open lineage view but don’t see data sources.`}]},{id:`RM-04`,machineId:y,bulletIds:[`M2.4`],format:`single`,difficulty:2,trapPairId:`lineage-vs-impact`,stem:`You want one diagram of every item in a workspace and how data flows between them, including upstream sources one level outside the workspace. What should you open?`,sources:[t.lineage],options:[{id:`a`,text:`Lineage view`,explain:`Correct. Lineage view shows the workspace’s items, their connections, and upstream sources one level out.`},{id:`b`,text:`Impact analysis on each item`,explain:`Impact analysis starts from one item and lists downstream dependents.`},{id:`c`,text:`The OneLake catalog Govern tab`,explain:`The diagram of items and their connections is lineage view.`},{id:`d`,text:`The Monitor hub`,explain:`Lineage view, not a monitoring page, shows how data flows between items.`}],answer:`a`},{id:`RM-05`,machineId:y,bulletIds:[`M2.4`],format:`single`,difficulty:3,stem:`You run impact analysis on a data source (a SQL Server database) rather than on a Fabric item. What does it show?`,sources:[t.impact],options:[{id:`a`,text:`All downstream items in every workspace, grouped by type and by workspace`,explain:`For data sources, only direct children are shown.`},{id:`b`,text:`Nothing; impact analysis doesn’t support data sources`,explain:`Impact analysis does support data sources, with limits.`},{id:`c`,text:`The tables and columns used by each report`,explain:`Impact analysis lists items, not column usage.`},{id:`d`,text:`Only its direct children, along with the connection string`,explain:`Correct. For data sources it shows direct children and the connection string.`}],answer:`d`},{id:`RM-06`,machineId:y,bulletIds:[`M2.4`],format:`single`,difficulty:2,stem:`In an impact analysis, some downstream items appear as “Limited access”. What does this mean?`,sources:[t.impact],options:[{id:`a`,text:`The items are in a workspace on a paused capacity`,explain:`Capacity state isn’t what the label means.`},{id:`b`,text:`You don’t have access to those items`,explain:`Correct. Items you can’t access appear as Limited access.`},{id:`c`,text:`The items are protected by RLS`,explain:`RLS is unrelated to impact analysis labels.`},{id:`d`,text:`The items aren’t endorsed`,explain:`Endorsement isn’t shown this way.`}],answer:`b`},{id:`RM-07`,machineId:y,bulletIds:[`M2.4`],format:`multi`,difficulty:2,stem:`You plan to rename a column in a Dataflow Gen2 output. Which two ways can you open impact analysis for the dataflow? Choose two.`,sources:[t.impact],options:[{id:`a`,text:`From the dataflow’s card in lineage view`,explain:`Correct. Impact analysis opens from the item card in lineage view.`},{id:`b`,text:`From Lineage on the dataflow’s details page`,explain:`Correct. It also opens from the item’s details page.`},{id:`c`,text:`From the dataflow’s refresh history`,explain:`Impact analysis opens from lineage view or the item’s details page.`},{id:`d`,text:`From the workspace’s Manage access pane`,explain:`Impact analysis opens from lineage view or the item’s details page.`}],answers:[`a`,`b`]},{id:`RL-01`,machineId:b,bulletIds:[`M2.5`],format:`single`,difficulty:2,trapPairId:`xmla-read-vs-readwrite`,stem:`Deploying a semantic model from Tabular Editor to a Fabric capacity workspace fails, while DAX queries from DAX Studio work. What should a capacity admin check?`,sources:[t.xmla],options:[{id:`a`,text:`That the XMLA Endpoint setting is Read Write for the capacity`,explain:`Correct. Read-only is the default; writes need Read Write.`},{id:`b`,text:`That the model has Large storage format turned off`,explain:`Learn recommends large format on for XMLA writes.`},{id:`c`,text:`That the workspace is connected to Git`,explain:`Git isn’t required for XMLA.`},{id:`d`,text:`That DAX Studio is closed`,explain:`Other connections don’t block deployment.`}],answer:`a`},{id:`RL-02`,machineId:b,bulletIds:[`M2.5`],format:`single`,difficulty:1,stem:`You need the server address to connect SSMS to a workspace’s semantic models over XMLA. Where do you find it?`,sources:[t.xmla],options:[{id:`a`,text:`In the semantic model’s refresh history`,explain:`Refresh history doesn’t contain the connection URL.`},{id:`b`,text:`In the lakehouse’s SQL analytics endpoint settings`,explain:`That’s a T-SQL connection string, not XMLA.`},{id:`c`,text:`In Workspace settings, as the workspace connection URL`,explain:`Correct. The powerbi:// URL is under the workspace’s connection settings.`},{id:`d`,text:`In the tenant admin portal’s audit logs`,explain:`Audit logs don’t provide connection URLs.`}],answer:`c`},{id:`RL-03`,machineId:b,bulletIds:[`M2.5`],format:`single`,difficulty:2,stem:`In SSMS connected to a workspace’s XMLA endpoint, you send a TMSL refresh command for the FactSales table. You need to reload its data and recalculate all dependents. Which refresh type should the command use?`,sources:[t.tmslRefresh,t.xmla],options:[{id:`a`,text:`calculate`,explain:`calculate recalculates without reloading data.`},{id:`b`,text:`full`,explain:`Correct. full refreshes data and recalculates all dependents.`},{id:`c`,text:`clearValues`,explain:`clearValues empties the object’s values instead of reloading them.`},{id:`d`,text:`defragment`,explain:`defragment cleans unused dictionary values; it doesn’t reload data.`}],answer:`b`},{id:`RL-04`,machineId:b,bulletIds:[`M2.5`],format:`yesno`,difficulty:2,trapPairId:`xmla-read-vs-readwrite`,stem:`You are planning XMLA-based management of semantic models. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.xmla,t.largeModels],statements:[{id:`s1`,text:`Semantic models in Pro workspaces support XMLA write operations.`,answer:!1,explain:`No. Pro workspaces don’t support XMLA writes; you need a capacity or PPU.`},{id:`s2`,text:`The XMLA Endpoint setting applies to all workspaces on the capacity.`,answer:!0,explain:`Yes. It’s a capacity-level setting.`},{id:`s3`,text:`Workspace Contributors have Write permission on semantic models over XMLA.`,answer:!0,explain:`Yes. Contributor and above have Write, effectively Analysis Services database admin.`}]},{id:`RL-05`,machineId:b,bulletIds:[`M2.5`],format:`single`,difficulty:3,stem:`A model has an incremental refresh policy. An administrator must reload one specific historical partition outside the policy’s refresh window. What can they use?`,sources:[t.tmslRefresh,t.xmla],options:[{id:`a`,text:`A scheduled refresh in the service`,explain:`Learn names TMSL over XMLA as the way to refresh specific partitions and override the policy.`},{id:`b`,text:`A TMSL refresh command over the XMLA endpoint`,explain:`Correct. TMSL refresh over XMLA can target objects and override the incremental refresh policy.`},{id:`c`,text:`Publishing the .pbix again`,explain:`Republishing isn’t a partition refresh.`},{id:`d`,text:`Changing the archive period temporarily`,explain:`Learn’s way to target partitions is a TMSL refresh over XMLA, not editing the policy.`}],answer:`b`},{id:`RL-06`,machineId:b,bulletIds:[`M2.5`],format:`match`,difficulty:2,trapPairId:`xmla-read-vs-readwrite`,stem:`Match each task to the XMLA endpoint setting it needs. A choice may be used more than once or not at all.`,sources:[t.xmla],prompts:[{id:`p1`,text:`Run DAX queries from DAX Studio`},{id:`p2`,text:`Deploy a tabular project from Visual Studio`},{id:`p3`,text:`Save metadata changes from Tabular Editor`}],choices:[{id:`c1`,text:`Read-only is enough`},{id:`c2`,text:`Read Write is required`},{id:`c3`,text:`XMLA isn’t used`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Queries only need read access.`},{promptId:`p2`,choiceId:`c2`,explain:`Deployment writes metadata.`},{promptId:`p3`,choiceId:`c2`,explain:`Saving changes is a write operation.`}]},{id:`RL-07`,machineId:b,bulletIds:[`M2.5`],format:`single`,difficulty:1,stem:`Which tool can query and manage a semantic model through the XMLA endpoint, outside Power BI Desktop?`,sources:[t.xmla],options:[{id:`a`,text:`A KQL queryset`,explain:`SSMS is the XMLA client here; a KQL queryset isn’t.`},{id:`b`,text:`The visual query editor`,explain:`SSMS is the XMLA client here; the visual query editor isn’t.`},{id:`c`,text:`Data Wrangler`,explain:`SSMS is the XMLA client here; Data Wrangler isn’t.`},{id:`d`,text:`SQL Server Management Studio (SSMS)`,explain:`Correct. SSMS connects to the workspace XMLA URL like an Analysis Services server.`}],answer:`d`},{id:`PB-01`,machineId:x,bulletIds:[`M2.6`],format:`single`,difficulty:1,placement:!0,trapPairId:`pbi-files`,stem:`Report authors should start every new report from a standard layout, model, and set of queries, but without anyone else’s data. What should you distribute?`,sources:[t.templates],options:[{id:`a`,text:`A .pbix file`,explain:`A .pbix includes the imported data.`},{id:`b`,text:`A Power BI template (.pbit)`,explain:`Correct. A template has report pages, the model definition, and queries but no data.`},{id:`c`,text:`A .pbids file`,explain:`A .pbids holds only a connection.`},{id:`d`,text:`A Power BI project (.pbip)`,explain:`A project is a source-control format, and its data cache is excluded only from Git.`}],answer:`b`},{id:`PB-02`,machineId:x,bulletIds:[`M2.6`],format:`single`,difficulty:2,placement:!0,trapPairId:`pbi-files`,stem:`New analysts struggle to find the right server and database. You want a file they double-click to open Power BI Desktop’s Get data for that source, with no credentials stored. What should you create?`,sources:[t.pbids],options:[{id:`a`,text:`A .pbids data source file`,explain:`Correct. It describes one connection and prompts for credentials when opened.`},{id:`b`,text:`A .pbit template`,explain:`A template includes a whole report and model.`},{id:`c`,text:`A shortcut in a lakehouse`,explain:`Shortcuts don’t open Power BI Desktop.`},{id:`d`,text:`A deployment pipeline rule`,explain:`Rules change sources between stages.`}],answer:`a`},{id:`PB-03`,machineId:x,bulletIds:[`M2.6`],format:`yesno`,difficulty:2,placement:!0,trapPairId:`pbi-files`,stem:`You are creating reusable files for report authors. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.templates,t.pbids],statements:[{id:`s1`,text:`A single .pbids file can describe connections to three different data sources.`,answer:!1,explain:`No. A .pbids supports one data source; more causes an error.`},{id:`s2`,text:`Filter values saved in report metadata remain in a .pbit file even though it has no data.`,answer:!0,explain:`Yes. Learn warns that such values stay in the template.`},{id:`s3`,text:`Opening a .pbit prompts for parameter values and data source credentials.`,answer:!0,explain:`Yes. The template loads data after you supply them.`}]},{id:`PB-04`,machineId:x,bulletIds:[`M2.6`],format:`single`,difficulty:2,placement:!0,stem:`Report authors in five workspaces should reuse one certified Sales semantic model instead of building their own. What must each author have on the model?`,sources:[t.sharedModels],options:[{id:`a`,text:`Workspace Admin on the model’s workspace`,explain:`More than needed; Build is enough to create content.`},{id:`b`,text:`Build permission`,explain:`Correct. Build controls who can create content on a shared model.`},{id:`c`,text:`A copy of the model in their workspace`,explain:`Copies defeat the purpose of a shared model.`},{id:`d`,text:`A sensitivity label on the model`,explain:`Labels don’t grant permissions.`}],answer:`b`},{id:`PB-05`,machineId:x,bulletIds:[`M2.6`],format:`single`,difficulty:3,placement:!0,stem:`A user with only a free license has Build permission on a shared semantic model, but can’t create a report from it. According to Learn, when can free users build reports from shared models?`,sources:[t.sharedModels],options:[{id:`a`,text:`Never; free users can only view`,explain:`Learn describes a case where free users can build reports.`},{id:`b`,text:`When the model is certified`,explain:`Endorsement doesn’t change licensing.`},{id:`c`,text:`When the model is on Premium or an F64-or-larger capacity`,explain:`Correct. Free users can build from shared models with Build permission on those capacities.`},{id:`d`,text:`When the model is shared through a .pbids file`,explain:`A .pbids only describes a connection.`}],answer:`c`},{id:`PB-06`,machineId:x,bulletIds:[`M2.6`],format:`order`,difficulty:1,placement:!0,stem:`You need to create a Power BI template from an existing report and use it to start a new report. Put the steps in order.`,sources:[t.templates],items:[{id:`i2`,text:`Add a description for the template`,explain:`Second. Describe the template for authors.`},{id:`i4`,text:`Enter parameter values and credentials to load data`,explain:`Last. The template has no data until loaded.`},{id:`i1`,text:`Select File > Export > Power BI template`,explain:`First. Export the report as a .pbit.`},{id:`i3`,text:`Open the .pbit with File > Import > Power BI template`,explain:`Third. Importing starts a new report from it.`}],answerOrder:[`i1`,`i2`,`i3`,`i4`]},{id:`PB-07`,machineId:x,bulletIds:[`M2.6`],format:`single`,difficulty:2,placement:!0,stem:`You want to export a .pbids file for a SQL Server source that you already use in Power BI Desktop. Where do you do this?`,sources:[t.pbids],options:[{id:`a`,text:`File > Export > Power BI template`,explain:`That exports a .pbit, not a .pbids.`},{id:`b`,text:`The Publish dialog`,explain:`Publish sends a report to the service.`},{id:`c`,text:`Model view > Manage relationships`,explain:`Relationships aren’t data sources.`},{id:`d`,text:`Data source settings > Export PBIDS`,explain:`Correct. Export PBIDS is in Data source settings.`}],answer:`d`},{id:`PB-08`,machineId:x,bulletIds:[`M2.6`],format:`match`,difficulty:2,placement:!0,trapPairId:`pbi-files`,stem:`Match each Power BI file type to what it contains.`,sources:[t.templates,t.pbids,t.pbip],prompts:[{id:`p1`,text:`.pbix`},{id:`p2`,text:`.pbit`},{id:`p3`,text:`.pbids`},{id:`p4`,text:`.pbip`}],choices:[{id:`c1`,text:`Report, model, and imported data in one file`},{id:`c2`,text:`Report, model, and queries, but no data`},{id:`c3`,text:`One data source connection, as JSON`},{id:`c4`,text:`A pointer to a folder of plain-text report and model definitions`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`The standard single-file report.`},{promptId:`p2`,choiceId:`c2`,explain:`A template for new reports.`},{promptId:`p3`,choiceId:`c3`,explain:`Opens Get data for that source.`},{promptId:`p4`,choiceId:`c4`,explain:`The project file points to the report folder.`}]},{id:`PB-09`,machineId:x,bulletIds:[`M2.6`],format:`multi`,difficulty:2,placement:!0,stem:`You want report authors across the organization to find and reuse your shared semantic model. Which two actions help? Choose two.`,sources:[t.sharedModels,t.endorsement],options:[{id:`a`,text:`Export the model as a .pbids file`,explain:`A .pbids describes a data source connection, not a shared model.`},{id:`b`,text:`Turn off the XMLA endpoint`,explain:`This doesn’t help reuse.`},{id:`c`,text:`Endorse the model as Promoted or Certified`,explain:`Correct. Endorsement helps people find trustworthy content.`},{id:`d`,text:`Grant Build permission to the authors`,explain:`Correct. Build lets them create content on the model.`}],answers:[`c`,`d`]}],ce=[...ie,...se,...oe],S=`https://learn.microsoft.com/en-us/`,C=`${S}fabric/fundamentals/microsoft-fabric-overview`,w=`${S}fabric/fundamentals/fabric-terminology`,T=`${S}fabric/onelake/onelake-overview`,E=`${S}fabric/enterprise/licenses`,D=`${S}fabric/enterprise/throttling`,O=`${S}fabric/fundamentals/fabric-trial`,k=`${S}fabric/fundamentals/decision-guide-data-store`,A=`${S}fabric/data-engineering/lakehouse-overview`,j=`${S}fabric/data-warehouse/data-warehousing`,M=`${S}fabric/real-time-intelligence/eventhouse`,N=`${S}fabric/fundamentals/decision-guide-lakehouse-warehouse`,le=`${S}fabric/fundamentals/workspaces`,P=`${S}fabric/data-factory/data-factory-overview`,F=`${S}fabric/onelake/onelake-medallion-lakehouse-architecture`,ue=`${S}fabric/cicd/deployment-pipelines/intro-to-deployment-pipelines`,de=`${S}power-bi/transform-model/dax-query-view`,fe=[{id:`FO-01`,machineId:`founding-charter`,bulletIds:[],format:`single`,difficulty:1,stem:`Your company is adopting Microsoft Fabric. Data engineers will use Spark, analysts will use T-SQL, and report authors will use Power BI. You need all three groups to work on the same copy of the data. Which Fabric component provides the shared storage?`,sources:[C,T],options:[{id:`a`,text:`OneLake`,explain:`Correct. Every Fabric workload stores and reads data in OneLake, so one copy serves Spark, T-SQL, and Power BI without duplication.`},{id:`b`,text:`The Real-Time hub`,explain:`The Real-Time hub is the tenant-wide place to discover and ingest streaming data and events, not the storage layer for all workloads.`},{id:`c`,text:`A Fabric capacity`,explain:`A capacity provides compute (capacity units), not storage. Workspaces run on capacities, but data lives in OneLake.`},{id:`d`,text:`The OneLake catalog`,explain:`The OneLake catalog is for discovering and governing items. It doesn’t store the data itself.`}],answer:`a`},{id:`FO-02`,machineId:`founding-charter`,bulletIds:[],format:`match`,difficulty:1,stem:`You are explaining Fabric workloads to a new team. Match each task to the workload that provides it.`,sources:[C,w,P],prompts:[{id:`p1`,text:`Connect to many data sources with built-in connectors and orchestrate data movement with pipelines`},{id:`p2`,text:`Process large datasets with Apache Spark notebooks`},{id:`p3`,text:`Analyze streaming IoT and log data as it arrives`},{id:`p4`,text:`Build an enterprise warehouse developed with T-SQL`}],choices:[{id:`c1`,text:`Data Factory`},{id:`c2`,text:`Data Engineering`},{id:`c3`,text:`Real-Time Intelligence`},{id:`c4`,text:`Data Warehouse`},{id:`c5`,text:`Data Science`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Data Factory provides the connectors, pipelines, and Dataflow Gen2 used for data integration.`},{promptId:`p2`,choiceId:`c2`,explain:`Data Engineering provides Apache Spark with notebooks for large-scale processing.`},{promptId:`p3`,choiceId:`c3`,explain:`Real-Time Intelligence analyzes data in motion such as IoT readings, logs, and clickstreams.`},{promptId:`p4`,choiceId:`c4`,explain:`Fabric Data Warehouse is a T-SQL relational warehouse. Data Science (the unused choice) is for building ML models.`}]},{id:`FO-03`,machineId:`founding-charter`,bulletIds:[],format:`yesno`,difficulty:2,stem:`You are reviewing statements in a Fabric onboarding document. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[C,T,w,ue],statements:[{id:`s1`,text:`Each user needs their own Azure subscription before they can use Fabric.`,answer:!1,explain:`No. Fabric is SaaS and OneLake hides Azure details; Learn states you don’t need an Azure account to use Fabric.`},{id:`s2`,text:`A table created with T-SQL in a warehouse can be read by a Spark notebook without exporting or copying it.`,answer:!0,explain:`Yes. All engines store tables in OneLake in Delta format, so Spark reads the warehouse’s tables directly.`},{id:`s3`,text:`A Data Factory pipeline and a deployment pipeline are the same kind of item.`,answer:!1,explain:`No. Learn notes that data pipelines (orchestration) are different from deployment pipelines (lifecycle promotion between stages).`}]},{id:`FO-04`,machineId:`water-wheel`,bulletIds:[],format:`single`,difficulty:2,stem:`Your organization will publish Power BI reports to a Fabric workspace. Most report consumers have only a Microsoft Fabric free license and will be given the Viewer role. You need them to view the reports without buying more per-user licenses, at the lowest cost. What should you assign the workspace to?`,sources:[E],options:[{id:`a`,text:`F32`,explain:`On F SKUs smaller than F64, every viewer of Power BI content needs a Pro, PPU, or individual trial license.`},{id:`b`,text:`F64`,explain:`Correct. On F64 or larger, users with only a free license and the Viewer role can view Power BI content.`},{id:`c`,text:`F2`,explain:`F2 is the smallest F SKU. Free-license viewers still need Pro, PPU, or a trial license to view Power BI content there.`},{id:`d`,text:`A Premium Per User (PPU) workspace`,explain:`A PPU workspace requires each viewer to have a PPU license (or individual trial), and it isn’t a Fabric capacity.`}],answer:`b`},{id:`FO-05`,machineId:`water-wheel`,bulletIds:[],format:`yesno`,difficulty:2,stem:`A capacity administrator is investigating slow reports during a large overnight data load. For each statement about Fabric capacity behavior, select Yes if it is true. Otherwise, select No.`,sources:[D],statements:[{id:`s1`,text:`Background operations, such as scheduled refreshes, have their CU usage smoothed over 24 hours.`,answer:!0,explain:`Yes. Fabric smooths background operations over a 24-hour period.`},{id:`s2`,text:`As soon as utilization goes above 100%, Fabric rejects all new requests.`,answer:!1,explain:`No. Overage protection allows 10 minutes of future capacity first; throttling then escalates in stages (delays, then rejecting interactive, then rejecting all).`},{id:`s3`,text:`An overloaded capacity slows down workspaces that are assigned to other capacities in the same tenant.`,answer:!1,explain:`No. Throttling applies at the capacity level; other capacities can keep running normally.`}]},{id:`FO-06`,machineId:`water-wheel`,bulletIds:[],format:`single`,difficulty:1,stem:`Your Fabric tenant has dozens of workspaces owned by Finance, Marketing, and Operations. You need to group the workspaces by business area so that Fabric administrators can delegate management and apply governance above the workspace level. What should you use?`,sources:[w,T,le],options:[{id:`a`,text:`A separate capacity for each business area`,explain:`Capacities control compute and billing. They don’t provide a governance grouping for delegating management.`},{id:`b`,text:`Workspace folders`,explain:`Folders organize items inside a single workspace, not workspaces across the tenant.`},{id:`c`,text:`Domains`,explain:`Correct. Domains group workspaces into business areas so admins can delegate management and apply governance policies above the workspace level.`},{id:`d`,text:`OneLake shortcuts`,explain:`Shortcuts reference data in other locations. They don’t organize workspaces or delegate administration.`}],answer:`c`},{id:`FO-07`,machineId:`three-vats`,bulletIds:[],format:`single`,difficulty:2,stem:`A team of SQL developers needs a Fabric data store for curated sales data. Their load procedures update several tables and must commit or roll back all the changes together. Which data store should they use?`,sources:[N,j,M],trapPairId:`stores`,options:[{id:`a`,text:`A lakehouse`,explain:`A lakehouse doesn’t support multi-table transactions, and it is developed mainly with Spark.`},{id:`b`,text:`The SQL analytics endpoint of a lakehouse`,explain:`The SQL analytics endpoint is read-only for data, so T-SQL there can’t insert, update, or delete rows.`},{id:`c`,text:`An eventhouse`,explain:`An eventhouse targets streaming, time-based event data queried with KQL, not transactional T-SQL loads.`},{id:`d`,text:`A warehouse`,explain:`Correct. A warehouse is developed with T-SQL and supports full multi-table ACID transactions.`}],answer:`d`},{id:`FO-08`,machineId:`three-vats`,bulletIds:[],format:`single`,difficulty:2,stem:`You uploaded several CSV files to the Files area of a lakehouse. Analysts report that the data doesn’t appear when they connect to the lakehouse’s SQL analytics endpoint. You need the data to be queryable from the endpoint. What should you do?`,sources:[A],trapPairId:`stores`,options:[{id:`a`,text:`Load the CSV data into a Delta table in the Tables area`,explain:`Correct. Only Delta tables appear in the SQL analytics endpoint; CSV and Parquet files in Files can’t be queried there until converted.`},{id:`b`,text:`Give the analysts the Contributor workspace role`,explain:`This is about format and location, not permissions. Even workspace admins can’t query CSV files through the endpoint.`},{id:`c`,text:`Turn on OneLake availability for the lakehouse`,explain:`OneLake availability is an eventhouse (KQL database) setting, not a lakehouse one. The SQL analytics endpoint shows only Delta tables, so the CSV files must be loaded into a Delta table.`},{id:`d`,text:`Create a shortcut to the CSV folder in the Files area`,explain:`Files-area shortcuts aren’t discovered as tables, and the data still isn’t in Delta format.`}],answer:`a`},{id:`FO-09`,machineId:`three-vats`,bulletIds:[],format:`match`,difficulty:2,stem:`You are designing a Fabric solution with three workloads. Match each workload to the data store you should use.`,sources:[k,N,M],trapPairId:`stores`,prompts:[{id:`p1`,text:`High-volume telemetry events analyzed interactively with KQL within seconds of arrival`},{id:`p2`,text:`Raw JSON, images, and Parquet files processed by data engineers in PySpark notebooks`},{id:`p3`,text:`A star schema for BI built and loaded by SQL developers with T-SQL stored procedures`}],choices:[{id:`c1`,text:`Eventhouse`},{id:`c2`,text:`Lakehouse`},{id:`c3`,text:`Warehouse`},{id:`c4`,text:`SQL database in Fabric`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Eventhouses are built for streaming, time-based event data queried with KQL.`},{promptId:`p2`,choiceId:`c2`,explain:`Lakehouses hold structured and unstructured data and are developed mainly with Spark.`},{promptId:`p3`,choiceId:`c3`,explain:`Warehouses are T-SQL-first and suit dimensional models for BI. SQL database in Fabric (unused) also runs T-SQL, but Learn positions it for operational OLTP workloads, not enterprise warehousing and SQL-based BI.`}]},{id:`FO-10`,machineId:`mill-lease`,bulletIds:[],format:`single`,difficulty:2,stem:`Your 60-day Fabric trial capacity expired yesterday. The workspace contains a lakehouse and notebooks you want to keep using. What should you do?`,sources:[O],options:[{id:`a`,text:`Export each item to a .pbix file before the content is deleted`,explain:`Learn’s way to keep trial content is to reassign the workspace to a paid capacity within 7 days; exporting items isn’t part of that guidance.`},{id:`b`,text:`Assign the workspace to a paid F or P capacity within 7 days`,explain:`Correct. Content stays in OneLake for 7 days after the trial ends and is reactivated when the workspace is assigned to a paid F or P capacity.`},{id:`c`,text:`Start a new Power BI individual trial`,explain:`A Power BI individual trial is a per-user license. It doesn’t give the workspace the capacity that non-Power BI items need.`},{id:`d`,text:`Change the workspace type to Pro`,explain:`The workspace is already reverted to Pro when the trial ends, and Pro can’t run non-Power BI Fabric items.`}],answer:`b`},{id:`FO-11`,machineId:`mill-lease`,bulletIds:[],format:`yesno`,difficulty:1,stem:`You are planning hands-on labs on a Fabric trial capacity. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[O],statements:[{id:`s1`,text:`When the trial ends, workspaces assigned to the trial capacity are reassigned to Pro.`,answer:!0,explain:`Yes. Learn: workspaces assigned to the trial capacity are reassigned to Pro, and non-Power BI items become inaccessible until the workspace gets a paid F or P capacity.`},{id:`s2`,text:`You can use Copilot in Fabric on the trial capacity.`,answer:!1,explain:`No. Copilot isn’t supported on trial capacities.`},{id:`s3`,text:`You can store up to 1 TB of data in OneLake during the trial.`,answer:!0,explain:`Yes. The trial allows up to 1 TB of OneLake storage.`}]},{id:`FO-12`,machineId:`mill-lease`,bulletIds:[],format:`order`,difficulty:1,stem:`You need to start a Fabric trial from the Account manager and begin building items in it. Put the steps in order.`,sources:[O],items:[{id:`i1`,text:`Create a workspace and set its workspace type to Trial`,explain:`Last: workspaces must use the Trial type so their items run on the trial capacity.`},{id:`i2`,text:`Select Start trial in the Account manager`,explain:`Second: Start trial is in the Account manager.`},{id:`i3`,text:`Open the Account manager from your profile picture`,explain:`First: the Account manager opens from the photo in the upper-right corner.`},{id:`i4`,text:`Choose the trial capacity region and select Activate`,explain:`Third: you choose the trial capacity region (the default is your home region, which you can keep or change) and select Activate.`}],answerOrder:[`i3`,`i2`,`i4`,`i1`]},{id:`FO-13`,machineId:`founding-charter`,bulletIds:[],format:`single`,difficulty:1,stem:`A manager asks how Microsoft Fabric is delivered. You need to describe its service model in one phrase. What should you say?`,sources:[C],options:[{id:`a`,text:`Infrastructure as a service that you patch yourself`,explain:`Fabric needs no infrastructure management; it isn’t IaaS.`},{id:`b`,text:`Software as a service (SaaS)`,explain:`Correct. Learn: Fabric is delivered as a software-as-a-service (SaaS) platform.`},{id:`c`,text:`An on-premises server product`,explain:`Fabric runs in the cloud as a SaaS platform.`},{id:`d`,text:`A set of separate Azure services you integrate`,explain:`Learn says Fabric removes the need to manually integrate separate services.`}],answer:`b`},{id:`FO-14`,machineId:`founding-charter`,bulletIds:[],format:`single`,difficulty:2,stem:`Data scientists want to build, deploy, and track machine learning models, with experiment tracking and a model registry, inside Fabric. Which workload should they use?`,sources:[C],options:[{id:`a`,text:`Real-Time Intelligence`,explain:`Real-Time Intelligence analyzes data in motion, such as IoT readings and logs.`},{id:`b`,text:`Data Factory`,explain:`Data Factory ingests, prepares, and transforms data.`},{id:`c`,text:`Fabric Data Science`,explain:`Correct. It builds, deploys, and operationalizes ML models, with built-in experiment tracking and model registry.`},{id:`d`,text:`Fabric Data Warehouse`,explain:`The warehouse provides SQL storage and querying, not ML model management.`}],answer:`c`},{id:`FO-15`,machineId:`founding-charter`,bulletIds:[],format:`multi`,difficulty:2,stem:`You are describing the shared platform layer that sits beneath all Fabric workloads. Which two of the following does Learn place in that layer? Choose two.`,sources:[C],options:[{id:`a`,text:`Power BI Report Server`,explain:`Report Server isn’t listed in the Fabric platform layer; Learn lists OneLake, Copilot, and governance.`},{id:`b`,text:`OneLake`,explain:`Correct. OneLake is the centralized, logical data lake used by all workloads.`},{id:`c`,text:`Copilot`,explain:`Correct. Copilot is AI assistance embedded across Fabric workloads.`},{id:`d`,text:`Azure Virtual Machines`,explain:`Fabric is SaaS; you don’t manage virtual machines.`}],answers:[`b`,`c`]},{id:`FO-16`,machineId:`founding-charter`,bulletIds:[],format:`yesno`,difficulty:2,stem:`You are checking a slide about Fabric workloads. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[C,P],statements:[{id:`s1`,text:`Fabric Data Engineering provides Apache Spark with notebooks for processing large datasets.`,answer:!0,explain:`Yes. Learn describes Data Engineering as providing Apache Spark with notebooks and job tools.`},{id:`s2`,text:`Data Factory provides connectors for on-premises and cloud data sources.`,answer:!0,explain:`Yes. Learn describes Data Factory connecting to a wide range of on-premises and cloud data sources through its connectors.`},{id:`s3`,text:`Fabric Data Warehouse stores its data in a proprietary format that only T-SQL can read.`,answer:!1,explain:`No. It natively stores data in the open Delta Lake format.`}]},{id:`FO-17`,machineId:`founding-charter`,bulletIds:[],format:`single`,difficulty:1,stem:`Your team will analyze IoT sensor readings and website clickstreams as they arrive, and act on them in near real time. Which Fabric workload is built for this?`,sources:[C],options:[{id:`a`,text:`Real-Time Intelligence`,explain:`Correct. It analyzes data as it arrives, such as IoT readings, logs, and clickstreams.`},{id:`b`,text:`Fabric Data Science`,explain:`Data Science builds and deploys ML models.`},{id:`c`,text:`Databases`,explain:`Databases provide operational transactional databases such as SQL database in Fabric.`},{id:`d`,text:`Industry Solutions`,explain:`Industry Solutions address industry-specific needs, not streaming analytics in general.`}],answer:`a`},{id:`FO-18`,machineId:`water-wheel`,bulletIds:[],format:`single`,difficulty:1,stem:`An architect proposes creating a second OneLake for the Finance department to keep its data separate. What should you tell them?`,sources:[T],options:[{id:`a`,text:`Create it from the admin portal under OneLake settings`,explain:`There’s no option to create another OneLake.`},{id:`b`,text:`Create it by buying a second capacity`,explain:`Capacities add compute; they don’t add OneLake instances.`},{id:`c`,text:`Each tenant has exactly one OneLake; separate Finance with workspaces and domains instead`,explain:`Correct. Learn: every tenant has a single OneLake that you can’t delete or duplicate; organize it with domains and workspaces.`},{id:`d`,text:`Each workspace already has its own OneLake`,explain:`Workspaces are containers within the tenant’s single OneLake.`}],answer:`c`},{id:`FO-19`,machineId:`water-wheel`,bulletIds:[],format:`order`,difficulty:1,stem:`Put the levels of the Fabric data hierarchy in order, from the broadest to the most specific.`,sources:[T],items:[{id:`i2`,text:`Workspace`,explain:`Second. Workspaces organize data within the tenant and are each part of a capacity.`},{id:`i3`,text:`Data item, such as a lakehouse or warehouse`,explain:`Last. Workspaces contain data items.`},{id:`i1`,text:`Tenant`,explain:`First. Tenant-level policies protect all data that lands in OneLake.`}],answerOrder:[`i1`,`i2`,`i3`]},{id:`FO-20`,machineId:`water-wheel`,bulletIds:[],format:`single`,difficulty:2,stem:`A capacity is overloaded during a busy afternoon. Interactive report queries are now being rejected, but scheduled background jobs can still start. Which throttling stage is the capacity in?`,sources:[D],options:[{id:`a`,text:`Overage protection with no throttling`,explain:`Overage protection lets you use up to 10 minutes of future capacity without any throttling.`},{id:`b`,text:`Interactive delay: 20-second delays on new interactive operations`,explain:`Interactive delay comes before interactive rejection, when usage is over 10 minutes but at most 60.`},{id:`c`,text:`Background rejection: all new requests are rejected`,explain:`At this stage background operations are rejected too.`},{id:`d`,text:`Interactive rejection: new interactive operations are rejected`,explain:`Correct. Learn: in interactive rejection, new interactive operations are rejected while background operations can start and run.`}],answer:`d`},{id:`FO-21`,machineId:`water-wheel`,bulletIds:[],format:`yesno`,difficulty:2,stem:`You are explaining how Fabric capacities absorb spikes in usage. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[D],statements:[{id:`s1`,text:`Bursting lets an operation temporarily use more compute than the capacity SKU provides.`,answer:!0,explain:`Yes. Learn: with bursting, operations can temporarily use more compute than provisioned.`},{id:`s2`,text:`Background operations are smoothed over a 24-hour period.`,answer:!0,explain:`Yes. Background operations are smoothed over 24 hours.`},{id:`s3`,text:`Interactive operations are always smoothed over exactly one minute.`,answer:!1,explain:`No. Interactive operations are smoothed over a minimum of five minutes and up to 64 minutes.`}]},{id:`FO-22`,machineId:`water-wheel`,bulletIds:[],format:`single`,difficulty:2,stem:`Your organization wants a Fabric capacity it can use without a long-term commitment, billed per second, and Learn’s recommended SKU type. What should you buy?`,sources:[E],options:[{id:`a`,text:`An F SKU purchased through Azure`,explain:`Correct. F SKUs are billed per second with no commitment and are the recommended capacities for Fabric.`},{id:`b`,text:`A Power BI EM SKU`,explain:`Learn says Power BI EM SKUs don’t support Fabric.`},{id:`c`,text:`An A SKU`,explain:`A SKUs only support Power BI items.`},{id:`d`,text:`Power BI Pro licenses only`,explain:`Pro is a per-user license, not a capacity.`}],answer:`a`},{id:`FO-23`,machineId:`three-vats`,bulletIds:[],format:`single`,difficulty:1,stem:`You need a Fabric data store built for time-based streaming events, including semi-structured JSON and free-text analysis, that can query billions of events in seconds. What should you choose?`,sources:[M,j,k,w],options:[{id:`a`,text:`A warehouse`,explain:`A warehouse targets T-SQL analytics with multi-table transactions, not streaming events.`},{id:`b`,text:`An eventhouse`,explain:`Correct. Eventhouses are designed for streaming data and are the preferred engine for semi-structured and free-text analysis.`},{id:`c`,text:`A SQL database in Fabric`,explain:`Learn points operational, transactional (OLTP) workloads to SQL database in Fabric, not event analytics.`},{id:`d`,text:`A semantic model`,explain:`A semantic model is a metadata layer (tables, relationships, measures) for reporting, not a store for raw events.`}],answer:`b`},{id:`FO-24`,machineId:`three-vats`,bulletIds:[],format:`match`,difficulty:2,stem:`Your lakehouse follows the medallion architecture. Match each layer to what it stores.`,sources:[F],prompts:[{id:`p1`,text:`Bronze`},{id:`p2`,text:`Silver`},{id:`p3`,text:`Gold`}],choices:[{id:`c1`,text:`Raw data, stored exactly as it arrives`},{id:`c2`,text:`Enriched data: errors fixed, formats standardized, duplicates removed`},{id:`c3`,text:`Curated data organized for reports and dashboards`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Bronze keeps everything as it arrives; no changes are allowed.`},{promptId:`p2`,choiceId:`c2`,explain:`Silver fixes errors, standardizes formats, and removes duplicates.`},{promptId:`p3`,choiceId:`c3`,explain:`Gold is organized for reports and dashboards.`}]},{id:`FO-25`,machineId:`three-vats`,bulletIds:[],format:`yesno`,difficulty:2,stem:`You are comparing Fabric lakehouses and warehouses for a new project. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[A,j],statements:[{id:`s1`,text:`A lakehouse can store both structured and unstructured data.`,answer:!0,explain:`Yes. A lakehouse stores structured and unstructured data in one location.`},{id:`s2`,text:`Lakehouses and warehouses store their tables in different, incompatible formats.`,answer:!1,explain:`No. Both store data in Delta format on OneLake and share the same SQL engine.`},{id:`s3`,text:`The warehouse separates compute from storage so each can scale independently.`,answer:!0,explain:`Yes. Learn says storage and compute are separated in Fabric Data Warehouse.`}]},{id:`FO-26`,machineId:`three-vats`,bulletIds:[],format:`single`,difficulty:2,stem:`Data engineers in a lakehouse want to write transformations in Python, Scala, Spark SQL, or R. Where do they write and run that code?`,sources:[A,w,de],options:[{id:`a`,text:`In the SQL analytics endpoint editor`,explain:`The endpoint runs read-only T-SQL, not Spark code.`},{id:`b`,text:`In a KQL queryset`,explain:`KQL querysets run KQL against KQL databases.`},{id:`c`,text:`In DAX query view`,explain:`DAX query view runs DAX against semantic models.`},{id:`d`,text:`In a notebook attached to the lakehouse`,explain:`Correct. Notebooks run Spark code in Python, Scala, SQL, or R against lakehouse tables and folders.`}],answer:`d`},{id:`FO-27`,machineId:`three-vats`,bulletIds:[],format:`single`,difficulty:3,stem:`A team keeps raw files from a CSV export in the bronze layer and plans the silver and gold layers. According to Learn, which format should the silver and gold layers use?`,sources:[F],options:[{id:`a`,text:`The same format as the source, so CSV`,explain:`Keeping the source format describes bronze; for silver and gold, Learn recommends Delta tables (other files are only allowed).`},{id:`b`,text:`Delta tables`,explain:`Correct. Learn: the silver and gold layers should contain Delta tables.`},{id:`c`,text:`JSON files in the Files area`,explain:`Learn recommends Delta tables for silver and gold.`},{id:`d`,text:`Excel workbooks in OneDrive`,explain:`Workbooks aren’t a lakehouse layer format.`}],answer:`b`},{id:`FO-28`,machineId:`mill-lease`,bulletIds:[],format:`single`,difficulty:1,stem:`You start a Fabric trial by signing up yourself. Which role do you hold for the new trial capacity?`,sources:[O],options:[{id:`a`,text:`Capacity administrator`,explain:`Correct. Learn: signing up for a trial capacity makes you its Capacity administrator.`},{id:`b`,text:`Fabric administrator for the tenant`,explain:`Starting a trial makes you its Capacity administrator, which is a different role from Fabric administrator.`},{id:`c`,text:`Viewer only`,explain:`You manage the trial, so you’re more than a viewer.`},{id:`d`,text:`No role; the tenant admin owns it`,explain:`The person who signs up becomes the trial’s Capacity administrator.`}],answer:`a`},{id:`FO-29`,machineId:`mill-lease`,bulletIds:[],format:`single`,difficulty:2,stem:`You activated a trial capacity in your home region. A month later you want to move a trial workspace that contains Fabric items to a different region. What must you do first?`,sources:[O],options:[{id:`a`,text:`Nothing; workspaces move between regions automatically`,explain:`Learn requires extra work before moving a workspace with Fabric items.`},{id:`b`,text:`Export the workspace to a .pbix file`,explain:`This isn’t the documented requirement.`},{id:`c`,text:`Delete all existing Fabric items in the workspace`,explain:`Correct. Learn: to move a workspace with Fabric items to another region after the trial is created, you must delete all existing Fabric items first.`},{id:`d`,text:`Start a second trial in the new region`,explain:`A new trial doesn’t move the existing workspace.`}],answer:`c`},{id:`FO-30`,machineId:`mill-lease`,bulletIds:[],format:`yesno`,difficulty:2,stem:`You are the Capacity administrator of a Fabric trial and want coworkers to use it. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[O],statements:[{id:`s1`,text:`You can give coworkers permission to create workspaces in your trial capacity.`,answer:!0,explain:`Yes. As Capacity administrator, you manage who can create workspaces in the trial.`},{id:`s2`,text:`Assigning a workspace to the trial capacity adds coworkers who have roles in that workspace to the trial.`,answer:!0,explain:`Yes. Learn says this happens automatically.`},{id:`s3`,text:`The trial lasts 120 days unless you cancel it.`,answer:!1,explain:`No. The trial capacity lasts 60 days unless you cancel it earlier.`}]},{id:`FO-31`,machineId:`mill-lease`,bulletIds:[],format:`single`,difficulty:2,stem:`You started a Fabric trial and don’t have a Power BI Premium Per User license. Which other trial is added for you?`,sources:[O],options:[{id:`a`,text:`A Microsoft 365 E5 trial`,explain:`Learn doesn’t pair the Fabric trial with a Microsoft 365 trial.`},{id:`b`,text:`A Power BI individual trial`,explain:`Correct. The Fabric trial is complemented with a Power BI individual trial if you don’t already have PPU.`},{id:`c`,text:`An Azure free account`,explain:`This isn’t part of the Fabric trial.`},{id:`d`,text:`A Copilot Pro trial`,explain:`This isn’t part of the Fabric trial.`}],answer:`b`},{id:`FO-32`,machineId:`mill-lease`,bulletIds:[],format:`single`,difficulty:3,stem:`You are the trial’s Capacity administrator and already have a workspace on shared capacity. You want that workspace’s items to run on your trial capacity. What should you do?`,sources:[O],options:[{id:`a`,text:`Start a second trial from the workspace`,explain:`You already have a trial; you add workspaces to it.`},{id:`b`,text:`Ask a tenant admin to merge the workspace into OneLake`,explain:`Every workspace is already in OneLake; this isn’t the documented step.`},{id:`c`,text:`Create a shortcut from the trial workspace to each item`,explain:`Shortcuts reference data; they don’t move the workspace to the capacity.`},{id:`d`,text:`Change the workspace type to Trial in its workspace settings`,explain:`Correct. Learn: you can add workspaces to the trial capacity by changing their type to Trial in workspace settings.`}],answer:`d`}],I=`direct-lake-shuttle`,pe=[{id:`DS-V1`,machineId:I,bulletIds:[`S2.3`],format:`single`,difficulty:2,trapPairId:`dl-fallback`,stem:`A semantic model uses Direct Lake on SQL analytics endpoints with DirectLakeBehavior left at its default, Automatic. A warehouse administrator adds dynamic data masking to a column of a table the model uses. What happens to report queries against that table?`,sources:[t.dlHow],options:[{id:`a`,text:`They stay in Direct Lake mode and show the unmasked values`,explain:`Learn lists dynamic data masking defined at the SQL analytics endpoint as a condition that keeps a table out of Direct Lake mode.`},{id:`b`,text:`They fail with an error until the masking rule is removed`,explain:`An error is what DirectLakeOnly returns. With Automatic, the query falls back instead.`},{id:`c`,text:`They fall back to DirectQuery through the SQL analytics endpoint`,explain:`Correct. Dynamic data masking at the SQL analytics endpoint is a fallback cause, and with Automatic the query silently falls back to DirectQuery.`},{id:`d`,text:`The next refresh fails, but queries keep using the last framed data`,explain:`Learn lists masking as a condition for how queries are answered. With Automatic, the consequence is DirectQuery fallback for those queries.`}],answer:`c`},{id:`DS-V2`,machineId:I,bulletIds:[`S2.3`],format:`single`,difficulty:3,trapPairId:`dl-fallback`,stem:`A Direct Lake on SQL analytics endpoints model must never run DirectQuery, so its DirectLakeBehavior is set to DirectLakeOnly. Later, dynamic data masking is defined at the SQL analytics endpoint on a column of one of its tables. What do report users see for visuals that query that table?`,sources:[t.dlHow],options:[{id:`a`,text:`The visuals fail with an error`,explain:`Correct. Masking at the SQL analytics endpoint is a Direct Lake condition that isn’t met, and with DirectLakeOnly a query that can’t run in Direct Lake fails instead of falling back.`},{id:`b`,text:`The visuals fall back to DirectQuery anyway, because masking overrides the setting`,explain:`DirectLakeOnly prevents fallback; Learn says the query fails instead.`},{id:`c`,text:`The visuals load in Direct Lake mode with the masked values`,explain:`The table no longer meets the conditions for Direct Lake mode, so it isn’t answered from memory.`},{id:`d`,text:`The visuals load in Direct Lake mode, ignoring the mask`,explain:`The table no longer meets the conditions for Direct Lake mode.`}],answer:`a`}],me=`loom-gearbox`,L=`warp-frame`,R=`punch-card-reader`,z=`jacquard-head`,he=`wide-beam`,ge=`double-loom`,B=`speed-governor`,V=`direct-lake-shuttle`,H=`batch-winder`,_e=[{id:`LG-H1`,machineId:me,bulletIds:[`S1.1`],format:`single`,difficulty:3,trapPairId:`storage-modes`,stem:`A Direct Lake on OneLake semantic model reads an IT-managed lakehouse. A finance analyst has no write permission on that lakehouse but must add a small budget table from a spreadsheet, cleaned with Power Query, and relate it to the existing tables. What should the analyst do?`,sources:[t.directLake,t.composite],options:[{id:`a`,text:`Write the budget data into the lakehouse with a notebook so it becomes a Direct Lake table`,explain:`The analyst can’t modify the lakehouse, so this isn’t possible here.`},{id:`b`,text:`Switch the whole model to Direct Lake on SQL analytics endpoints and add the spreadsheet there`,explain:`Direct Lake on SQL can’t mix storage modes in the same model, so it can’t hold a spreadsheet table alongside its Direct Lake tables.`},{id:`c`,text:`Add the budget as an Import table to the model, making it a composite model`,explain:`Correct. Learn suggests Import tables when the author can’t modify the source item, because Import supports Power Query preparation inside the model, and Direct Lake on OneLake tables can be combined with Import tables.`},{id:`d`,text:`Add the spreadsheet as a DirectQuery table so it always shows the latest values`,explain:`DirectQuery queries the source on every visual and is limited to M that can be translated; Learn’s suggestion for Power Query preparation inside the model is an Import table.`}],answer:`c`},{id:`WF-H1`,machineId:L,bulletIds:[`S1.2`],format:`single`,difficulty:3,stem:`An imported model has Product, Subcategory, and Category tables related in a chain, and a Sales fact with OrderDateKey and ShipDateKey columns. Report authors need a Category > Subcategory > Product hierarchy and must analyze sales by order date and by ship date with a single Date table. What should you do?`,sources:[t.star,t.relationships],options:[{id:`a`,text:`Keep the three product tables and set every relationship to Both; relate Date to Sales twice, both active`,explain:`A hierarchy can’t span tables, and only one relationship between two tables can be active.`},{id:`b`,text:`Flatten the product tables into one Product table; make the order-date relationship active and the ship-date one inactive, used through USERELATIONSHIP in ship-date measures`,explain:`Correct. Flattening lets the hierarchy come from one table, and a role-playing Date table keeps one active relationship while measures activate the inactive one with USERELATIONSHIP.`},{id:`c`,text:`Flatten the product tables, and duplicate the Sales fact so each copy has one active date relationship`,explain:`Duplicating the fact doubles its size and splits measures; USERELATIONSHIP handles the second date role.`},{id:`d`,text:`Relate Date to Sales on ShipDateKey only, and build the order-date analysis with a calculated column`,explain:`That makes order-date analysis depend on per-row workarounds instead of the role-playing pattern Learn describes.`}],answer:`b`},{id:`WF-H2`,machineId:L,bulletIds:[`S1.2`],format:`yesno`,difficulty:3,stem:`You are reviewing a star schema semantic model before it goes to production. Some analysts use Analyze in Excel. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.star,t.relationships,t.calcGroups],statements:[{id:`s1`,text:`Analysts using Analyze in Excel can only aggregate numbers through explicit DAX measures.`,answer:!0,explain:`Yes. Learn notes MDX clients such as Analyze in Excel need explicit measures.`},{id:`s2`,text:`Setting every dimension-to-fact relationship to Both is the recommended default for a star schema.`,answer:!1,explain:`No. Keep cross-filter direction single unless a specific pattern, such as a bridge table, needs Both.`},{id:`s3`,text:`Two relationships between Date and Sales can both be active if they use different columns.`,answer:!1,explain:`No. Only one relationship between two tables can be active; the others are inactive and used with USERELATIONSHIP.`}]},{id:`WF-H3`,machineId:L,bulletIds:[`S1.3`],format:`single`,difficulty:3,trapPairId:`regular-vs-limited`,stem:`Sales targets are stored by product category and month, but the Product dimension is at product level and the Date dimension is at day level. Targets must filter correctly when users slice by category and by month. How should you relate the Target table on the Category column?`,sources:[t.manyToMany,t.relationships],options:[{id:`a`,text:`Use a many-to-many relationship between Product[Category] and Target[Category] that filters in a single direction, from Product to Target`,explain:`Correct. For higher-grain facts on a non-date column, Learn uses a many-to-many relationship filtering from the dimension to the fact.`},{id:`b`,text:`Use a many-to-many relationship between Product[Category] and Target[Category] with cross-filter direction set to Both`,explain:`Learn’s guidance for this case filters in a single direction, from the dimension to the fact.`},{id:`c`,text:`Add a bridge table of all category–product pairs and relate it with one-to-many relationships`,explain:`A bridge resolves many-to-many dimensions; for a higher-grain fact, Learn relates the fact on the category column directly.`},{id:`d`,text:`Relate Target to Product on ProductKey after copying each target to every product in its category`,explain:`Spreading targets across products duplicates the target amounts and gives wrong totals.`}],answer:`a`},{id:`PC-H1`,machineId:R,bulletIds:[`S1.4`],format:`single`,difficulty:3,stem:`A developer writes this measure to return last year's sales: Sales LY = VAR CurrentSales = [Total Sales] RETURN CALCULATE(CurrentSales, SAMEPERIODLASTYEAR('Date'[Date])). In a visual by year it shows the same values as Total Sales. Why, and what is the fix?`,sources:[t.varBP,t.varRef,t.calculate],options:[{id:`a`,text:`SAMEPERIODLASTYEAR needs a marked date table; mark Date as a date table`,explain:`Marking the date table doesn’t change how the variable is evaluated, which is the cause here.`},{id:`b`,text:`VAR can’t hold a measure value; use a calculated column instead`,explain:`Variables can hold any value, including a measure result.`},{id:`c`,text:`The variable is evaluated once, before CALCULATE applies its filter; put CALCULATE([Total Sales], SAMEPERIODLASTYEAR(…)) inside the variable or the RETURN`,explain:`Correct. A variable is evaluated once, outside the filters the RETURN expression applies, so CALCULATE can’t change a value that was already computed.`},{id:`d`,text:`CALCULATE ignores time intelligence filters; use FILTER over the Date table`,explain:`CALCULATE accepts table filter functions such as SAMEPERIODLASTYEAR; the problem is the variable’s evaluation.`}],answer:`c`},{id:`PC-H2`,machineId:R,bulletIds:[`S1.4`],format:`single`,difficulty:3,stem:`A matrix shows sales by month for each product category. You need a measure that shows the previous month’s sales on each row, restarting for every category. Which DAX function family fits best, and how?`,sources:[t.offset,t.window,t.index],options:[{id:`a`,text:`INDEX, with position 1, ORDERBY month, and PARTITIONBY category`,explain:`INDEX returns a row by absolute position, so position 1 is always the first month of the category.`},{id:`b`,text:`OFFSET, with -1, ORDERBY month, and PARTITIONBY category`,explain:`Correct. OFFSET returns the row a given distance before or after the current row; -1 is the previous month, and PARTITIONBY restarts it for each category.`},{id:`c`,text:`WINDOW, from the first row to the current row, ORDERBY month`,explain:`That window covers every month up to the current one, which suits a running total, not the previous month.`},{id:`d`,text:`HASONEVALUE on the month column, then subtract one from the month number`,explain:`HASONEVALUE only tests whether one value is filtered; it doesn’t navigate rows.`}],answer:`b`},{id:`JH-H1`,machineId:z,bulletIds:[`S1.5`],format:`multi`,difficulty:3,trapPairId:`calcgroup-vs-fieldparam`,stem:`You add a time intelligence calculation group to a model that previously relied on report authors dragging numeric columns into visuals. Which two effects should you warn the authors about? Choose two.`,sources:[t.calcGroups,t.fieldParams],options:[{id:`a`,text:`Existing field parameters stop working until they are rebuilt`,explain:`Learn lists no such effect; field parameter limits concern implicit measures, AI visuals, drillthrough, and live connections.`},{id:`b`,text:`Every measure in reports changes to the variant data type`,explain:`Correct. Adding any calculation group changes measures to the variant data type; removing all calculation groups reverts them.`},{id:`c`,text:`Dragging a numeric column to sum it no longer works, so they need explicit measures`,explain:`Correct. Calculation groups need Discourage implicit measures turned on, which blocks adding data columns to visuals as values; existing implicit measures in visuals keep working, but new ones can’t be created.`},{id:`d`,text:`The calculation items can only apply to one measure, chosen when the group is created`,explain:`Calculation items use SELECTEDMEASURE(), so they apply to whatever measure is in the visual.`}],answers:[`b`,`c`]},{id:`JH-H2`,machineId:z,bulletIds:[`S1.5`],format:`single`,difficulty:3,trapPairId:`dfs-vs-format`,stem:`Readers must switch one column chart between Sales, Margin, and Units with a slicer. A Year-over-Year calculation item must show as a percentage while staying numeric so the chart can plot it. Which design meets both requirements?`,sources:[t.fieldParams,t.dynamicFormat,t.calcGroups],options:[{id:`a`,text:`A field parameter for the three measures, and a dynamic format string on the Year-over-Year calculation item`,explain:`Correct. A field parameter lets readers swap which measure the visual shows, and a dynamic format string changes the display format while the value stays numeric.`},{id:`b`,text:`A calculation group with Sales, Margin, and Units items, and FORMAT() in the Year-over-Year item`,explain:`A calculation group changes how measures are calculated rather than which measure is shown, and FORMAT() returns text the chart can’t plot.`},{id:`c`,text:`Three bookmarks with three charts, and FORMAT() in the Year-over-Year item`,explain:`FORMAT() turns the result into text, which breaks charts that need numbers.`},{id:`d`,text:`A field parameter for the three measures, and a static percentage format on every base measure`,explain:`A static percentage format would also display Sales and Units as percentages.`}],answer:`a`},{id:`WB-H1`,machineId:he,bulletIds:[`S1.6`],format:`single`,difficulty:3,stem:`An Import model is 8 GB in Power BI Desktop. With incremental refresh in a workspace on a Fabric F capacity, it is expected to grow to about 25 GB, and a CI/CD tool deploys metadata changes through the XMLA endpoint. What should you do?`,sources:[t.largeModels,t.xmla],options:[{id:`a`,text:`Keep the default storage format; it grows automatically to the capacity limit`,explain:`The default format is limited (1 GB by default in the service); large models beyond 10 GB require the large semantic model storage format.`},{id:`b`,text:`Publish the full 25 GB file from Power BI Desktop after loading all history locally`,explain:`Publishing from Desktop is still capped at 10 GB; large models grow beyond that through refresh in the service.`},{id:`c`,text:`Move the model to a Pro workspace to remove the size limit`,explain:`Pro workspaces don’t lift the limit and don’t support XMLA write operations.`},{id:`d`,text:`Turn on large semantic model storage format, publish the smaller file, and let refreshes in the service grow it`,explain:`Correct. The large format is required beyond 10 GB and recommended for XMLA write operations, and the model grows through refresh after publishing.`}],answer:`d`},{id:`DL-H1`,machineId:ge,bulletIds:[`S1.7`],format:`single`,difficulty:3,trapPairId:`dual-vs-hybrid`,stem:`A composite model has a large Sales fact in DirectQuery from a SQL source and a Customer dimension in Import mode from the same source. Sales rows whose customer key has no match silently disappear from visuals, and queries that filter by customer are slow. Which change addresses both issues?`,sources:[t.modes,t.composite,t.relationships],options:[{id:`a`,text:`Change the Customer table to Import partitions plus a DirectQuery partition (a hybrid table)`,explain:`Hybrid tables are usually created through an incremental refresh policy with real-time DirectQuery and are typically facts; they don’t change how this dimension relates to the fact.`},{id:`b`,text:`Set the relationship’s cross-filter direction to Both`,explain:`Direction doesn’t change the cross-source-group relationship, which stays limited.`},{id:`c`,text:`Set the Customer table to Dual storage mode`,explain:`Correct. Dual is typically used for dimensions in a composite model so relationships with DirectQuery facts stay regular, and the engine can send one efficient native query joining the fact to the filtered dimension.`},{id:`d`,text:`Change the Sales fact to Import and drop the DirectQuery source`,explain:`That gives up the DirectQuery fact the design needs for its freshness or size, rather than fixing the relationship.`}],answer:`c`},{id:`SG-H1`,machineId:B,bulletIds:[`S2.1`],format:`single`,difficulty:3,trapPairId:`perf-categories`,stem:`Performance Analyzer shows that an unfiltered scatter chart takes most of its time in Visual display, while its DAX query time is small. The chart plots every one of tens of thousands of customers. What should you change first?`,sources:[t.perfAnalyzer,t.optimization],options:[{id:`a`,text:`Rewrite the chart’s measures with variables`,explain:`The DAX query time is already small; rewriting DAX targets the wrong category.`},{id:`b`,text:`Reduce what the visual draws, for example with a Top N filter or by summarizing to fewer points`,explain:`Correct. Visual display is rendering time, fixed by report design such as fewer data points, and Learn suggests restrictive filters such as Top N.`},{id:`c`,text:`Switch the model’s tables to DirectQuery`,explain:`DirectQuery adds source query time; it doesn’t reduce rendering.`},{id:`d`,text:`Turn on large semantic model storage format`,explain:`Storage format affects model size limits, not how long a visual takes to draw.`}],answer:`b`},{id:`SG-H2`,machineId:B,bulletIds:[`S2.1`],format:`yesno`,difficulty:3,stem:`You are diagnosing slow visuals on a Direct Lake on SQL analytics endpoints model with Performance Analyzer and SQL Server Profiler. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.dlAnalyze,t.perfAnalyzer,t.dataReduction],statements:[{id:`s1`,text:`Every DirectQuery Begin/End event in a Profiler trace means a query fell back to DirectQuery.`,answer:!1,explain:`No. EngineEdition and OLS check queries always use DirectQuery and don’t mean fallback.`},{id:`s2`,text:`A Direct query line under a visual in Performance Analyzer means that visual’s query fell back.`,answer:!0,explain:`Yes. For a Direct Lake model, a Direct query duration shows the visual’s query was answered through DirectQuery.`},{id:`s3`,text:`Turning off auto date/time usually makes an Import model larger.`,answer:!1,explain:`No. Learn lists disabling auto date/time as a way to reduce Import model size.`}]},{id:`SG-H3`,machineId:B,bulletIds:[`S2.2`],format:`dropdown`,difficulty:3,stem:`You are rewriting three slow measures to follow Learn’s DAX guidance. Complete the definitions.`,sources:[t.bpFilter,t.bpDivide,t.bpCountrows],language:`dax`,code:`Red Sales = CALCULATE([Sales], [[1]](Product[Color] = "Red"))

Margin % = [[2]]([Profit], [Sales])

Order Lines = [[3]](Sales)`,slots:[{id:`1`,options:[{id:`a`,text:`KEEPFILTERS`,explain:`Correct. A Boolean filter on one column, optionally wrapped in KEEPFILTERS to keep existing filters, is preferred over FILTER over a whole table.`},{id:`b`,text:`FILTER(Product, `,explain:`FILTER over the whole Product table is the pattern Learn advises against when a Boolean column filter works.`},{id:`c`,text:`ALL`,explain:`ALL removes filters; it doesn’t take a Boolean expression.`}],answer:`a`},{id:`2`,options:[{id:`a`,text:`IFERROR`,explain:`IFERROR catches errors after they happen; DIVIDE handles zero and blank denominators directly and is better optimized.`},{id:`b`,text:`DIVIDE`,explain:`Correct. DIVIDE handles zero or blank denominators and is better optimized than testing the denominator with IF.`},{id:`c`,text:`SUMX`,explain:`SUMX iterates a table; it doesn’t divide two values.`}],answer:`b`},{id:`3`,options:[{id:`a`,text:`COUNT`,explain:`COUNT needs a column and counts its non-blank values; COUNTROWS counts table rows more efficiently.`},{id:`b`,text:`DISTINCTCOUNT`,explain:`DISTINCTCOUNT counts distinct values of a column, not rows.`},{id:`c`,text:`COUNTROWS`,explain:`Correct. COUNTROWS counts the rows of a table and is more efficient than COUNT on a column.`}],answer:`c`}]},{id:`DLS-H1`,machineId:V,bulletIds:[`S2.3`],format:`single`,difficulty:3,trapPairId:`framing-vs-import-refresh`,stem:`A nightly ETL rewrites several Delta tables over two hours. While it runs, users of a Direct Lake model see a mix of new and old data in the same report. Business users must only see the data once the whole load has finished. What should you do?`,sources:[t.dlHow,t.directLake],options:[{id:`a`,text:`Set DirectLakeBehavior to DirectQueryOnly during the load`,explain:`DirectQuery reads the latest data from the source, so users would see the half-finished load even sooner.`},{id:`b`,text:`Schedule an Import refresh of the model after the load`,explain:`A Direct Lake model’s refresh is framing, not a data copy; turning the model into Import isn’t needed.`},{id:`c`,text:`Increase the capacity SKU so the ETL finishes faster`,explain:`A faster ETL still exposes partial data to users while it runs.`},{id:`d`,text:`Turn off “Keep your Direct Lake data up to date” and refresh (reframe) the model when the ETL completes`,explain:`Correct. Automatic updates reframe whenever Delta tables change; turning them off and framing after the load fixes the point in time users see.`}],answer:`d`},{id:`DLS-H2`,machineId:V,bulletIds:[`S2.3`],format:`match`,difficulty:2,trapPairId:`dl-fallback`,stem:`A team uses a Direct Lake on SQL analytics endpoints model in development, test, and production. Match each goal to the DirectLakeBehavior setting Learn suggests for it.`,sources:[t.dlHow],prompts:[{id:`p1`,text:`In production, keep reports working even if a query can’t use Direct Lake`},{id:`p2`,text:`In development, make any query that can’t use Direct Lake fail so it gets fixed`},{id:`p3`,text:`Measure how fast the model would be if every query used DirectQuery`}],choices:[{id:`c1`,text:`Automatic`},{id:`c2`,text:`DirectLakeOnly`},{id:`c3`,text:`DirectQueryOnly`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Automatic (the default) silently falls back to DirectQuery, so reports keep working.`},{promptId:`p2`,choiceId:`c2`,explain:`DirectLakeOnly makes such queries fail with an error, which surfaces problems during development.`},{promptId:`p3`,choiceId:`c3`,explain:`DirectQueryOnly forces DirectQuery for every query, which lets you measure fallback performance.`}]},{id:`DLS-H3`,machineId:V,bulletIds:[`S2.4`],format:`single`,difficulty:3,trapPairId:`dl-onelake-vs-sql`,stem:`A new Direct Lake model must combine Delta tables from two lakehouses with a KQL database that has OneLake availability turned on, and it must also hold a small Import table. No SQL views are used. Which option fits?`,sources:[t.directLake,t.dlHow],options:[{id:`a`,text:`Direct Lake on SQL analytics endpoints, one model per source item`,explain:`Direct Lake on SQL uses a single source item, doesn’t support KQL databases, and can’t mix storage modes in one model.`},{id:`b`,text:`Direct Lake on OneLake`,explain:`Correct. It can use Delta tables from more than one Fabric item, supports KQL databases with OneLake availability, and can be combined with Import tables.`},{id:`c`,text:`Direct Lake on SQL analytics endpoints with DirectLakeBehavior set to Automatic`,explain:`The setting only controls fallback; it doesn’t add multiple sources, KQL data, or Import tables.`},{id:`d`,text:`DirectQuery to each lakehouse’s SQL analytics endpoint`,explain:`DirectQuery sends every query to the source, giving up the in-memory performance the Direct Lake requirement asks for.`}],answer:`b`},{id:`BW-H1`,machineId:H,bulletIds:[`S2.5`],format:`single`,difficulty:3,stem:`A model already has an incremental refresh policy on Sales that uses RangeStart and RangeEnd. A developer adds a policy to the Returns table, filtering it with two new Date/Time parameters named ReturnsFrom and ReturnsTo so it can keep a different history length. What should you do?`,sources:[t.incrementalCfg,t.incremental],options:[{id:`a`,text:`Filter Returns with the same RangeStart and RangeEnd parameters, and set its different periods in its own policy`,explain:`Correct. Every table with a policy must use the same RangeStart and RangeEnd parameters (reserved, case-sensitive names), even when their archive and refresh periods differ.`},{id:`b`,text:`Keep ReturnsFrom and ReturnsTo; the service overrides any Date/Time parameters for each partition`,explain:`The service overrides only the reserved RangeStart and RangeEnd parameters.`},{id:`c`,text:`Rename the parameters to rangestart and rangeend in lowercase`,explain:`The names are case-sensitive, so they must be RangeStart and RangeEnd.`},{id:`d`,text:`Move Returns into a separate model so it can use its own parameters`,explain:`Splitting the model isn’t needed; both tables can share the parameters and keep different periods.`}],answer:`a`},{id:`BW-H2`,machineId:H,bulletIds:[`S2.5`],format:`multi`,difficulty:3,trapPairId:`archive-vs-refresh-period`,stem:`You are reviewing an incremental refresh setup on a Sales table partitioned by OrderDate. Which two settings will cause problems? Choose two.`,sources:[t.incrementalCfg,t.incremental],options:[{id:`a`,text:`Archive data starting 5 years before refresh date, and incrementally refresh data starting 3 days before refresh date`,explain:`This is a normal policy: a long archive period and a short refresh window.`},{id:`b`,text:`A filter of OrderDate >= RangeStart and OrderDate <= RangeEnd`,explain:`Correct. Equal-to on both parameters can put a boundary row in two partitions and duplicate data.`},{id:`c`,text:`Only refresh complete days turned on`,explain:`This is an optional setting that doesn’t cause the problems described.`},{id:`d`,text:`Detect data changes set to the OrderDate column`,explain:`Correct. The Detect data changes column must be different from the column used for RangeStart/RangeEnd partitioning.`}],answers:[`b`,`d`]}],U=`loom-gearbox`,W=`warp-frame`,G=`punch-card-reader`,K=`jacquard-head`,ve=[{id:`LG-01`,machineId:U,bulletIds:[`S1.1`],format:`single`,difficulty:2,placement:!0,trapPairId:`storage-modes`,stem:`Data engineers maintain several billion-row Delta tables in a Fabric lakehouse. You need a semantic model with VertiPaq query performance, without copying the data into the model, and with refreshes that finish in seconds. Which storage mode should you use?`,sources:[t.directLake],options:[{id:`a`,text:`Import`,explain:`Import copies the whole data volume into the model, and its refresh can take considerable time and capacity.`},{id:`b`,text:`DirectQuery`,explain:`DirectQuery doesn’t copy data, but it federates every query to the source instead of using VertiPaq.`},{id:`c`,text:`Direct Lake`,explain:`Correct. Direct Lake loads Delta columns into VertiPaq on demand, and its refresh copies only metadata (framing), which takes seconds.`},{id:`d`,text:`Dual`,explain:`Dual acts as Import or DirectQuery per query, so it still needs an Import copy of the data.`}],answer:`c`},{id:`LG-02`,machineId:U,bulletIds:[`S1.1`],format:`single`,difficulty:2,placement:!0,stem:`A self-service analyst builds a Direct Lake model on a lakehouse that IT manages. The analyst has no write permission on the lakehouse but needs to add a small lookup table that requires data preparation. What does Learn suggest?`,sources:[t.directLake],options:[{id:`a`,text:`Ask IT for Contributor access and write the table with Spark`,explain:`Learn’s suggestion keeps the analyst out of the IT-managed lakehouse.`},{id:`b`,text:`Add a calculated column to an existing Direct Lake table`,explain:`This doesn’t give the analyst a separate table with data preparation.`},{id:`c`,text:`Convert the whole model to DirectQuery`,explain:`DirectQuery doesn’t add data preparation and would give up VertiPaq performance.`},{id:`d`,text:`Add an Import table and prepare the data with Power Query`,explain:`Correct. Learn: when the author can’t modify the source item, augmenting the model with Import tables might be a good choice because Import supports Power Query.`}],answer:`d`},{id:`LG-03`,machineId:U,bulletIds:[`S1.1`],format:`single`,difficulty:2,placement:!0,trapPairId:`framing-vs-import-refresh`,stem:`A pipeline appends new rows to the Delta tables behind a Direct Lake semantic model and then refreshes the model. What does that refresh do?`,sources:[t.directLake],options:[{id:`a`,text:`It updates metadata to point at the latest Delta table version`,explain:`Correct. A Direct Lake refresh (framing) analyzes the latest Delta metadata and updates references to the latest files.`},{id:`b`,text:`It reloads every table into a cached copy inside the model`,explain:`That describes an Import refresh, which replicates the data.`},{id:`c`,text:`It sends a native query to the SQL analytics endpoint for each table`,explain:`Refresh doesn’t run DirectQuery; it updates metadata.`},{id:`d`,text:`It rebuilds the Delta tables’ Parquet files in OneLake`,explain:`Refresh reads Delta metadata; it doesn’t rewrite the files.`}],answer:`a`},{id:`LG-04`,machineId:U,bulletIds:[`S1.1`],format:`yesno`,difficulty:2,placement:!0,trapPairId:`storage-modes`,stem:`You are comparing storage modes for a new Fabric semantic model. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.directLake],statements:[{id:`s1`,text:`Direct Lake requires a Fabric capacity (SKU), while Import and DirectQuery work with any Fabric or Power BI license.`,answer:!0,explain:`Yes. Learn’s comparison lists Fabric capacity subscriptions only for Direct Lake and any license for Import and DirectQuery.`},{id:`s2`,text:`Direct Lake tables support hybrid tables and model table partitions.`,answer:!1,explain:`No. Hybrid tables and model table partitions aren’t supported in Direct Lake; partition the Delta tables instead.`},{id:`s3`,text:`Direct Lake and Import queries are both processed by the VertiPaq engine.`,answer:!0,explain:`Yes. DirectQuery is the mode that federates queries to the source.`}]},{id:`LG-05`,machineId:U,bulletIds:[`S1.1`],format:`match`,difficulty:2,placement:!0,trapPairId:`storage-modes`,stem:`Match each requirement to the storage mode that best fits it.`,sources:[t.directLake,t.modes,t.storageMode],prompts:[{id:`p1`,text:`An analyst must shape spreadsheet data with Power Query inside the model`},{id:`p2`,text:`Reports must show near-real-time data from a large external SQL database, beyond scheduled refresh limits`},{id:`p3`,text:`Large Delta tables already prepared in a Fabric warehouse must be queried without copying them`},{id:`p4`,text:`A Date table must relate to both Import and DirectQuery fact tables while keeping relationships regular`}],choices:[{id:`c1`,text:`Import`},{id:`c2`,text:`DirectQuery`},{id:`c3`,text:`Direct Lake`},{id:`c4`,text:`Dual`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Import supports Power Query data preparation defined in the model.`},{promptId:`p2`,choiceId:`c2`,explain:`DirectQuery queries the source each time, so data is current without waiting for a refresh.`},{promptId:`p3`,choiceId:`c3`,explain:`Direct Lake reads Delta tables in OneLake without replicating them.`},{promptId:`p4`,choiceId:`c4`,explain:`Dual tables can act as Import or DirectQuery, which helps keep relationships regular.`}]},{id:`LG-06`,machineId:U,bulletIds:[`S1.1`],format:`single`,difficulty:3,placement:!0,stem:`A Direct Lake model’s fact table holds ten years of sales. You want to manage the data by year, the way you used partitions in Import models. What should you do?`,sources:[t.directLake],options:[{id:`a`,text:`Add model table partitions by year in Tabular Editor`,explain:`Direct Lake doesn’t support model table partitions.`},{id:`b`,text:`Configure incremental refresh to create a hybrid table`,explain:`Direct Lake doesn’t support hybrid tables.`},{id:`c`,text:`Partition the Delta table in the lakehouse`,explain:`Correct. Partitioning belongs at the Delta table level, because Direct Lake models can’t have model partitions.`},{id:`d`,text:`Switch the fact table to Dual storage mode`,explain:`Dual doesn’t partition anything and isn’t a Direct Lake option.`}],answer:`c`},{id:`LG-07`,machineId:U,bulletIds:[`S1.1`],format:`single`,difficulty:2,placement:!0,stem:`In October 2026, you create a new lakehouse. A report author asks where its default semantic model is so they can build a report. What should you tell them?`,sources:[t.semanticModels],options:[{id:`a`,text:`It appears in the workspace a few minutes after the lakehouse`,explain:`Default semantic models are no longer created automatically.`},{id:`b`,text:`It is hidden under the lakehouse’s SQL analytics endpoint`,explain:`There’s no hidden default model; none is created.`},{id:`c`,text:`It is created the first time someone runs a SQL query`,explain:`Querying doesn’t create a semantic model.`},{id:`d`,text:`None is created, so create a semantic model on the lakehouse`,explain:`Correct. Since September 5, 2025, default semantic models aren’t created when a warehouse, lakehouse, or mirrored item is created.`}],answer:`d`},{id:`LG-08`,machineId:U,bulletIds:[`S1.1`],format:`single`,difficulty:1,stem:`An Import semantic model is on a Premium capacity. Business users ask for more frequent scheduled refreshes. What is the maximum number of scheduled refreshes per day?`,sources:[t.modes],options:[{id:`a`,text:`8`,explain:`Eight per day is the limit on shared capacity.`},{id:`b`,text:`48`,explain:`Correct. Learn: 48 times a day for a Premium capacity.`},{id:`c`,text:`24`,explain:`This isn’t one of the documented limits.`},{id:`d`,text:`96`,explain:`This isn’t one of the documented limits.`}],answer:`b`},{id:`LG-09`,machineId:U,bulletIds:[`S1.1`],format:`single`,difficulty:3,placement:!0,stem:`In Power BI Desktop you change a DirectQuery table to Import, then decide you want it back in DirectQuery. You aren’t using web modeling or live editing. What happens?`,sources:[t.storageMode],options:[{id:`a`,text:`You select DirectQuery again in the table’s storage mode property`,explain:`After changing to Import or Dual, the mode can’t be set back to DirectQuery in this case.`},{id:`b`,text:`Power BI switches it back automatically at the next refresh`,explain:`Storage mode never changes on its own at refresh.`},{id:`c`,text:`It can’t be set back to DirectQuery`,explain:`Correct. Learn: after you change a DirectQuery table to Import or Dual, you can’t set it back to DirectQuery (except with web modeling or live editing).`},{id:`d`,text:`You set it to Dual first, then to DirectQuery`,explain:`Dual can’t be set back to DirectQuery either.`}],answer:`c`},{id:`LG-10`,machineId:U,bulletIds:[`S1.1`],format:`multi`,difficulty:2,placement:!0,stem:`Your organization is weighing Direct Lake for an IT-managed analytics project on OneLake. Which two statements describe benefits Learn lists for Direct Lake? Choose two.`,sources:[t.directLake],options:[{id:`a`,text:`Power Query transformations run inside the model for every Direct Lake table`,explain:`Power Query preparation is an Import feature; Direct Lake relies on upstream preparation.`},{id:`b`,text:`Analyzed data volumes can exceed the capacity’s max memory, because only the data needed for a query is loaded`,explain:`Correct. Learn lists this as an ROI benefit of Direct Lake.`},{id:`c`,text:`It works with any Power BI license, including Free`,explain:`Direct Lake requires a Fabric capacity subscription.`},{id:`d`,text:`Data preparation moves upstream to OneLake, using Spark, T-SQL, dataflows, and pipelines`,explain:`Correct. Direct Lake depends on preparation in the lake, which maximizes reuse.`}],answers:[`b`,`d`]},{id:`WF-01`,machineId:W,bulletIds:[`S1.2`],format:`dropdown`,difficulty:2,stem:`The Sales table has OrderDate and ShipDate columns, both related to the Date table. The OrderDate relationship is active. You need a measure that totals sales by ship date. Complete the DAX.`,sources:[t.star,t.calculate],language:`dax`,code:`Sales by Ship Date =
[[1]](
    [Sales],
    [[2]](Sales[ShipDate], [[3]])
)`,slots:[{id:`1`,options:[{id:`a`,text:`CALCULATE`,explain:`Correct. CALCULATE evaluates [Sales] with the modified relationship.`},{id:`b`,text:`SUMX`,explain:`SUMX iterates a table; it can’t take a relationship modifier.`},{id:`c`,text:`FILTER`,explain:`FILTER returns a table; it doesn’t evaluate a measure with modifiers.`}],answer:`a`},{id:`2`,options:[{id:`a`,text:`TREATAS`,explain:`TREATAS applies values as filters to unrelated columns; the relationship already exists.`},{id:`b`,text:`USERELATIONSHIP`,explain:`Correct. The only way to use an inactive relationship is a DAX expression with USERELATIONSHIP.`},{id:`c`,text:`RELATED`,explain:`RELATED fetches a value from the one side in row context.`}],answer:`b`},{id:`3`,options:[{id:`a`,text:`'Date'[Date]`,explain:`Correct. The inactive relationship is between Sales[ShipDate] and the Date table’s date column.`},{id:`b`,text:`Sales[OrderDate]`,explain:`That column is on the active relationship, not the ship date one.`},{id:`c`,text:`[Sales]`,explain:`USERELATIONSHIP takes two columns, not a measure.`}],answer:`a`}]},{id:`WF-02`,machineId:W,bulletIds:[`S1.2`],format:`single`,difficulty:2,placement:!0,stem:`Report authors build visuals by dragging numeric columns and letting Power BI sum them. You plan to add a calculation group for time intelligence. What must change in how authors work?`,sources:[t.calcGroups],options:[{id:`a`,text:`They must switch every visual to DirectQuery`,explain:`Calculation groups don’t depend on storage mode changes.`},{id:`b`,text:`They must use explicit DAX measures`,explain:`Correct. Calculation groups need Discourage implicit measures; calculation items only apply to explicit measures.`},{id:`c`,text:`They must build reports from a field parameter only`,explain:`Field parameters are separate and not required by calculation groups.`},{id:`d`,text:`They must remove all relationships to the Date table`,explain:`Calculation groups work with normal relationships.`}],answer:`b`},{id:`WF-03`,machineId:W,bulletIds:[`S1.2`],format:`single`,difficulty:1,stem:`A model table holds OrderQuantity, SalesAmount, and keys for Product, Customer, and Date. Which role should it play in a star schema?`,sources:[t.star],options:[{id:`a`,text:`A fact table`,explain:`Correct. It stores events with measures to summarize and dimension keys.`},{id:`b`,text:`A dimension table`,explain:`Dimension tables describe entities for filtering and grouping, not numeric events.`},{id:`c`,text:`A bridging table`,explain:`A bridging table stores key pairs to resolve a many-to-many relationship.`},{id:`d`,text:`A disconnected table`,explain:`A disconnected table has no relationships and accepts user input.`}],answer:`a`},{id:`WF-04`,machineId:W,bulletIds:[`S1.2`],format:`yesno`,difficulty:2,placement:!0,stem:`You are building relationships in a semantic model on Fabric data. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.star,t.relationships,t.directLake],statements:[{id:`s1`,text:`Only one relationship between two model tables can be active at a time.`,answer:!0,explain:`Yes. Learn: there can only be one active relationship between two semantic model tables.`},{id:`s2`,text:`You can relate an EmployeeID column to a ManagerID column in the same table to build a hierarchy.`,answer:!1,explain:`No. It isn’t possible to relate a column to a different column in the same table; use the parent and child DAX functions.`},{id:`s3`,text:`In a Direct Lake model, the columns on both sides of a relationship need matching data types.`,answer:!0,explain:`Yes. Learn’s Direct Lake guidance requires the data types of related columns to match.`}]},{id:`WF-05`,machineId:W,bulletIds:[`S1.2`],format:`single`,difficulty:2,placement:!0,stem:`Visuals in a Direct Lake model start failing after a load. You find duplicate ProductKey values in the Product table, which is the one side of its relationship to Sales. What should you do?`,sources:[t.directLake],options:[{id:`a`,text:`Change the relationship to many-to-many in the model`,explain:`That hides a data problem and makes the relationship limited; fix the dimension instead.`},{id:`b`,text:`Set the relationship’s cross-filter direction to Both`,explain:`Filter direction doesn’t fix a non-unique one side.`},{id:`c`,text:`Make ProductKey unique in the Product Delta table`,explain:`Correct. Duplicates on the one side make Direct Lake queries fail, so the key must be unique in the source table.`},{id:`d`,text:`Switch the Product table to Dual storage mode`,explain:`Direct Lake tables don’t use Dual, and the duplicates would remain.`}],answer:`c`},{id:`WF-06`,machineId:W,bulletIds:[`S1.2`],format:`single`,difficulty:2,placement:!0,trapPairId:`star-vs-snowflake`,stem:`A semantic model imports Product, Subcategory, and Category as three related tables. Report authors want one Category > Subcategory > Product hierarchy in the Data pane. What should you do?`,sources:[t.star,t.dimTables],options:[{id:`a`,text:`Create the hierarchy across the three related tables`,explain:`A model hierarchy can only be based on columns from a single table.`},{id:`b`,text:`Set all relationships among the three tables to Both`,explain:`Filter direction doesn’t let a hierarchy span tables.`},{id:`c`,text:`Add a calculation group with one item per level`,explain:`Calculation groups change measure logic; they don’t build hierarchies.`},{id:`d`,text:`Flatten them into one Product table, such as a view`,explain:`Correct. Denormalize the snowflake into one table so the hierarchy can use its columns.`}],answer:`d`},{id:`WF-07`,machineId:W,bulletIds:[`S1.3`],format:`single`,difficulty:2,placement:!0,stem:`A bank model has Customer and Account dimension tables. A customer can hold many accounts, and joint accounts have several customers. Transactions relate to Account. How should you model Customer and Account?`,sources:[t.manyToMany],options:[{id:`a`,text:`Add a bridging table of customer-account pairs`,explain:`Correct. Learn: add a bridging table and set the filter direction so Customer filters reach the Transaction table.`},{id:`b`,text:`Relate Customer to Account directly with a many-to-many relationship`,explain:`Learn doesn’t recommend relating many-to-many dimension tables directly.`},{id:`c`,text:`Merge Customer and Account into one table in Power Query`,explain:`Merging duplicates rows per pair and breaks both dimensions’ keys.`},{id:`d`,text:`Relate Customer directly to the Transaction table`,explain:`Transactions belong to accounts, not customers, so there’s no customer key to relate on.`}],answer:`a`},{id:`WF-08`,machineId:W,bulletIds:[`S1.3`],format:`order`,difficulty:2,placement:!0,stem:`You are implementing a many-to-many relationship between Customer and Account by using the bridging pattern. Put the steps in order.`,sources:[t.manyToMany],items:[{id:`i3`,text:`Set the cross-filter direction of the Account-to-bridge relationship to Both`,explain:`Third. Filters from Customer must flow back through the bridge to Account and on to the facts.`},{id:`i1`,text:`Add the bridging table that stores one row per customer-account pair`,explain:`First. The bridge holds the associations the two dimensions share.`},{id:`i2`,text:`Create one-to-many relationships from Customer and from Account to the bridge`,explain:`Second. Each dimension’s unique ID is the one side.`}],answerOrder:[`i1`,`i2`,`i3`]},{id:`WF-09`,machineId:W,bulletIds:[`S1.3`],format:`single`,difficulty:3,placement:!0,stem:`A Target table stores sales targets by month and product category. Product has one row per product, so Category repeats in both Product and Target. How should you relate Target to Product?`,sources:[t.manyToMany],options:[{id:`a`,text:`One-to-many from Product[Category] to Target[Category]`,explain:`Product[Category] has duplicate values, so it can’t be the one side.`},{id:`b`,text:`Many-to-many on Category, single direction from Product`,explain:`Correct. Learn: with no one side, use many-to-many that propagates filters from the dimension to the fact.`},{id:`c`,text:`Many-to-many on Category with cross-filter direction Both`,explain:`Learn says the relationship should filter in a single direction, from dimension to fact.`},{id:`d`,text:`No relationship; use TREATAS in every target measure`,explain:`Learn’s recommended design for this case is a many-to-many relationship that filters from the dimension to the fact.`}],answer:`b`},{id:`WF-10`,machineId:W,bulletIds:[`S1.3`],format:`single`,difficulty:2,placement:!0,trapPairId:`regular-vs-limited`,stem:`A composite model relates an Import Product table to a DirectQuery Sales table from a different source group. A calculated column on Sales uses RELATED(Product[Category]) and fails. Why?`,sources:[t.relationships],options:[{id:`a`,text:`RELATED only works in measures, not calculated columns`,explain:`RELATED is designed for row context, such as calculated columns.`},{id:`b`,text:`The relationship needs cross-filter direction Both`,explain:`Direction isn’t the issue; the relationship type is.`},{id:`c`,text:`Product[Category] must be the key column of the relationship`,explain:`RELATED can return any column from the one side of a regular relationship.`},{id:`d`,text:`The relationship is limited, so RELATED can’t use it`,explain:`Correct. Cross source group relationships are limited, and the RELATED function can’t be used across them.`}],answer:`d`},{id:`WF-11`,machineId:W,bulletIds:[`S1.3`],format:`yesno`,difficulty:3,placement:!0,trapPairId:`regular-vs-limited`,stem:`You are reviewing relationships in a composite semantic model. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.relationships],statements:[{id:`s1`,text:`A relationship with many-to-many cardinality is a limited relationship.`,answer:!0,explain:`Yes. A relationship is limited when it is many-to-many or crosses source groups.`},{id:`s2`,text:`For a limited relationship, a blank virtual row is added to the one side for unmatched keys.`,answer:!1,explain:`No. Limited relationships use INNER JOIN semantics, so no blank row is added and unmatched rows drop out.`},{id:`s3`,text:`A one-to-many relationship between an Import table and a DirectQuery table from another source is limited.`,answer:!0,explain:`Yes. It crosses source groups, so it’s limited. (Dual storage mode is only available when the Import and DirectQuery tables come from the same source.)`}]},{id:`WF-12`,machineId:W,bulletIds:[`S1.3`],format:`single`,difficulty:2,placement:!0,stem:`Order and Fulfillment fact tables share an OrderID column with duplicate values in both. A developer related them directly with many-to-many cardinality. What does Learn recommend instead?`,sources:[t.manyToMany],options:[{id:`a`,text:`Set the relationship’s cross-filter direction to Both`,explain:`The design problem remains: visuals can still only filter by OrderID.`},{id:`b`,text:`Merge both fact tables into one wide table`,explain:`Learn recommends a star schema, not merging facts of different grains.`},{id:`c`,text:`Relate both facts to shared dimension tables`,explain:`Correct. A star schema lets visuals filter or group by any dimension column and summarize either fact.`},{id:`d`,text:`Turn on Assume referential integrity for the relationship`,explain:`That property applies to one-to-many relationships between DirectQuery tables in the same source group.`}],answer:`c`},{id:`WF-13`,machineId:W,bulletIds:[`S1.3`],format:`single`,difficulty:3,placement:!0,stem:`In a bank model with a customer-account bridging table, a matrix shows each customer’s balance. The grand total is lower than the sum of the customer rows. What explains this?`,sources:[t.manyToMany],options:[{id:`a`,text:`The bridge relationship should be set to single direction`,explain:`Single direction would stop customer filters from reaching the facts at all.`},{id:`b`,text:`Values through the bridge aren’t additive`,explain:`Correct. A joint account’s balance appears under each customer, but only once in the total.`},{id:`c`,text:`Limited relationships drop rows from the grand total only`,explain:`The total is right; it’s the customer rows that each include shared balances.`},{id:`d`,text:`The model needs an Unknown customer member`,explain:`There are no unmatched keys here; the difference comes from shared accounts.`}],answer:`b`},{id:`PC-01`,machineId:G,bulletIds:[`S1.4`],format:`dropdown`,difficulty:2,placement:!0,stem:`You are rewriting a year-over-year growth measure so the prior-year value is calculated once and reused. Complete the DAX.`,sources:[t.varBP,t.bpDivide],language:`dax`,code:`Sales YoY Growth % =
[[1]] SalesPriorYear =
    CALCULATE([Sales], PARALLELPERIOD('Date'[Date], -12, MONTH))
[[2]]
    [[3]]([Sales] - SalesPriorYear, SalesPriorYear)`,slots:[{id:`1`,options:[{id:`a`,text:`DEFINE`,explain:`DEFINE starts the definitions block of a DAX query, not a variable inside a measure.`},{id:`b`,text:`VAR`,explain:`Correct. VAR stores the prior-year result in a named variable.`},{id:`c`,text:`MEASURE`,explain:`MEASURE belongs in a query’s DEFINE block.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`RETURN`,explain:`Correct. RETURN gives the result expression that uses the variable.`},{id:`b`,text:`EVALUATE`,explain:`EVALUATE runs a DAX query; measures use RETURN.`},{id:`c`,text:`THEN`,explain:`THEN isn’t a DAX keyword.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`FORMAT`,explain:`FORMAT would turn the result into text.`},{id:`b`,text:`SUMX`,explain:`SUMX needs a table to iterate.`},{id:`c`,text:`DIVIDE`,explain:`Correct. DIVIDE handles a zero or blank denominator safely.`}],answer:`c`}]},{id:`PC-02`,machineId:G,bulletIds:[`S1.4`],format:`single`,difficulty:3,placement:!0,stem:`A measure is defined as VAR AllSales = [Sales] RETURN CALCULATE(AllSales, 'Product'[Color] = "Red"). In a visual with no other filters, what does it return?`,sources:[t.varBP,t.varRef],options:[{id:`a`,text:`Sales of red products only`,explain:`The variable was already evaluated before CALCULATE applied the Red filter.`},{id:`b`,text:`Total sales, unaffected by the Red filter`,explain:`Correct. Variables are always evaluated outside the filters the RETURN expression applies.`},{id:`c`,text:`BLANK, because variables can’t be used inside CALCULATE`,explain:`Variables can be used in CALCULATE; they just don’t respond to its filters.`},{id:`d`,text:`An error, because a variable can’t hold a measure`,explain:`A variable can store any scalar or table expression, including a measure.`}],answer:`b`},{id:`PC-03`,machineId:G,bulletIds:[`S1.4`],format:`single`,difficulty:1,placement:!0,stem:`The Sales table has Quantity and UnitPrice columns but no amount column. You need a measure that returns the total revenue. Which expression should you use?`,sources:[t.sumx],options:[{id:`a`,text:`SUM(Sales[Quantity]) * SUM(Sales[UnitPrice])`,explain:`Multiplying two totals isn’t the same as summing each row’s product.`},{id:`b`,text:`SUMX(Sales, Sales[Quantity] * Sales[UnitPrice])`,explain:`Correct. SUMX evaluates the expression for each row and then sums the results.`},{id:`c`,text:`SUM(Sales[Quantity] * Sales[UnitPrice])`,explain:`SUM takes a single column, not an expression.`},{id:`d`,text:`CALCULATE(SUM(Sales[Quantity]), Sales[UnitPrice])`,explain:`This sums Quantity only; it never multiplies by price, so it isn’t a sales amount.`}],answer:`b`},{id:`PC-04`,machineId:G,bulletIds:[`S1.4`],format:`single`,difficulty:3,placement:!0,stem:`You need a running total of [Total Sales] by month that restarts each fiscal year. Rows are ALLSELECTED('Date'[Fiscal Year], 'Date'[Month Number Of Year]). Which WINDOW arguments define the window?`,sources:[t.window],options:[{id:`a`,text:`WINDOW(0, REL, 1, ABS, <rows>, PARTITIONBY('Date'[Fiscal Year]))`,explain:`This starts at the current row and ends at the first row, which reverses the window.`},{id:`b`,text:`WINDOW(1, ABS, -1, ABS, <rows>, PARTITIONBY('Date'[Fiscal Year]))`,explain:`This covers the whole year for every month, so it returns a full-year total, not a running total.`},{id:`c`,text:`WINDOW(1, ABS, 0, REL, <rows>, PARTITIONBY('Date'[Fiscal Year]))`,explain:`Correct. The window starts at the first row of the partition (1, ABS) and ends at the current row (0, REL), restarting each fiscal year.`},{id:`d`,text:`WINDOW(1, ABS, 0, REL, <rows>, PARTITIONBY('Date'[Month Number Of Year]))`,explain:`Partitioning by month groups each month across fiscal years, so it accumulates the same month across years instead of restarting each fiscal year.`}],answer:`c`},{id:`PC-05`,machineId:G,bulletIds:[`S1.4`],format:`single`,difficulty:2,placement:!0,stem:`You need a measure that returns the previous calendar year’s sales next to each year in a table visual, by using a window function. Which function should you use?`,sources:[t.offset],options:[{id:`a`,text:`INDEX(1, …, ORDERBY(DimDate[CalendarYear]))`,explain:`INDEX returns the row at an absolute position, such as the first year, not the prior one.`},{id:`b`,text:`WINDOW(1, ABS, 0, REL, …)`,explain:`This returns all years up to the current one, which gives a running total.`},{id:`c`,text:`RANK(…, ORDERBY(DimDate[CalendarYear]))`,explain:`RANK returns a position number, not another row’s value.`},{id:`d`,text:`OFFSET(-1, …, ORDERBY(DimDate[CalendarYear]))`,explain:`Correct. OFFSET returns the row a given distance from the current row; -1 is the previous year.`}],answer:`d`},{id:`PC-06`,machineId:G,bulletIds:[`S1.4`],format:`single`,difficulty:2,placement:!0,trapPairId:`hasonevalue-vs-isinscope`,stem:`A matrix shows Category > Product. You need a measure that returns one calculation on product rows and a different one on category subtotals. Which function should you test?`,sources:[t.isinscope,t.hasonevalue],options:[{id:`a`,text:`HASONEVALUE('Product'[Product])`,explain:`HASONEVALUE is also TRUE when a slicer filters to one product, even at the subtotal level.`},{id:`b`,text:`ISFILTERED('Product'[Product])`,explain:`ISFILTERED reports any filter on the column, including slicers, not the grouping level.`},{id:`c`,text:`ISINSCOPE('Product'[Product])`,explain:`Correct. ISINSCOPE is TRUE when the visual is grouping by that column at the current level.`},{id:`d`,text:`SELECTEDVALUE('Product'[Product])`,explain:`SELECTEDVALUE returns a value, and it also returns one under a single-product slicer.`}],answer:`c`},{id:`PC-07`,machineId:G,bulletIds:[`S1.4`],format:`single`,difficulty:2,placement:!0,trapPairId:`hasonevalue-vs-isinscope`,stem:`A card must show the region chosen in a slicer, or the text Multiple when more than one region (or none) is selected. Which expression should you use?`,sources:[t.selectedvalue],options:[{id:`a`,text:`SELECTEDVALUE('Geo'[Region], "Multiple")`,explain:`Correct. SELECTEDVALUE returns the single value in context, or the alternate result otherwise.`},{id:`b`,text:`VALUES('Geo'[Region])`,explain:`This doesn’t give the fallback text Learn’s SELECTEDVALUE pattern provides when several regions are selected.`},{id:`c`,text:`ISINSCOPE('Geo'[Region])`,explain:`ISINSCOPE returns TRUE or FALSE about grouping, not the selected value.`},{id:`d`,text:`FIRSTNONBLANK('Geo'[Region], "Multiple")`,explain:`This doesn’t show a fallback when several regions are selected; SELECTEDVALUE returns the alternate result in that case.`}],answer:`a`},{id:`PC-08`,machineId:G,bulletIds:[`S1.4`],format:`match`,difficulty:1,placement:!0,stem:`The DP-600 skills outline names several families of DAX functions. Match each function to its family.`,sources:[t.sumx,t.window,t.infoFuncs,t.filterFuncs],prompts:[{id:`p1`,text:`SUMX`},{id:`p2`,text:`OFFSET`},{id:`p3`,text:`ISINSCOPE`},{id:`p4`,text:`REMOVEFILTERS`}],choices:[{id:`c1`,text:`Iterator`},{id:`c2`,text:`Windowing`},{id:`c3`,text:`Information function`},{id:`c4`,text:`Table filtering (CALCULATE filter modifier)`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`SUMX evaluates an expression for each row of a table, then sums.`},{promptId:`p2`,choiceId:`c2`,explain:`OFFSET returns a row relative to the current row, using ORDERBY and PARTITIONBY.`},{promptId:`p3`,choiceId:`c3`,explain:`ISINSCOPE tests the evaluation context.`},{promptId:`p4`,choiceId:`c4`,explain:`REMOVEFILTERS clears filters, typically as a CALCULATE modifier.`}]},{id:`PC-09`,machineId:G,bulletIds:[`S1.4`],format:`yesno`,difficulty:2,placement:!0,stem:`You are reviewing DAX measures that use variables. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.varRef,t.varBP],statements:[{id:`s1`,text:`A measure can reference a variable that was defined in a different measure.`,answer:!1,explain:`No. Measures can’t refer to variables defined outside the measure expression.`},{id:`s2`,text:`If a variable stores a table, you can read its columns with VariableName[Column] syntax.`,answer:!1,explain:`No. You can’t reference columns in table variables by using TableName[ColumnName] syntax.`},{id:`s3`,text:`Using a variable can remove the need for the EARLIER or EARLIEST functions.`,answer:!0,explain:`Yes. Because variables are evaluated outside the RETURN filters, EARLIER and EARLIEST can be avoided.`}]},{id:`PC-10`,machineId:G,bulletIds:[`S1.4`],format:`single`,difficulty:2,stem:`You need a measure that shows each product’s sales as a percentage of sales for all products, regardless of any product filter in the visual. Which denominator should you use?`,sources:[t.calculate,t.filterFuncs],options:[{id:`a`,text:`CALCULATE([Sales], KEEPFILTERS('Product'))`,explain:`KEEPFILTERS adds to existing filters; it doesn’t remove the product filter.`},{id:`b`,text:`CALCULATE([Sales], REMOVEFILTERS('Product'))`,explain:`Correct. REMOVEFILTERS clears the product filters so the denominator is all products.`},{id:`c`,text:`SUMX('Product', [Sales])`,explain:`This iterates only the products in the current filter context.`},{id:`d`,text:`CALCULATE([Sales], VALUES('Product'[Product]))`,explain:`VALUES keeps the current product selection as the filter.`}],answer:`b`},{id:`JH-01`,machineId:K,bulletIds:[`S1.5`],format:`single`,difficulty:1,placement:!0,trapPairId:`calcgroup-vs-fieldparam`,stem:`A model has 30 base measures. The business wants YTD, prior year, and YoY% versions of every one, without creating 90 more measures. What should you implement?`,sources:[t.calcGroups],options:[{id:`a`,text:`A field parameter listing the 30 measures`,explain:`A field parameter lets readers switch fields; it doesn’t change how measures calculate.`},{id:`b`,text:`A dynamic format string on each measure`,explain:`Format strings change display formatting, not the calculation.`},{id:`c`,text:`A calculation group`,explain:`Correct. Calculation items apply their logic to whatever measure is in context.`},{id:`d`,text:`A disconnected table with three rows`,explain:`A disconnected table alone would still need logic in every measure.`}],answer:`c`},{id:`JH-02`,machineId:K,bulletIds:[`S1.5`],format:`single`,difficulty:1,placement:!0,trapPairId:`calcgroup-vs-fieldparam`,stem:`Report readers want to choose with a slicer whether a line chart shows Sales, Profit, or Margin, without bookmarks or duplicate visuals. What should you create?`,sources:[t.fieldParams],options:[{id:`a`,text:`A calculation group with one item per measure`,explain:`Calculation groups change how the selected measure is calculated, not which field a visual shows.`},{id:`b`,text:`A field parameter containing the three measures`,explain:`Correct. Field parameters let readers switch the measures or columns a visual uses.`},{id:`c`,text:`A dynamic format string that returns the measure name`,explain:`A format string only changes how a value is displayed.`},{id:`d`,text:`A what-if parameter with values 1 to 3`,explain:`What-if parameters supply numeric input values, not field choices.`}],answer:`b`},{id:`JH-03`,machineId:K,bulletIds:[`S1.5`],format:`single`,difficulty:2,placement:!0,trapPairId:`dfs-vs-format`,stem:`A sales measure must display in each country’s currency format. It is also used in a line chart. A developer used FORMAT() and the chart stopped plotting. What should you use instead?`,sources:[t.dynamicFormat],options:[{id:`a`,text:`A dynamic format string for the measure`,explain:`Correct. The measure keeps its numeric data type while the format changes by context.`},{id:`b`,text:`A calculated column that stores the formatted text`,explain:`Text values still can’t be plotted as numbers.`},{id:`c`,text:`CONVERT() around the FORMAT() result`,explain:`Converting formatted text back to a number loses the currency format.`},{id:`d`,text:`A separate measure per country`,explain:`This multiplies measures and still doesn’t switch format by context in one visual.`}],answer:`a`},{id:`JH-04`,machineId:K,bulletIds:[`S1.5`],format:`dropdown`,difficulty:2,placement:!0,stem:`A calculation group named 'Time Intelligence' has a column [Time Calculation] with a YOY% item. You need an [Orders YOY%] measure that applies that item to [Orders]. Complete the DAX.`,sources:[t.calcGroups],language:`dax`,code:`Orders YOY% =
[[1]](
    [[2]],
    'Time Intelligence'[Time Calculation] = [[3]]
)`,slots:[{id:`1`,options:[{id:`a`,text:`SELECTEDMEASURE`,explain:`SELECTEDMEASURE is used inside calculation items; it takes no arguments.`},{id:`b`,text:`CALCULATE`,explain:`Correct. CALCULATE evaluates the measure with the calculation item as a filter.`},{id:`c`,text:`SWITCH`,explain:`SWITCH chooses between values; it doesn’t apply a calculation item.`}],answer:`b`},{id:`2`,options:[{id:`a`,text:`[Orders]`,explain:`Correct. The measure the calculation item should modify.`},{id:`b`,text:`SELECTEDMEASURE()`,explain:`In a regular measure there’s no selected measure to refer to.`},{id:`c`,text:`'Time Intelligence'`,explain:`The calculation group is the filter, not the expression.`}],answer:`a`},{id:`3`,options:[{id:`a`,text:`[YOY%]`,explain:`Square brackets reference a measure, not a text value.`},{id:`b`,text:`SELECTEDVALUE()`,explain:`This returns a value from context rather than naming the item.`},{id:`c`,text:`"YOY%"`,explain:`Correct. Filter the calculation group column to the item’s name as text.`}],answer:`c`}]},{id:`JH-05`,machineId:K,bulletIds:[`S1.5`],format:`single`,difficulty:3,placement:!0,stem:`After you add a calculation group to a semantic model, a report developer notices that every measure now shows a different data type in reports. What happened, and how is it reversed?`,sources:[t.calcGroups],options:[{id:`a`,text:`Measures became text; set each measure’s format back to Number`,explain:`They change to variant, not text, and changing formats doesn’t reverse it.`},{id:`b`,text:`Measures became variant; they revert only if all calculation groups are removed`,explain:`Correct. Learn: reports use variant for all measures once a calculation group exists, and revert when all calculation groups are removed.`},{id:`c`,text:`Measures became decimal; turn off Discourage implicit measures`,explain:`The property must stay on for calculation groups, and the type change is to variant.`},{id:`d`,text:`Only measures used in calculation items changed; recreate those measures`,explain:`All measures change, not just the ones the items touch.`}],answer:`b`},{id:`JH-06`,machineId:K,bulletIds:[`S1.5`],format:`multi`,difficulty:2,placement:!0,stem:`You plan to use a field parameter in a report. Which two limitations apply? Choose two.`,sources:[t.fieldParams],options:[{id:`a`,text:`AI visuals and Q&A aren’t supported with field parameters`,explain:`Correct. Learn lists this limitation.`},{id:`b`,text:`A field parameter can’t be placed on a slicer`,explain:`Using the field parameter on a slicer is how readers choose fields.`},{id:`c`,text:`A field parameter can contain measures or columns, never both`,explain:`Learn’s guidance doesn’t restrict a parameter to one kind of field.`},{id:`d`,text:`A field parameter can’t include implicit measures`,explain:`Correct. Create explicit measures for aggregated columns you want to include.`}],answers:[`a`,`d`]},{id:`JH-07`,machineId:K,bulletIds:[`S1.5`],format:`yesno`,difficulty:2,placement:!0,trapPairId:`dfs-vs-format`,stem:`You are adding format strings to a semantic model. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.dynamicFormat,t.calcGroups],statements:[{id:`s1`,text:`A calculation item can have its own dynamic format string, for example to show YOY% as a percentage.`,answer:!0,explain:`Yes. Turn on Dynamic format string for the calculation item and return a format such as #,##0.00%.`},{id:`s2`,text:`A measure that uses a dynamic format string keeps its numeric data type.`,answer:!0,explain:`Yes. Unlike FORMAT(), a dynamic format string doesn’t change the measure to text.`},{id:`s3`,text:`FORMAT() is the recommended way to format a measure used in charts, because it keeps numbers numeric.`,answer:!1,explain:`No. FORMAT returns all results as strings, which causes problems for charts that need numbers.`}]},{id:`JH-08`,machineId:K,bulletIds:[`S1.5`],format:`single`,difficulty:2,placement:!0,stem:`A model has a Time Intelligence calculation group and a Currency Conversion calculation group. Both apply to the same measure, and results differ depending on which applies first. Which setting controls the order?`,sources:[t.calcGroups],options:[{id:`a`,text:`The order of the calculation items in each group`,explain:`Item order controls how items are listed, not the order the groups apply.`},{id:`b`,text:`The Sort by column on each group’s column`,explain:`Sort by column affects display order in visuals.`},{id:`c`,text:`The calculation group precedence property`,explain:`Correct. Precedence specifies the order in which calculation groups apply to a measure.`},{id:`d`,text:`The measure’s dynamic format string`,explain:`Format strings don’t change how calculation groups combine.`}],answer:`c`},{id:`JH-09`,machineId:K,bulletIds:[`S1.5`],format:`single`,difficulty:1,placement:!0,stem:`In Power BI Desktop, you want to add a dynamic format string to an existing measure. What should you do first?`,sources:[t.dynamicFormat],options:[{id:`a`,text:`Create a calculation group and add the measure to it`,explain:`Measures can have their own dynamic format strings without a calculation group.`},{id:`b`,text:`Wrap the measure’s expression in FORMAT()`,explain:`FORMAT returns text; dynamic format strings are set separately.`},{id:`c`,text:`Open TMDL view and add a formatString property`,explain:`The documented path starts from Measure tools in the ribbon.`},{id:`d`,text:`Choose Dynamic in the measure’s Format list`,explain:`Correct. A drop-down then switches the formula bar to the format string DAX expression.`}],answer:`d`},{id:`JH-10`,machineId:K,bulletIds:[`S1.5`],format:`single`,difficulty:2,placement:!0,stem:`You are writing a field parameter table by hand in DAX. Each row lists a display name, a field reference, and a sort order. Which function should provide the field reference?`,sources:[t.fieldParams],options:[{id:`a`,text:`NAMEOF`,explain:`Correct. Learn’s field parameter definition uses NAMEOF('Product'[Category]) for each field.`},{id:`b`,text:`SELECTEDMEASURE`,explain:`SELECTEDMEASURE belongs in calculation items.`},{id:`c`,text:`RELATED`,explain:`RELATED returns a value from the one side of a relationship.`},{id:`d`,text:`VALUES`,explain:`VALUES returns the distinct values of a column, not a reference to the column.`}],answer:`a`}],q=`wide-beam`,J=`double-loom`,Y=`speed-governor`,X=`direct-lake-shuttle`,Z=`batch-winder`,ye=[{id:`WB-01`,machineId:q,bulletIds:[`S1.6`],format:`single`,difficulty:1,stem:`An Import semantic model on a Fabric F64 capacity is expected to grow to 25 GB through incremental refresh. Refreshes will fail once the model passes the default size limit. What should you configure?`,sources:[t.largeModels],options:[{id:`a`,text:`Large semantic model storage format`,explain:`Correct. It’s required for models to grow beyond 10 GB and lifts the default 1 GB limit up to the capacity limit.`},{id:`b`,text:`Switch the model to Dual storage mode`,explain:`Dual is a per-table storage mode; it doesn’t change the model size limit.`},{id:`c`,text:`Turn on query caching for the model`,explain:`Query caching speeds up repeated queries; it doesn’t raise the size limit.`},{id:`d`,text:`Move the model to a Pro workspace on shared capacity`,explain:`Shared capacity has lower limits and doesn’t support the large format.`}],answer:`a`},{id:`WB-02`,machineId:q,bulletIds:[`S1.6`],format:`single`,difficulty:2,stem:`A 300 MB semantic model is deployed and updated by a CI/CD tool through the XMLA endpoint. The team wants better XMLA write performance. What does Learn recommend?`,sources:[t.largeModels],options:[{id:`a`,text:`Leave the default format, because the model is under 1 GB`,explain:`Learn recommends the large format for XMLA write operations even for models you wouldn’t call large.`},{id:`b`,text:`Publish the model from Power BI Desktop instead of XMLA`,explain:`Publishing from Desktop doesn’t improve XMLA write performance.`},{id:`c`,text:`Enable the large storage format anyway`,explain:`Correct. The large storage format can improve XMLA write performance.`},{id:`d`,text:`Turn on the read-only XMLA endpoint for the capacity`,explain:`A read-only endpoint blocks the write operations the tool needs.`}],answer:`c`},{id:`WB-03`,machineId:q,bulletIds:[`S1.6`],format:`yesno`,difficulty:2,stem:`You are planning to use Large semantic model storage format. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.largeModels],statements:[{id:`s1`,text:`With the large format enabled, you can publish a 15 GB model directly from Power BI Desktop.`,answer:!1,explain:`No. The Desktop upload size is still limited to 10 GB; the model grows larger through refresh in the service.`},{id:`s2`,text:`On-demand load is enabled by default for large semantic models.`,answer:!0,explain:`Yes. It loads only the data pages a query needs and speeds up loading evicted models.`},{id:`s3`,text:`The large format can be enabled for models in Premium Per User (PPU) workspaces.`,answer:!0,explain:`Yes. Learn lists F SKUs, P SKUs, A SKUs, PPU, and Pro workspaces on Reserved Capacity for Pro Workspaces.`}]},{id:`WB-04`,machineId:q,bulletIds:[`S1.6`],format:`single`,difficulty:1,stem:`You want every new semantic model published to a Fabric capacity workspace to use the large storage format automatically. Where do you set this?`,sources:[t.largeModels],options:[{id:`a`,text:`In each report’s settings, under Query caching`,explain:`Report settings don’t control model storage format.`},{id:`b`,text:`In the workspace settings, under Default storage format`,explain:`Correct. Set Default storage format to Large semantic model storage format.`},{id:`c`,text:`In Power BI Desktop options, under Data load`,explain:`Desktop options don’t set the service storage format.`},{id:`d`,text:`In the lakehouse settings, under Delta table maintenance`,explain:`Delta maintenance affects tables in OneLake, not semantic model storage.`}],answer:`b`},{id:`WB-05`,machineId:q,bulletIds:[`S1.6`],format:`single`,difficulty:2,stem:`Learn lists several capacities and licenses that support Large semantic model storage format. Which of these environments does NOT support it?`,sources:[t.largeModels],options:[{id:`a`,text:`A workspace on a Fabric F SKU capacity`,explain:`Fabric F SKUs support the large format.`},{id:`b`,text:`A Premium Per User (PPU) workspace`,explain:`PPU supports the large format.`},{id:`c`,text:`A workspace on an Embedded A SKU capacity`,explain:`Embedded A SKUs support the large format.`},{id:`d`,text:`A Pro workspace on shared capacity, not assigned to Reserved Capacity for Pro Workspaces`,explain:`Correct. Only Pro workspaces assigned to Reserved Capacity for Pro Workspaces are listed; a Pro workspace on shared capacity isn’t.`}],answer:`d`},{id:`WB-06`,machineId:q,bulletIds:[`S1.6`],format:`single`,difficulty:3,stem:`A team plans a 40 GB model. One architect proposes Direct Lake on a lakehouse; another proposes Import with the large storage format. Which statement about size limits is correct?`,sources:[t.largeModels,t.directLake],options:[{id:`a`,text:`Both are limited only by the 1 GB default size limit`,explain:`The large format lifts the 1 GB default, and Direct Lake is governed by capacity guardrails.`},{id:`b`,text:`Direct Lake needs the large storage format setting to pass 10 GB`,explain:`The large format setting lifts the in-memory model size limit; Direct Lake depends on its own SKU guardrails.`},{id:`c`,text:`Import uses the large format limit; Direct Lake uses guardrails`,explain:`Correct. Large format lets Import models grow to the capacity limit, while Direct Lake depends on SKU guardrails and only loads the columns queries need.`},{id:`d`,text:`Import models can’t exceed 10 GB on any capacity`,explain:`With the large format, Import models can grow beyond 10 GB through refresh in the service.`}],answer:`c`},{id:`WB-07`,machineId:q,bulletIds:[`S1.6`],format:`single`,difficulty:2,stem:`An admin wants to enable Large semantic model storage format for one existing model without opening the service UI, by using PowerShell. Which setting does the cmdlet change?`,sources:[t.largeModels],options:[{id:`a`,text:`Set-PowerBIDataset with -TargetStorageMode PremiumFiles`,explain:`Correct. Learn: Set-PowerBIDataset -TargetStorageMode PremiumFiles enables the large format.`},{id:`b`,text:`Set-PowerBIWorkspace with -Capacity F64`,explain:`Assigning a capacity doesn’t change a model’s storage format.`},{id:`c`,text:`Set-PowerBIDataset with -StorageMode DirectLake`,explain:`Storage mode is a per-table property, not the large storage format.`},{id:`d`,text:`Invoke-PowerBIRestMethod with a refresh request`,explain:`A refresh doesn’t change the storage format.`}],answer:`a`},{id:`DL-01`,machineId:J,bulletIds:[`S1.7`],format:`single`,difficulty:2,stem:`An analyst is live-connected to a certified Sales semantic model in Power BI Desktop. They need to add a Targets Excel sheet and relate it to the model. What should they do?`,sources:[t.composite],options:[{id:`a`,text:`Download the Sales model as a .pbix and add the sheet`,explain:`This creates a disconnected copy instead of extending the shared model.`},{id:`b`,text:`Select Make changes to this model, then add the sheet`,explain:`Correct. This converts the live connection to DirectQuery and creates a local composite model.`},{id:`c`,text:`Ask the model owner to switch the Sales model to Dual`,explain:`Dual is a table storage mode; it doesn’t let a report author add tables.`},{id:`d`,text:`Use a field parameter to bring in the Targets sheet`,explain:`Field parameters switch fields in a visual; they don’t add data sources.`}],answer:`b`},{id:`DL-02`,machineId:J,bulletIds:[`S1.7`],format:`single`,difficulty:2,trapPairId:`regular-vs-limited`,stem:`A composite model has Import dimension tables and a DirectQuery Sales fact table. Queries that filter Sales by dimension attributes are slow. Which change helps the engine send one efficient native query?`,sources:[t.storageMode],options:[{id:`a`,text:`Set the dimension tables to Dual storage mode`,explain:`Correct. Dual dimensions keep relationships with DirectQuery facts regular and let JOIN logic be pushed to the source.`},{id:`b`,text:`Set the Sales table to Import with a one-day refresh`,explain:`That gives up the DirectQuery freshness the design was chosen for.`},{id:`c`,text:`Set every relationship to cross-filter direction Both`,explain:`Bi-directional filtering adds work and doesn’t fix limited relationships.`},{id:`d`,text:`Add a calculated table that copies the Sales table`,explain:`A calculated table uses Import storage and duplicates the fact data.`}],answer:`a`},{id:`DL-03`,machineId:J,bulletIds:[`S1.7`],format:`single`,difficulty:1,trapPairId:`dual-vs-hybrid`,stem:`A FactSales table must serve history from Import partitions and the most recent rows in real time through DirectQuery, in one table. What kind of table is this?`,sources:[t.incremental,t.composite,t.modes],options:[{id:`a`,text:`A Dual table`,explain:`A Dual table is served from cache or DirectQuery per query, not split into partitions by date.`},{id:`b`,text:`A calculated table`,explain:`A calculated table is defined by DAX and stored as Import.`},{id:`c`,text:`A hybrid table`,explain:`Correct. A hybrid table has Import partitions plus a DirectQuery partition for the latest data, created by an incremental refresh policy.`},{id:`d`,text:`A bridging table`,explain:`A bridging table resolves many-to-many relationships.`}],answer:`c`},{id:`DL-04`,machineId:J,bulletIds:[`S1.7`],format:`yesno`,difficulty:2,stem:`You are designing a composite model. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.composite,t.relationships],statements:[{id:`s1`,text:`All Import tables in a model belong to the same source group.`,answer:!0,explain:`Yes. A source group is the items from one DirectQuery source, or all Import sources involved in the model.`},{id:`s2`,text:`A relationship between tables in different source groups is always regular.`,answer:!1,explain:`No. Relationships that cross source groups are limited relationships.`},{id:`s3`,text:`A calculated table can reference both Import and DirectQuery tables.`,answer:!0,explain:`Yes. The DAX that defines a calculated table can reference imported or DirectQuery tables, or both.`}]},{id:`DL-05`,machineId:J,bulletIds:[`S1.7`],format:`single`,difficulty:3,stem:`You create a composite model that combines a confidential SQL Server source with a product list in an Excel file. Power BI shows a security warning. What risk does the warning describe?`,sources:[t.composite],options:[{id:`a`,text:`Users of the report bypass RLS defined on the SQL Server source`,explain:`The warning is about data moving between sources, not RLS.`},{id:`b`,text:`Values from one source can be included in queries sent to the other source`,explain:`Correct. Learn: data from one source can be sent inside queries to another, so check whether that data movement is acceptable.`},{id:`c`,text:`The Excel file will be uploaded to OneLake as a Delta table`,explain:`Composite models don’t convert sources into Delta tables.`},{id:`d`,text:`The SQL Server data will be imported into the model at every refresh`,explain:`DirectQuery tables aren’t imported, and that isn’t the warning.`}],answer:`b`},{id:`DL-06`,machineId:J,bulletIds:[`S1.7`],format:`single`,difficulty:3,trapPairId:`dl-onelake-vs-sql`,stem:`You need one semantic model that combines Direct Lake tables from a lakehouse with an Import table from an external Excel source. Which Direct Lake option allows this?`,sources:[t.directLake],options:[{id:`a`,text:`Direct Lake on SQL analytics endpoints, by mixing modes in the model`,explain:`Direct Lake on SQL can’t be mixed with other storage modes in the same model.`},{id:`b`,text:`Neither; Direct Lake tables can never share a model with Import tables`,explain:`Direct Lake on OneLake models can have Import tables added.`},{id:`c`,text:`Direct Lake on OneLake, adding the Import table to the model`,explain:`Correct. Semantic models with Direct Lake on OneLake tables can also have Import tables from other sources.`},{id:`d`,text:`Either option, as long as the Excel file is stored in OneLake`,explain:`Where the file is stored doesn’t change Direct Lake on SQL’s restriction.`}],answer:`c`},{id:`DL-07`,machineId:J,bulletIds:[`S1.7`],format:`single`,difficulty:2,stem:`Model C is a composite model built on published model A. Model A has no RLS on its Customer table. A report on model C uses only C’s new tables. What can that report query?`,sources:[t.composite],options:[{id:`a`,text:`Only the tables added in model C`,explain:`A report on C can query tables in A that aren’t protected by RLS.`},{id:`b`,text:`Only the A tables that C’s visuals already use`,explain:`Learn says any table in A without RLS can be queried, not just used ones.`},{id:`c`,text:`Nothing in A until A’s owner grants Build to the report`,explain:`The point is what C’s reports can reach once C includes A’s tables.`},{id:`d`,text:`Any table in model A that isn’t protected by RLS`,explain:`Correct. Learn: a report on C can query any table in A that isn’t protected by RLS.`}],answer:`d`},{id:`DL-08`,machineId:J,bulletIds:[`S1.7`],format:`match`,difficulty:2,trapPairId:`dual-vs-hybrid`,stem:`Match each composite model term to its description.`,sources:[t.composite,t.storageMode,t.incremental],prompts:[{id:`p1`,text:`Source group`},{id:`p2`,text:`Dual table`},{id:`p3`,text:`Hybrid table`},{id:`p4`,text:`Chaining`}],choices:[{id:`c1`,text:`Items from one DirectQuery source, or all Import sources, in a model`},{id:`c2`,text:`A table served from cache or by DirectQuery, chosen per query`},{id:`c3`,text:`A table with Import partitions and a DirectQuery partition for the newest data`},{id:`c4`,text:`Building semantic models on top of other semantic models`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`This is Learn’s definition of a source group.`},{promptId:`p2`,choiceId:`c2`,explain:`Dual tables can act as Import or DirectQuery depending on the query.`},{promptId:`p3`,choiceId:`c3`,explain:`Hybrid tables come from incremental refresh with real-time DirectQuery.`},{promptId:`p4`,choiceId:`c4`,explain:`Models built on other models form a chain; Learn sets the maximum chain length at three.`}]},{id:`SG-01`,machineId:Y,bulletIds:[`S2.1`],format:`single`,difficulty:2,placement:!0,trapPairId:`dl-fallback`,stem:`In Performance Analyzer, a visual on a Direct Lake on SQL semantic model shows a Direct query duration line. What does this indicate?`,sources:[t.dlAnalyze],options:[{id:`a`,text:`The visual’s query fell back from Direct Lake to DirectQuery`,explain:`Correct. A Direct query line on a Direct Lake model means that visual’s query fell back.`},{id:`b`,text:`Columns were transcoded into memory for the first time`,explain:`Transcoding is Direct Lake loading; it isn’t reported as Direct query.`},{id:`c`,text:`The visual is using a field parameter`,explain:`Field parameters are reported under Evaluated parameters.`},{id:`d`,text:`The report is waiting for other visuals to complete`,explain:`Waiting on other visuals is part of Other.`}],answer:`a`},{id:`SG-02`,machineId:Y,bulletIds:[`S2.1`],format:`single`,difficulty:3,placement:!0,stem:`You trace a Direct Lake on SQL model with SQL Server Profiler to find fallback. You see DirectQuery events for an EngineEdition check query. What should you conclude?`,sources:[t.dlAnalyze],options:[{id:`a`,text:`The whole model has fallen back because of a guardrail`,explain:`Guardrail fallback shows on report queries; this system query always uses DirectQuery.`},{id:`b`,text:`This query always uses DirectQuery and doesn’t indicate fallback`,explain:`Correct. Learn: EngineEdition and OLS check queries always use DirectQuery and don’t mean fallback.`},{id:`c`,text:`The SQL analytics endpoint has RLS on the table`,explain:`RLS fallback would appear on report queries against that table.`},{id:`d`,text:`The model needs a manual refresh to reframe`,explain:`Reframing doesn’t change how this system query runs.`}],answer:`b`},{id:`SG-03`,machineId:Y,bulletIds:[`S2.1`],format:`single`,difficulty:1,trapPairId:`perf-categories`,stem:`In Performance Analyzer, a scatter chart with 30,000 points shows a fast DAX query time but a long Visual display time. What should you change?`,sources:[t.perfAnalyzer,t.optimization],options:[{id:`a`,text:`Rewrite the visual’s measures with variables`,explain:`The DAX query is already fast; the time goes into drawing the visual.`},{id:`b`,text:`Switch the model to Direct Lake`,explain:`Storage mode affects query time, not rendering time.`},{id:`c`,text:`Reduce the points the visual draws`,explain:`Correct. Visual display is time spent rendering, which you fix with report design.`},{id:`d`,text:`Add an index to the source table`,explain:`Source indexes affect query time, not drawing time.`}],answer:`c`},{id:`SG-04`,machineId:Y,bulletIds:[`S2.1`],format:`single`,difficulty:2,placement:!0,stem:`A report page has a table visual with no filters over a 400-million-row fact table, and it loads slowly. What does Learn suggest as a fix?`,sources:[t.optimization],options:[{id:`a`,text:`Turn on the large semantic model storage format`,explain:`The format raises size limits; it doesn’t limit rows in a visual.`},{id:`b`,text:`Set the fact table to Dual storage mode`,explain:`The visual would still try to load every row.`},{id:`c`,text:`Add a field parameter to the table visual`,explain:`Field parameters switch fields; they don’t reduce rows.`},{id:`d`,text:`Apply a Top N filter to limit the rows the table displays`,explain:`Correct. Learn: use the Top N filter to reduce the max number of items the table displays.`}],answer:`d`},{id:`SG-05`,machineId:Y,bulletIds:[`S2.1`],format:`multi`,difficulty:2,stem:`An Import model is larger than it needs to be. Which two changes does Learn recommend to reduce its size? Choose two.`,sources:[t.dataReduction],options:[{id:`a`,text:`Set every relationship to cross-filter direction Both`,explain:`Filter direction doesn’t reduce stored data.`},{id:`b`,text:`Remove columns that reports and the model don’t use`,explain:`Correct. Removing unnecessary columns is a key data reduction technique.`},{id:`c`,text:`Disable auto date/time in Power BI Desktop`,explain:`Correct. Auto date/time creates a hidden date table for each date column.`},{id:`d`,text:`Convert numeric columns to text`,explain:`Text uses hash encoding and generally compresses worse than numbers.`}],answers:[`b`,`c`]},{id:`SG-06`,machineId:Y,bulletIds:[`S2.1`],format:`match`,difficulty:2,placement:!0,trapPairId:`perf-categories`,stem:`Match each Performance Analyzer duration to what it measures.`,sources:[t.perfAnalyzer],prompts:[{id:`p1`,text:`DAX query`},{id:`p2`,text:`Direct query`},{id:`p3`,text:`Visual display`},{id:`p4`,text:`Other`}],choices:[{id:`c1`,text:`Time for the semantic model to produce the visual’s results`},{id:`c2`,text:`Time for the external source to answer a DirectQuery request`},{id:`c3`,text:`Time to draw the visual on screen`},{id:`c4`,text:`Time preparing queries and waiting for other visuals`}],pairs:[{promptId:`p1`,choiceId:`c1`,explain:`Fix slow DAX query time in the model or the DAX.`},{promptId:`p2`,choiceId:`c2`,explain:`On a Direct Lake model, this line also reveals fallback.`},{promptId:`p3`,choiceId:`c3`,explain:`Fix it with report design, such as fewer data points.`},{promptId:`p4`,choiceId:`c4`,explain:`Other covers preparing queries, waiting, and background processing.`}]},{id:`SG-07`,machineId:Y,bulletIds:[`S2.2`],format:`single`,difficulty:2,placement:!0,stem:`A measure is defined as CALCULATE([Sales], FILTER('Product', 'Product'[Color] = "Red")). It is slow on a large Product table. Which rewrite follows Learn’s guidance?`,sources:[t.bpFilter],options:[{id:`a`,text:`CALCULATE([Sales], FILTER(ALL('Product'), 'Product'[Color] = "Red"))`,explain:`This still iterates a whole table and also removes all Product filters.`},{id:`b`,text:`CALCULATE([Sales], KEEPFILTERS('Product'[Color] = "Red"))`,explain:`Correct. A Boolean filter on one column is optimized by the column store, and KEEPFILTERS keeps existing Color filters.`},{id:`c`,text:`SUMX(FILTER('Product', 'Product'[Color] = "Red"), [Sales])`,explain:`This iterates products and evaluates the measure per row, which is slower.`},{id:`d`,text:`IF(SELECTEDVALUE('Product'[Color]) = "Red", [Sales])`,explain:`This returns BLANK unless exactly Red is selected, which changes the result.`}],answer:`b`},{id:`SG-08`,machineId:Y,bulletIds:[`S2.2`],format:`single`,difficulty:1,placement:!0,stem:`A margin measure is written as IF([Sales] = 0, BLANK(), [Profit] / [Sales]). How should you rewrite it for better performance and safe division?`,sources:[t.bpDivide],options:[{id:`a`,text:`IFERROR([Profit] / [Sales], BLANK())`,explain:`IFERROR catches errors after they happen and isn’t the recommended pattern.`},{id:`b`,text:`DIVIDE([Profit], [Sales])`,explain:`Correct. DIVIDE handles zero or blank denominators and is better optimized than testing with IF.`},{id:`c`,text:`[Profit] / ([Sales] + 0)`,explain:`Adding zero doesn’t prevent division by zero.`},{id:`d`,text:`SUMX(Sales, [Profit] / [Sales])`,explain:`Row-by-row division changes the result and adds iteration.`}],answer:`b`},{id:`SG-09`,machineId:Y,bulletIds:[`S2.2`],format:`single`,difficulty:1,placement:!0,stem:`You need a measure that counts the rows in the Sales table. Which expression does Learn recommend?`,sources:[t.bpCountrows],options:[{id:`a`,text:`COUNT(Sales[OrderID])`,explain:`COUNT over a column works but is less efficient, and it skips blank values in that column.`},{id:`b`,text:`COUNTX(Sales, Sales[OrderID])`,explain:`COUNTX adds an iterator for no benefit.`},{id:`c`,text:`COUNTROWS(Sales)`,explain:`Correct. Learn recommends COUNTROWS to count table rows; it is more efficient.`},{id:`d`,text:`DISTINCTCOUNT(Sales[OrderID])`,explain:`This counts distinct values, which differs when an order has several lines.`}],answer:`c`},{id:`SG-10`,machineId:Y,bulletIds:[`S2.2`],format:`yesno`,difficulty:3,placement:!0,stem:`You are tuning DAX measures in a semantic model. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.bpFilter,t.varBP],statements:[{id:`s1`,text:`A Boolean filter argument in CALCULATE can compare a column to a measure, such as Sales[Amount] > [Average Amount].`,answer:!1,explain:`No. Boolean filter expressions can’t reference a measure or columns from several tables; use FILTER for those cases.`},{id:`s2`,text:`Storing a repeated sub-expression in a variable means it is evaluated once instead of several times.`,answer:!0,explain:`Yes. Learn’s variables article shows a YoY measure running in about half the time.`},{id:`s3`,text:`FILTER over a whole table is the most efficient way to filter a single column in CALCULATE.`,answer:!1,explain:`No. In-memory column stores are optimized for Boolean column filters.`}]},{id:`SG-11`,machineId:Y,bulletIds:[`S2.2`],format:`order`,difficulty:2,placement:!0,stem:`A visual is slow and you suspect one measure. Put the steps in order to diagnose and fix it.`,sources:[t.perfAnalyzer,t.daxQueryView],items:[{id:`i2`,text:`Copy the visual’s DAX query into DAX query view`,explain:`Second. The query lets you reproduce the slow request outside the report.`},{id:`i4`,text:`Use Update model to save the improved measure`,explain:`Last. Promote the faster DEFINE MEASURE into the model.`},{id:`i1`,text:`Record the page in Performance Analyzer and find the slow visual`,explain:`First. Measure before changing anything.`},{id:`i3`,text:`Rewrite the measure as a DEFINE MEASURE and run the query to check it`,explain:`Third. Test the new formula in the query without changing the model.`}],answerOrder:[`i1`,`i2`,`i3`,`i4`]},{id:`SG-12`,machineId:Y,bulletIds:[`S2.2`],format:`single`,difficulty:3,placement:!0,stem:`You need a measure that returns [Sales] only for months that achieved a profit, where profit is the [Profit] measure. You want to follow Learn’s guidance on filter arguments. Which expression should you use?`,sources:[t.bpFilter],options:[{id:`a`,text:`CALCULATE([Sales], [Profit] > 0)`,explain:`A Boolean filter argument can’t reference a measure.`},{id:`b`,text:`CALCULATE([Sales], KEEPFILTERS([Profit] > 0))`,explain:`KEEPFILTERS still wraps a Boolean expression, which can’t reference a measure.`},{id:`c`,text:`CALCULATE([Sales], FILTER(VALUES('Date'[Month]), [Profit] > 0))`,explain:`Correct. FILTER is needed here because the condition evaluates a measure for each month.`},{id:`d`,text:`CALCULATE([Sales], FILTER(ALL(Sales), [Profit] > 0))`,explain:`This iterates every fact row, removes all Sales filters, and tests profit per row rather than per month.`}],answer:`c`},{id:`DLS-01`,machineId:X,bulletIds:[`S2.3`],format:`single`,difficulty:2,trapPairId:`framing-vs-import-refresh`,stem:`A nightly ETL loads several Delta tables over two hours. Users of a Direct Lake model sometimes see half-loaded data. You need them to see only completed loads. What should you do?`,sources:[t.dlHow,t.directLake],options:[{id:`a`,text:`Switch the model to Import and refresh it hourly`,explain:`This gives up Direct Lake instead of controlling framing.`},{id:`b`,text:`Set DirectLakeBehavior to DirectQueryOnly`,explain:`DirectQuery always reads the latest data, including half-finished loads.`},{id:`c`,text:`Turn off automatic updates; refresh after the ETL`,explain:`Correct. Turning off automatic updates lets you frame the model only after the load completes.`},{id:`d`,text:`Enable the large semantic model storage format`,explain:`Storage format doesn’t control when the model reframes.`}],answer:`c`},{id:`DLS-02`,machineId:X,bulletIds:[`S2.3`],format:`single`,difficulty:2,trapPairId:`dl-fallback`,stem:`A Direct Lake on SQL model must never silently switch to DirectQuery in development, so problems are found early. Which DirectLakeBehavior setting should you use?`,sources:[t.dlHow,t.dlAnalyze],options:[{id:`a`,text:`Automatic`,explain:`Automatic is the default and falls back silently.`},{id:`b`,text:`DirectQueryOnly`,explain:`This forces every query to DirectQuery, for measuring fallback cost.`},{id:`c`,text:`Import`,explain:`Import isn’t a DirectLakeBehavior value.`},{id:`d`,text:`DirectLakeOnly`,explain:`Correct. Queries that can’t run in Direct Lake fail instead of falling back.`}],answer:`d`},{id:`DLS-03`,machineId:X,bulletIds:[`S2.3`],format:`multi`,difficulty:3,trapPairId:`dl-fallback`,stem:`A Direct Lake on SQL analytics endpoint model with DirectLakeBehavior set to Automatic sends some queries to DirectQuery. Which two conditions cause fallback? Choose two.`,sources:[t.dlHow,t.directLake],options:[{id:`a`,text:`A model table is based on a SQL view in the endpoint that isn’t materialized`,explain:`Correct. Views can only be read by falling back to DirectQuery.`},{id:`b`,text:`A table the model uses has row-level security defined in the SQL analytics endpoint`,explain:`Correct. SQL RLS on a table is a fallback condition.`},{id:`c`,text:`A column is loaded into memory for the first time`,explain:`First load is transcoding, a normal Direct Lake operation.`},{id:`d`,text:`The model includes a field parameter`,explain:`Field parameters are allowed calculated tables in Direct Lake on SQL models.`}],answers:[`a`,`b`]},{id:`DLS-04`,machineId:X,bulletIds:[`S2.3`],format:`yesno`,difficulty:2,stem:`You manage refresh for a Direct Lake semantic model. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.dlHow,t.directLake],statements:[{id:`s1`,text:`Data written to the Delta tables after the last framing is not visible to Direct Lake queries until the model is framed again.`,answer:!0,explain:`Yes. Framing fixes the point in time that queries see.`},{id:`s2`,text:`Automatic updates are off by default for new Direct Lake models.`,answer:!1,explain:`No. Keep your Direct Lake data up to date is on by default.`},{id:`s3`,text:`Power BI suspends automatic updates after a non-recoverable refresh error.`,answer:!0,explain:`Yes. They resume after a successful on-demand refresh.`}]},{id:`DLS-06`,machineId:X,bulletIds:[`S2.3`],format:`single`,difficulty:1,stem:`A user opens a Direct Lake report for the first time after framing. The first visuals are slightly slower; later ones are fast. What explains this?`,sources:[t.dlHow],options:[{id:`a`,text:`Columns are transcoded from OneLake into memory when first queried`,explain:`Correct. Columns load on first use and then stay resident in memory.`},{id:`b`,text:`Each first query falls back to DirectQuery by design`,explain:`Fallback only happens under specific conditions, not on first use.`},{id:`c`,text:`The model performs an Import refresh before the first query`,explain:`Direct Lake doesn’t import data at refresh.`},{id:`d`,text:`The SQL analytics endpoint builds indexes on first access`,explain:`Direct Lake reads Delta files directly; this isn’t the mechanism.`}],answer:`a`},{id:`DLS-07`,machineId:X,bulletIds:[`S2.3`],format:`single`,difficulty:2,stem:`You try to create a Direct Lake semantic model from a lakehouse in West Central US, with the model in a workspace in another region. What does Learn say?`,sources:[t.directLake,t.dlHow],options:[{id:`a`,text:`It works, but every query falls back to DirectQuery`,explain:`Region mismatch isn’t a fallback condition; the model must be in the same region.`},{id:`b`,text:`It works after you enable large semantic model storage format`,explain:`Storage format doesn’t change region requirements.`},{id:`c`,text:`The model and source must be in the same region`,explain:`Correct. Learn requires the same region; a shortcut in a lakehouse in the model’s region is the workaround.`},{id:`d`,text:`It works only with Direct Lake on SQL analytics endpoints`,explain:`The region requirement applies regardless of flavor.`}],answer:`c`},{id:`DLS-08`,machineId:X,bulletIds:[`S2.4`],format:`single`,difficulty:2,trapPairId:`dl-onelake-vs-sql`,stem:`A new Direct Lake model must combine Delta tables from two lakehouses and a KQL database that has OneLake availability turned on. Which Direct Lake option should you choose?`,sources:[t.directLake],options:[{id:`a`,text:`Direct Lake on SQL analytics endpoints`,explain:`This option uses a single Fabric source and doesn’t support KQL databases.`},{id:`b`,text:`Direct Lake on OneLake`,explain:`Correct. It can use Delta tables from one or more Fabric items, including KQL databases with OneLake availability.`},{id:`c`,text:`Either option, because both read any Delta table`,explain:`Only Direct Lake on OneLake supports several sources and KQL databases.`},{id:`d`,text:`Neither; KQL data needs a separate DirectQuery model`,explain:`Direct Lake on OneLake supports KQL databases with OneLake availability on.`}],answer:`b`},{id:`DLS-09`,machineId:X,bulletIds:[`S2.4`],format:`single`,difficulty:3,trapPairId:`dl-onelake-vs-sql`,stem:`A team must build a Direct Lake model on business logic that exists only as non-materialized SQL views in a warehouse, and they accept DirectQuery fallback for those views. Which option fits?`,sources:[t.directLake,t.dlHow],options:[{id:`a`,text:`Direct Lake on OneLake, pointing tables at the views`,explain:`You can’t build a Direct Lake on OneLake table on a non-materialized SQL view.`},{id:`b`,text:`Direct Lake on OneLake with DirectLakeBehavior set to Automatic`,explain:`On OneLake runs only as DirectLakeOnly and never falls back.`},{id:`c`,text:`Direct Lake on SQL analytics endpoints`,explain:`Correct. It can read SQL views by falling back to DirectQuery.`},{id:`d`,text:`Either option, after shortcuts to the views are created`,explain:`Shortcuts reference Delta data, not SQL view definitions.`}],answer:`c`},{id:`DLS-10`,machineId:X,bulletIds:[`S2.4`],format:`yesno`,difficulty:2,trapPairId:`dl-onelake-vs-sql`,stem:`You are comparing Direct Lake on OneLake with Direct Lake on SQL analytics endpoints. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.directLake,t.dlManage],statements:[{id:`s1`,text:`Direct Lake on OneLake never falls back to DirectQuery.`,answer:!0,explain:`Yes. It runs exclusively in DirectLakeOnly mode.`},{id:`s2`,text:`Direct Lake on SQL analytics endpoints can combine Delta tables from several Fabric items in one model.`,answer:!1,explain:`No. It uses a single Fabric source; multiple sources need Direct Lake on OneLake.`},{id:`s3`,text:`Direct Lake on OneLake checks permissions through the SQL analytics endpoint.`,answer:!1,explain:`No. Direct Lake on OneLake doesn’t use a SQL analytics endpoint to check permissions; it uses OneLake security, or Read and ReadAll on the item.`}]},{id:`DLS-11`,machineId:X,bulletIds:[`S2.4`],format:`single`,difficulty:3,trapPairId:`dl-onelake-vs-sql`,stem:`A Direct Lake on OneLake model has a table that exceeds the capacity guardrail for row groups. What happens?`,sources:[t.dlHow,t.directLake],options:[{id:`a`,text:`Refresh fails and the model can’t be queried until the table is optimized`,explain:`Correct. Direct Lake on OneLake behaves like Import over a guardrail: it doesn’t fall back.`},{id:`b`,text:`Queries fall back to DirectQuery and refresh succeeds with a warning`,explain:`That describes Direct Lake on SQL, not on OneLake.`},{id:`c`,text:`Only that table’s queries fall back to DirectQuery`,explain:`Direct Lake on OneLake never falls back.`},{id:`d`,text:`The table is automatically repartitioned during framing`,explain:`Framing reads metadata; it doesn’t optimize tables.`}],answer:`a`},{id:`DLS-12`,machineId:X,bulletIds:[`S2.4`],format:`single`,difficulty:1,trapPairId:`dl-onelake-vs-sql`,stem:`You are creating a brand-new Direct Lake semantic model with no special requirements for SQL views or SQL endpoint security. Which option does Learn recommend?`,sources:[t.directLake,t.dlHow],options:[{id:`a`,text:`Direct Lake on SQL analytics endpoints`,explain:`This option is for cases that need SQL views or SQL endpoint security and accept fallback.`},{id:`b`,text:`Import mode with incremental refresh`,explain:`This isn’t a Direct Lake option.`},{id:`c`,text:`DirectQuery to the SQL analytics endpoint`,explain:`This isn’t a Direct Lake option either.`},{id:`d`,text:`Direct Lake on OneLake`,explain:`Correct. Learn recommends Direct Lake on OneLake for new models.`}],answer:`d`},{id:`DLS-13`,machineId:X,bulletIds:[`S2.4`],format:`multi`,difficulty:2,trapPairId:`dl-onelake-vs-sql`,stem:`Which two requirements can be met only by Direct Lake on SQL analytics endpoints, not by Direct Lake on OneLake? Choose two.`,sources:[t.directLake,t.dlManage],options:[{id:`a`,text:`Add Import tables from Excel to the same model`,explain:`Only on OneLake can mix with Import tables; on SQL can’t mix modes.`},{id:`b`,text:`Read a KQL database with OneLake availability turned on`,explain:`Only on OneLake supports KQL databases.`},{id:`c`,text:`Use a SQL view in the SQL analytics endpoint as a model table`,explain:`Correct. On SQL can read SQL views by falling back to DirectQuery; Direct Lake on OneLake can’t use SQL views that aren’t materialized.`},{id:`d`,text:`Respect RLS defined in the SQL analytics endpoint by falling back to DirectQuery`,explain:`Correct. On SQL checks permissions through the endpoint and falls back for SQL RLS; on OneLake doesn’t check permissions through the endpoint.`}],answers:[`c`,`d`]},{id:`DLS-14`,machineId:X,bulletIds:[`S2.4`],format:`single`,difficulty:2,trapPairId:`dl-onelake-vs-sql`,stem:`Analysts using a Direct Lake on OneLake model get access errors, even though they have SELECT permission in the lakehouse’s SQL analytics endpoint. What do they need?`,sources:[t.directLake],options:[{id:`a`,text:`Access to the data in OneLake`,explain:`Correct. On OneLake reads the Delta files directly, so users need access to the OneLake data, not SQL endpoint permissions.`},{id:`b`,text:`Membership in a SQL endpoint database role`,explain:`SQL endpoint permissions aren’t used by Direct Lake on OneLake.`},{id:`c`,text:`DirectLakeBehavior set to DirectQueryOnly`,explain:`On OneLake doesn’t fall back, so this setting doesn’t apply.`},{id:`d`,text:`A Pro license in addition to the capacity`,explain:`The error is about data access, not licensing.`}],answer:`a`},{id:`BW-01`,machineId:Z,bulletIds:[`S2.5`],format:`single`,difficulty:1,stem:`You are setting up incremental refresh in Power BI Desktop. Which two parameter names must the date filter use?`,sources:[t.incremental,t.incrementalCfg],options:[{id:`a`,text:`StartDate and EndDate`,explain:`The names are reserved and specific; these aren’t them.`},{id:`b`,text:`rangestart and rangeend`,explain:`The names are case-sensitive.`},{id:`c`,text:`RangeStart and RangeEnd`,explain:`Correct. Reserved, case-sensitive Date/Time parameters that the service overrides per partition.`},{id:`d`,text:`WindowStart and WindowEnd`,explain:`These aren’t the reserved names.`}],answer:`c`},{id:`BW-02`,machineId:Z,bulletIds:[`S2.5`],format:`single`,difficulty:2,stem:`An incremental refresh filter uses [OrderDate] >= RangeStart and [OrderDate] <= RangeEnd. Some orders appear twice in the model. What should you change?`,sources:[t.incrementalCfg],options:[{id:`a`,text:`Use < RangeEnd instead of <= RangeEnd`,explain:`Correct. Equality on both sides puts boundary rows in two partitions.`},{id:`b`,text:`Use > RangeStart and > RangeEnd`,explain:`This drops the start boundary and loads rows after RangeEnd instead of before it.`},{id:`c`,text:`Turn on Detect data changes on OrderDate`,explain:`Detect data changes needs a different column and doesn’t fix overlap.`},{id:`d`,text:`Set the refresh period to one day`,explain:`Period length doesn’t fix overlapping filters.`}],answer:`a`},{id:`BW-03`,machineId:Z,bulletIds:[`S2.5`],format:`single`,difficulty:2,placement:!0,trapPairId:`archive-vs-refresh-period`,stem:`A policy must keep five years of sales history and reload only the last 10 days on each refresh. How should you configure it?`,sources:[t.incrementalCfg],options:[{id:`a`,text:`Archive data starting 10 days before; incrementally refresh 5 years before`,explain:`This swaps the two settings.`},{id:`b`,text:`Archive data starting 5 years before; incrementally refresh 10 days before`,explain:`Correct. The archive period keeps history; the refresh period is the window reloaded each time.`},{id:`c`,text:`Archive data starting 5 years before; turn on Only refresh complete days`,explain:`Complete days doesn’t define the 10-day refresh window.`},{id:`d`,text:`Incrementally refresh 5 years before; turn on Detect data changes`,explain:`This reloads five years of data each time.`}],answer:`b`},{id:`BW-04`,machineId:Z,bulletIds:[`S2.5`],format:`yesno`,difficulty:2,placement:!0,stem:`You published a semantic model with an incremental refresh policy to a Fabric capacity workspace. For each statement, select Yes if it is true. Otherwise, select No.`,sources:[t.incremental,t.incrementalCfg],statements:[{id:`s1`,text:`You can download the published model back to Power BI Desktop as a .pbix file.`,answer:!1,explain:`No. After incremental refresh partitions are created, the model can’t be downloaded as a .pbix.`},{id:`s2`,text:`The first refresh in the service creates the partitions defined by the policy.`,answer:!0,explain:`Yes. Publish, then run the first refresh to build the partitions.`},{id:`s3`,text:`If two tables have policies, each can use its own pair of range parameters.`,answer:!1,explain:`No. All tables with policies must use the same RangeStart and RangeEnd parameters.`}]},{id:`BW-05`,machineId:Z,bulletIds:[`S2.5`],format:`single`,difficulty:3,placement:!0,stem:`An Import fact table with incremental refresh reloads 30 days each night, but most days don’t change. The table has a LastUpdated audit column and a partitioning column, OrderDate. How can you refresh only periods that changed?`,sources:[t.incrementalCfg],options:[{id:`a`,text:`Turn on Detect data changes and choose OrderDate`,explain:`The column must differ from the one used for RangeStart and RangeEnd.`},{id:`b`,text:`Turn on Detect data changes and choose LastUpdated`,explain:`Correct. Only periods whose LastUpdated maximum changed are refreshed, and it differs from the partitioning column.`},{id:`c`,text:`Turn on Only refresh complete days`,explain:`This skips today’s partial day; it doesn’t detect changes.`},{id:`d`,text:`Shorten the archive period to 30 days`,explain:`That drops history instead of skipping unchanged periods.`}],answer:`b`},{id:`BW-06`,machineId:Z,bulletIds:[`S2.5`],format:`single`,difficulty:2,placement:!0,trapPairId:`dual-vs-hybrid`,stem:`Reports must show today’s orders in real time while history stays in Import. The model is in a Premium Per User workspace. Which incremental refresh option should you turn on?`,sources:[t.incremental,t.incrementalCfg,t.modes],options:[{id:`a`,text:`Only refresh complete days`,explain:`This excludes the current day instead of making it real time.`},{id:`b`,text:`Detect data changes`,explain:`This skips unchanged periods; it doesn’t add real-time data.`},{id:`c`,text:`Get the latest data in real time with DirectQuery`,explain:`Correct. It adds a DirectQuery partition for the newest data, making a hybrid table; PPU supports it.`},{id:`d`,text:`Large semantic model storage format`,explain:`Storage format affects size limits, not freshness.`}],answer:`c`},{id:`BW-07`,machineId:Z,bulletIds:[`S2.5`],format:`single`,difficulty:2,placement:!0,stem:`A team wants incremental refresh partitions on a Direct Lake model’s fact table to speed up refresh. What should you tell them?`,sources:[t.directLake,t.incremental],options:[{id:`a`,text:`Define RangeStart and RangeEnd on the Direct Lake table`,explain:`Direct Lake tables don’t use incremental refresh partitions.`},{id:`b`,text:`Switch on hybrid mode for the Direct Lake table`,explain:`Direct Lake doesn’t support hybrid tables.`},{id:`c`,text:`Use XMLA to add model partitions to the table`,explain:`Direct Lake doesn’t support model table partitions.`},{id:`d`,text:`Partition the Delta table instead, if needed`,explain:`Correct. Direct Lake refresh copies only metadata, and partitioning belongs at the Delta table level.`}],answer:`d`},{id:`BW-08`,machineId:Z,bulletIds:[`S2.5`],format:`order`,difficulty:2,placement:!0,stem:`You are implementing incremental refresh on an Import Sales table. Put the steps in order.`,sources:[t.incrementalCfg],items:[{id:`i3`,text:`Define the incremental refresh policy on the table`,explain:`Third. The policy uses the filtered table.`},{id:`i1`,text:`Create the RangeStart and RangeEnd parameters`,explain:`First. The filter needs the parameters.`},{id:`i4`,text:`Publish and run the first refresh in the service`,explain:`Last. The first refresh creates the partitions.`},{id:`i2`,text:`Filter the date column with >= RangeStart and < RangeEnd`,explain:`Second. The filter defines what each partition loads.`}],answerOrder:[`i1`,`i2`,`i3`,`i4`]},{id:`BW-09`,machineId:Z,bulletIds:[`S2.5`],format:`single`,difficulty:3,placement:!0,stem:`An incremental refresh policy on a source that doesn’t support query folding of the date filter refreshes much slower than expected. What is the most likely cause?`,sources:[t.incremental,t.incrementalCfg],options:[{id:`a`,text:`Each partition query reads all source rows`,explain:`Correct. Without folding, the RangeStart and RangeEnd filter can’t be pushed to the source.`},{id:`b`,text:`The archive period is longer than the refresh period`,explain:`That is the normal configuration.`},{id:`c`,text:`The model doesn’t use the large storage format`,explain:`Storage format doesn’t affect how filters reach the source.`},{id:`d`,text:`Detect data changes is turned off`,explain:`It’s optional and doesn’t explain full source scans.`}],answer:`a`},{id:`BW-10`,machineId:Z,bulletIds:[`S2.5`],format:`single`,difficulty:2,placement:!0,stem:`The source column for incremental refresh is an integer date key, OrderDateKey (yyyymmdd). RangeStart and RangeEnd must stay Date/Time. How should the filter work?`,sources:[t.incrementalCfg],options:[{id:`a`,text:`Change RangeStart and RangeEnd to Whole Number parameters`,explain:`The parameters must be Date/Time.`},{id:`b`,text:`Use Detect data changes on OrderDateKey instead of a filter`,explain:`A range filter is still required.`},{id:`c`,text:`Convert their values to yyyymmdd integers in the filter step`,explain:`Correct. Convert the Date/Time parameters to the same integer form before comparing.`},{id:`d`,text:`Incremental refresh can’t be used with integer keys`,explain:`Learn documents the integer key pattern.`}],answer:`c`}],be=[...ve,...ye,..._e,...pe],Q=[`a`,`b`,`c`,`d`,`e`];function xe(e){let t=0;return e.map(e=>{if(e.format!==`single`||e.options.length!==4)return e;let n=e.options.find(t=>t.id===e.answer);if(!n)return e;let r=e.options.filter(t=>t.id!==e.answer),i=t++%4,a=[...r.slice(0,i),n,...r.slice(i)].map((e,t)=>({...e,id:Q[t]}));return{...e,options:a,answer:Q[i]}})}var Se=e({allQuestions:()=>$,caseStudies:()=>u}),$=xe([...fe,...n,...be,...ce,...re]);export{Se as n,u as r,$ as t};